import Taro from '@tarojs/taro'
import { LOTTERY_LIST, type LotteryCode } from '@/constants/lottery'
import { STORAGE_KEYS } from '@/utils/storage'

/**
 * 跨工具一次性 payload 传递：写入 → 跳转 → 目标页读取即删（Web PRD §5.7）。
 * 读取即删语义参照 src/pages/tools/history-review/index.tsx。
 */

/** 允许用于跨工具传递的 storage key（STORAGE_KEYS 中的 *Payload 键值） */
export type ToolPayloadKey =
  | typeof STORAGE_KEYS.filterToolPayload
  | typeof STORAGE_KEYS.codeGroupExtensionPayload
  | typeof STORAGE_KEYS.historyReviewPayload
  | typeof STORAGE_KEYS.setProcessingPayload

/** 写入跨工具 payload（JSON 序列化） */
export async function writeToolPayload(key: ToolPayloadKey, data: unknown): Promise<void> {
  await Taro.setStorage({ key, data: JSON.stringify(data) })
}

/** 读取跨工具 payload：getStorage 成功后 removeStorage（读取即删），失败或 JSON 非法返回 null */
export async function readToolPayloadOnce<T>(key: ToolPayloadKey): Promise<T | null> {
  let raw = ''
  try {
    const res = await Taro.getStorage({ key })
    raw = String(res.data || '')
  } catch {
    return null
  }
  if (!raw) return null
  Taro.removeStorage({ key }).catch(() => {})
  try {
    return JSON.parse(raw) as T
  } catch {
    return null
  }
}

// ---------- 彩种 toolKey ↔ code 映射（LOTTERY_LIST 单一数据源） ----------

/** 工具内部键（pl5/qxc/fc3d）→ 彩种 code（350133/04/3d）；非法值返回 null */
export function toolKeyToCode(toolKey?: string | null): LotteryCode | null {
  const found = LOTTERY_LIST.find((item) => item.toolKey === String(toolKey || '').trim())
  return found ? found.code : null
}

/** 彩种 code（350133/04/3d）→ 工具内部键（pl5/qxc/fc3d）；非法值返回 null */
export function codeToToolKey(code?: string | null): string | null {
  const found = LOTTERY_LIST.find((item) => item.code === String(code || '').trim())
  return found ? found.toolKey : null
}
