/* SheetPopup RN 端样式（仅 index.rn.tsx 引入；H5 端由 NutUI Popup 渲染，不加载本文件） */
.sheet-popup {
  flex: 1;
  justify-content: flex-end;
}

.sheet-popup__mask {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background-color: rgba(0, 0, 0, 0.7);
}

.sheet-popup__panel {
  position: relative;
  max-height: 100%;
  background-color: var(--color-bg-card);
  border-top-left-radius: 12px;
  border-top-right-radius: 12px;
}

/* 弹层内容容器：panel 限高后可收缩，配合 ScrollView 让超长内容内部滚动 */
.sheet-popup__scroll {
  flex-shrink: 1;
}

.sheet-popup__close {
  position: absolute;
  top: 4px;
  right: 8px;
  z-index: 1;
  padding: 8px;
}
