import { useEffect, useMemo, useRef, useState } from 'react'
import { ScrollView, Text, Textarea, View } from '@tarojs/components'
import Taro from '@tarojs/taro'
import Popup from '@/components/SheetPopup'
import { LOTTERY_LIST } from '@/constants/lottery'
import { fetchHistoryReview } from '@/services/api'
import { filterLabels as labels } from '@/labels/tools'
import { navigateTo } from '@/utils/nav'
import { STORAGE_KEYS } from '@/utils/storage'
import { codeToToolKey, readToolPayloadOnce, toolKeyToCode, writeToolPayload } from '@/utils/tools/toolPayload'
import PopupCloseIcon from '@/components/PopupCloseIcon'
import {
  EVEN_DIGITS,
  LARGE_DIGITS,
  LOTTERY_RULES,
  MAX_FILTER_CANDIDATES,
  ODD_DIGITS,
  PLAN_NAMES,
  RESULT_PAGE_SIZE,
  SMALL_DIGITS,
  buildCopyText,
  buildHistoryExcludeCodes,
  cloneConditionState,
  cloneSteps,
  createAllDigitSelections,
  createInitialConditionState,
  createResultItem,
  createStepId,
  getInitialCandidateCodes,
  getPositionLabels,
  pickerCandidateCount,
  ratioLabel,
  runFilterOnce,
  validateHistoryExcludeCodes,
  type ConditionKind,
  type ConditionMode,
  type ConditionState,
  type FilterConditionSnapshot,
  type FilterLotteryType,
  type FilterPlan,
  type FilterStep,
  type ResultItem,
} from '@/utils/tools/filterEngine'
import { ConditionPopup, DigitGrid } from './conditions'
import { ResultPanel } from './result'
import './index.css'
/** 条件键 → 名称（源 conditions computed 的 label） */
const CONDITION_LABELS: Record<ConditionKind, string> = {
  position: labels.conditionPosition,
  sum: labels.conditionSum,
  sumTail: labels.conditionSumTail,
  difference: labels.conditionDifference,
  sizeParity: labels.dialogTitleSizeParity,
  size: labels.conditionSize,
  parity: labels.conditionParity,
  historyExclude: labels.conditionHistoryExclude,
}

/** 条件库展示顺序（源 condition-actions，sizeParity 为源遗留类型无入口） */
const CONDITION_KEYS: ConditionKind[] = ['position', 'sum', 'sumTail', 'difference', 'size', 'parity', 'historyExclude']

function toast(title: string) {
  Taro.showToast({ title, icon: 'none' })
}

function isFilterLotteryType(value: unknown): value is FilterLotteryType {
  return value === 'qxc' || value === 'pl5' || value === 'fc3d'
}

/** 筛选工具（移植自 lottery_web FilterToolEntry.vue；唯一 API：历史排除拉历史开奖） */
export default function FilterPage() {
  // 入口携带的彩种 code（如首页开奖卡「筛选」直达）→ 工具键，非法或缺省回落排列五
  const routeToolKey = codeToToolKey(Taro.getCurrentInstance().router?.params?.code)
  const initialLotteryType: FilterLotteryType = isFilterLotteryType(routeToolKey) ? routeToolKey : 'pl5'
  // 定数默认取该彩种最大可用定数（对齐 changeLottery 的回落规则）
  const availableCounts = LOTTERY_RULES[initialLotteryType].digitCounts
  const initialDigitCount = availableCounts[availableCounts.length - 1]

  const [lotteryType, setLotteryType] = useState<FilterLotteryType>(initialLotteryType)
  const [digitCount, setDigitCount] = useState(initialDigitCount)
  const [baseInput, setBaseInput] = useState('')
  const [baseSelectedDigits, setBaseSelectedDigits] = useState<number[][]>(() => createAllDigitSelections(initialDigitCount))
  const [cond, setCond] = useState<ConditionState>(() => createInitialConditionState(initialDigitCount))
  const [activeCondition, setActiveCondition] = useState<ConditionKind | null>(null)
  const [activeMode, setActiveMode] = useState<ConditionMode>('include')
  const [results, setResults] = useState<ResultItem[]>([])
  const [displayCount, setDisplayCount] = useState(RESULT_PAGE_SIZE)
  const [steps, setSteps] = useState<FilterStep[]>([])
  const [hasPendingFilterStep, setHasPendingFilterStep] = useState(false)
  const [editingFilterStepIndex, setEditingFilterStepIndex] = useState<number | null>(null)
  const [plans, setPlans] = useState<FilterPlan[]>([])
  const [activePlanId, setActivePlanId] = useState('')
  const [selectedPlanIds, setSelectedPlanIds] = useState<string[]>([])
  const [dialogVisible, setDialogVisible] = useState(false)
  const [dialogKind, setDialogKind] = useState<ConditionKind>('position')
  const [applying, setApplying] = useState(false)
  const [copyVisible, setCopyVisible] = useState(false)
  const [copySeparator, setCopySeparator] = useState<'comma' | 'space'>('space')
  const [copyPad, setCopyPad] = useState(false)
  const [copyPadPositions, setCopyPadPositions] = useState<number[]>([])
  /** 方案持久化：storage 读取完成前不覆盖写回 */
  const plansReady = useRef(false)

  const digitCounts = LOTTERY_RULES[lotteryType].digitCounts
  const positionLabels = getPositionLabels(digitCount)
  const activeResultCodes = useMemo(() => results.filter((item) => !item.deleted).map((item) => item.code), [results])

  // ---------- 方案持久化（源 persistFilterPlans 语义：filterPlans 整体 JSON 落盘） ----------
  useEffect(() => {
    if (!plansReady.current) return
    Taro.setStorage({ key: STORAGE_KEYS.filterToolPlans, data: JSON.stringify(plans) }).catch(() => {})
  }, [plans])

  // ---------- 通用状态迁移 ----------
  const clearResults = () => {
    setResults([])
    setDisplayCount(RESULT_PAGE_SIZE)
    setSteps([])
    setHasPendingFilterStep(false)
  }

  /** 重置条件编辑状态（源 resetCurrentConditionState） */
  const resetConditionState = () => {
    setCond(createInitialConditionState(digitCount))
    setActiveCondition(null)
    setActiveMode('include')
    setHasPendingFilterStep(false)
    setEditingFilterStepIndex(null)
  }

  /** 定数切换（源 watch(digitCount)）：注意源不清理大底文本 */
  const resetForDigit = (count: number) => {
    setDigitCount(count)
    setBaseSelectedDigits(createAllDigitSelections(count))
    setCond(createInitialConditionState(count))
    setActiveCondition(null)
    setActiveMode('include')
    setEditingFilterStepIndex(null)
    clearResults()
  }

  const changeLottery = (next: FilterLotteryType) => {
    if (next === lotteryType) return
    setLotteryType(next)
    // 源 watch(lotteryType)：当前定数不可用时回落到最大可用定数（连带触发定数重置）
    const available = LOTTERY_RULES[next].digitCounts
    if (!available.includes(digitCount)) resetForDigit(available[available.length - 1])
  }

  const changeDigit = (count: number) => {
    if (count === digitCount) return
    resetForDigit(count)
  }

  /** 恢复方案到工作区（源 restorePlan；本端方案必含 resultCodes，省去源的 legacy 重跑分支） */
  const applyPlan = (plan: FilterPlan) => {
    setLotteryType(plan.lotteryType)
    setDigitCount(plan.digitCount)
    setBaseInput(plan.baseInput)
    setBaseSelectedDigits(plan.baseSelectedDigits.map((item) => [...item]))
    setCond(createInitialConditionState(plan.digitCount))
    setActiveCondition(null)
    setActiveMode('include')
    setHasPendingFilterStep(false)
    setEditingFilterStepIndex(null)
    setSteps(Array.isArray(plan.filterSteps) ? cloneSteps(plan.filterSteps) : [])
    setResults(
      (Array.isArray(plan.resultCodes) ? plan.resultCodes : [])
        .filter((code) => new RegExp(`^\\d{${plan.digitCount}}$`).test(code))
        .map(createResultItem),
    )
    setDisplayCount(RESULT_PAGE_SIZE)
    setActivePlanId(plan.id)
  }

  // ---------- 入站：跨工具 payload 优先，其次恢复持久化方案（源 onMounted） ----------
  useEffect(() => {
    void (async () => {
      const payload = await readToolPayloadOnce<{ lotteryType?: string; digitCount?: number; codes?: string[] }>(
        STORAGE_KEYS.filterToolPayload,
      )
      if (payload) {
        const type = isFilterLotteryType(payload.lotteryType) ? payload.lotteryType : null
        const digit = Number(payload.digitCount)
        const valid =
          type !== null &&
          LOTTERY_RULES[type].digitCounts.includes(digit) &&
          Array.isArray(payload.codes) &&
          payload.codes.length > 0 &&
          payload.codes.every((code) => new RegExp(`^\\d{${digit}}$`).test(code))
        if (!type || !valid) {
          toast(labels.errors.payloadInvalid)
        } else {
          setLotteryType(type)
          resetForDigit(digit)
          setBaseInput([...new Set(payload.codes!)].join(' '))
          plansReady.current = true
          return
        }
      }
      try {
        const res = await Taro.getStorage({ key: STORAGE_KEYS.filterToolPlans })
        const saved = JSON.parse(String(res.data || '[]')) as FilterPlan[]
        if (Array.isArray(saved) && saved.length) {
          const normalized = saved.slice(-10).map((plan, index) => ({ ...plan, name: PLAN_NAMES[index] }))
          setPlans(normalized)
          const latest = normalized[normalized.length - 1]
          if (latest) applyPlan(latest)
        }
      } catch {
        Taro.removeStorage({ key: STORAGE_KEYS.filterToolPlans }).catch(() => {})
      }
      plansReady.current = true
    })()
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  // ---------- 逐位选号 ----------
  const togglePickerDigit = (position: number, digit: number) => {
    setBaseSelectedDigits(
      baseSelectedDigits.map((selected, index) =>
        index === position
          ? selected.includes(digit)
            ? selected.filter((item) => item !== digit)
            : [...selected, digit].sort((a, b) => a - b)
          : selected,
      ),
    )
  }

  const setPickerDigits = (position: number, values: number[]) => {
    setBaseSelectedDigits(baseSelectedDigits.map((selected, index) => (index === position ? [...values] : selected)))
  }

  // ---------- 条件 ----------
  /** 条件摘要（源 conditions computed 各项 summary） */
  const conditionSummary = (kind: ConditionKind, state: ConditionState): string => {
    switch (kind) {
      case 'position': {
        const summary = state.positionSelections
          .map((selected, index) => (selected.length ? `${positionLabels[index]}${selected.join('')}` : ''))
          .filter(Boolean)
          .join(' ')
        return summary || labels.conditionSet
      }
      case 'sum': {
        // 源展示 sumSelections（base 模式）；本端展示当前 N 定和实际选中值，信息更完整
        const values =
          state.activeSumMode === 'base' ? state.sumSelections : state.sumGroupSelections[state.activeSumMode] || []
        return values.join('、')
      }
      case 'sumTail': {
        const values =
          state.activeSumTailMode === 'base'
            ? state.sumTailSelections
            : state.sumTailGroupSelections[state.activeSumTailMode] || []
        return values.join('、')
      }
      case 'difference':
        return labels.conditionSet
      case 'size':
        return state.sizeCountSelections.map((value) => ratioLabel(value, digitCount)).join('、') || labels.conditionSet
      case 'parity':
        return (
          state.parityCountSelections.map((value) => ratioLabel(value, digitCount)).join('、') || labels.conditionSet
        )
      case 'historyExclude':
        return state.historyExcludeCodes.length
          ? state.historyExcludeMode === 'draws'
            ? `${labels.drawShort} / ${state.historyExcludePositions.length}定 / ${state.historyExcludePeriod}期`
            : `${labels.historyCodesSection} / ${state.historyExcludePositions.length}定 / ${state.historyExcludeCodes.length}组`
          : labels.conditionSet
      default:
        return labels.conditionSet
    }
  }

  const openCondition = (kind: ConditionKind) => {
    setDialogKind(kind)
    setDialogVisible(true)
  }

  /** 取消：关闭弹层并重置条件编辑状态（源 cancelConditionDialog） */
  const cancelConditionDialog = () => {
    setDialogVisible(false)
    resetConditionState()
  }

  /** 确定 / 排除（源 applyConditionMode：校验 → 只保留当前条件字段 → 标记待执行） */
  const applyConditionMode = async (mode: ConditionMode) => {
    const kind = dialogKind
    let nextCond = cond
    if (kind === 'historyExclude') {
      if (cond.historyExcludePositions.length < 2) {
        toast(labels.errors.historyExcludeMinPositions)
        return
      }
      const length = cond.historyExcludePositions.length
      if (cond.historyExcludeMode === 'codes') {
        const validation = validateHistoryExcludeCodes(cond.historyExcludeInput, length)
        if (!validation.ok) {
          toast(
            validation.error === 'invalid'
              ? labels.errors.historyExcludeInvalidCode(length, validation.invalid || '')
              : labels.errors.historyExcludeEmpty,
          )
          return
        }
        nextCond = { ...cond, historyExcludeCodes: validation.codes }
      } else {
        const lotteryCode = toolKeyToCode(lotteryType)
        if (!lotteryCode) return
        setApplying(true)
        try {
          const res = await fetchHistoryReview({ lotteryCode, count: cond.historyExcludePeriod })
          if (res?.message) {
            toast(labels.errors.historyExcludeFailed)
            return
          }
          nextCond = {
            ...cond,
            historyExcludeCodes: buildHistoryExcludeCodes(
              (res?.rows || []).map((row) => row.result),
              cond.historyExcludePositions,
              length,
            ),
          }
        } catch {
          toast(labels.errors.historyExcludeFailed)
          return
        } finally {
          setApplying(false)
        }
      }
    }
    const sumDigitCount = cond.activeSumMode === 'base' ? digitCount : Number(cond.activeSumMode)
    if (kind === 'sum' && cond.activeSumMode !== 'base' && !cond.sumUseAnyPositions && cond.sumSelectedPositions.length !== sumDigitCount) {
      toast(labels.errors.sumPositionsRequired(sumDigitCount))
      return
    }
    const sumTailDigitCount = cond.activeSumTailMode === 'base' ? digitCount : Number(cond.activeSumTailMode)
    if (
      kind === 'sumTail' &&
      cond.activeSumTailMode !== 'base' &&
      !cond.sumTailUseAnyPositions &&
      cond.sumTailSelectedPositions.length !== sumTailDigitCount
    ) {
      toast(labels.errors.sumTailPositionsRequired(sumTailDigitCount))
      return
    }
    // 只保留当前条件字段，其余条件回到初始态（源 applyConditionMode 的逐字段重置）
    const fresh = createInitialConditionState(digitCount)
    setCond({
      ...fresh,
      positionSelections: kind === 'position' ? nextCond.positionSelections : fresh.positionSelections,
      sumSelections: kind === 'sum' ? nextCond.sumSelections : [],
      sumGroupSelections: kind === 'sum' ? nextCond.sumGroupSelections : {},
      activeSumMode: kind === 'sum' ? nextCond.activeSumMode : fresh.activeSumMode,
      sumSelectedPositions: kind === 'sum' ? nextCond.sumSelectedPositions : fresh.sumSelectedPositions,
      sumUseAnyPositions: kind === 'sum' ? nextCond.sumUseAnyPositions : false,
      sumTailSelections: kind === 'sumTail' ? nextCond.sumTailSelections : [],
      sumTailGroupSelections: kind === 'sumTail' ? nextCond.sumTailGroupSelections : {},
      activeSumTailMode: kind === 'sumTail' ? nextCond.activeSumTailMode : fresh.activeSumTailMode,
      sumTailSelectedPositions: kind === 'sumTail' ? nextCond.sumTailSelectedPositions : fresh.sumTailSelectedPositions,
      sumTailUseAnyPositions: kind === 'sumTail' ? nextCond.sumTailUseAnyPositions : false,
      differenceSelections: kind === 'difference' ? nextCond.differenceSelections : {},
      activeDifferencePair: kind === 'difference' ? nextCond.activeDifferencePair : 'any',
      sizeCountSelections: kind === 'size' ? nextCond.sizeCountSelections : [],
      parityCountSelections: kind === 'parity' ? nextCond.parityCountSelections : [],
      historyExcludePositions: kind === 'historyExclude' ? nextCond.historyExcludePositions : [],
      historyExcludeInput: kind === 'historyExclude' ? nextCond.historyExcludeInput : '',
      // 源 applyConditionMode 不重置回查期数，保留用户选择
      historyExcludePeriod: nextCond.historyExcludePeriod,
      historyExcludeMode: kind === 'historyExclude' ? nextCond.historyExcludeMode : 'codes',
      historyExcludeCodes: kind === 'historyExclude' ? nextCond.historyExcludeCodes : [],
    })
    setActiveCondition(kind)
    // 历史排除无论点哪个按钮都是排除语义（源 conditionModes[kind] = 'exclude'）
    setActiveMode(kind === 'historyExclude' ? 'exclude' : mode)
    setHasPendingFilterStep(true)
    setDialogVisible(false)
  }

  // ---------- 多步过滤链 ----------
  const buildStep = (inputCodes: string[], outputCount: number): FilterStep | null => {
    if (!activeCondition) return null
    const summary = conditionSummary(activeCondition, cond)
    const snapshot: FilterConditionSnapshot = {
      ...cloneConditionState(cond),
      kind: activeCondition,
      mode: activeMode,
    }
    return {
      id: createStepId(),
      label: CONDITION_LABELS[activeCondition],
      summary: `${activeMode === 'exclude' ? labels.dialogExclude : labels.keepPrefix}：${summary || labels.conditionSet}`,
      condition: snapshot,
      inputCodes: [...inputCodes],
      inputCount: inputCodes.length,
      outputCount,
    }
  }

  /** 编辑步骤：恢复该步条件到弹层（源 editFilterStep + restoreConditionSnapshot） */
  const editFilterStep = (index: number) => {
    const step = steps[index]
    if (!step) return
    const snapshot = cloneConditionState(step.condition) as FilterConditionSnapshot
    const { kind, mode, ...condState } = snapshot
    void mode
    setCond(condState)
    setActiveCondition(null)
    setHasPendingFilterStep(false)
    setEditingFilterStepIndex(index)
    setDialogKind(kind)
    setDialogVisible(true)
  }

  /** 删除步骤并回退到该步输入（源 removeFilterStep） */
  const removeFilterStep = (index: number) => {
    const step = steps[index]
    if (!step) return
    setResults(step.inputCodes.map(createResultItem))
    setSteps(steps.slice(0, index))
    resetConditionState()
    setDisplayCount(RESULT_PAGE_SIZE)
  }

  // ---------- 执行筛选（源 runFilter savePlan=true 路径） ----------
  const runFilter = () => {
    if (!plans.some((plan) => plan.id === activePlanId)) {
      toast(labels.errors.planRequired)
      return
    }
    const editingStep = editingFilterStepIndex === null ? null : steps[editingFilterStepIndex] || null
    const isFollowUp = steps.length > 0 && !editingStep
    if (isFollowUp && !hasPendingFilterStep) {
      toast(labels.errors.stepConditionRequired)
      return
    }
    let candidates: string[]
    if (editingStep) {
      candidates = [...editingStep.inputCodes]
    } else if (isFollowUp) {
      candidates = activeResultCodes
    } else {
      // 移动端性能保护：逐位选号先估算笛卡尔积注数，避免展开超大候选集
      if (!baseInput.trim() && pickerCandidateCount(baseSelectedDigits) > MAX_FILTER_CANDIDATES) {
        toast(labels.errors.tooManyCandidates(MAX_FILTER_CANDIDATES))
        return
      }
      candidates = getInitialCandidateCodes(baseInput, baseSelectedDigits, digitCount)
      if (candidates.length > MAX_FILTER_CANDIDATES) {
        toast(labels.errors.tooManyCandidates(MAX_FILTER_CANDIDATES))
        return
      }
    }
    const nextResults = runFilterOnce(candidates, cond, activeCondition, activeMode, digitCount)
    const step = buildStep(candidates, nextResults.length)
    const nextSteps = step
      ? editingStep
        ? [...steps.slice(0, editingFilterStepIndex as number), step]
        : [...steps, step]
      : steps
    setResults(nextResults)
    setDisplayCount(RESULT_PAGE_SIZE)
    setSteps(nextSteps)
    // 先保存方案（含本次条件快照与结果），再重置条件编辑状态（源 runFilter 顺序）
    const snapshot: FilterPlan = {
      id: '',
      name: '',
      lotteryType,
      digitCount,
      baseInput,
      baseSelectedDigits: baseSelectedDigits.map((item) => [...item]),
      condition: cloneConditionState(cond),
      activeCondition,
      activeMode,
      filterSteps: cloneSteps(nextSteps),
      resultCodes: nextResults.filter((item) => !item.deleted).map((item) => item.code),
    }
    setPlans(plans.map((plan) => (plan.id === activePlanId ? { ...snapshot, id: plan.id, name: plan.name } : plan)))
    resetConditionState()
  }

  /** 重设方案（源 resetFilters） */
  const resetFilters = () => {
    setBaseInput('')
    setBaseSelectedDigits(createAllDigitSelections(digitCount))
    resetConditionState()
    clearResults()
  }

  /** 新建方案（源 createNewPlan：重设后追加快照，上限 10 个并重新命名） */
  const createNewPlan = () => {
    const freshCond = createInitialConditionState(digitCount)
    const freshPicker = createAllDigitSelections(digitCount)
    setBaseInput('')
    setBaseSelectedDigits(freshPicker)
    setCond(freshCond)
    setActiveCondition(null)
    setActiveMode('include')
    setEditingFilterStepIndex(null)
    clearResults()
    const plan: FilterPlan = {
      id: createStepId(),
      name: '',
      lotteryType,
      digitCount,
      baseInput: '',
      baseSelectedDigits: freshPicker,
      condition: freshCond,
      activeCondition: null,
      activeMode: 'include',
      filterSteps: [],
      resultCodes: [],
    }
    const nextPlans = [...plans, plan].slice(-10).map((item, index) => ({ ...item, name: PLAN_NAMES[index] }))
    setPlans(nextPlans)
    setActivePlanId(nextPlans[nextPlans.length - 1]?.id || '')
    setSelectedPlanIds([])
  }

  /** 关闭方案（源 closePlan：剩余方案重命名，关闭当前方案时切换/清空） */
  const closePlan = (planId: string) => {
    const index = plans.findIndex((plan) => plan.id === planId)
    if (index < 0) return
    const remaining = plans.filter((plan) => plan.id !== planId).map((plan, itemIndex) => ({ ...plan, name: PLAN_NAMES[itemIndex] }))
    const wasActive = activePlanId === planId
    setPlans(remaining)
    setSelectedPlanIds(selectedPlanIds.filter((id) => id !== planId))
    if (!wasActive) return
    const nextPlan = remaining[Math.min(index, remaining.length - 1)]
    if (nextPlan) {
      applyPlan(nextPlan)
    } else {
      setActivePlanId('')
      clearResults()
    }
  }

  /** 勾选方案（源 togglePlanSelection：最多 2 组；勾选当前方案前回写其结果） */
  const togglePlanSelection = (planId: string) => {
    const checked = !selectedPlanIds.includes(planId)
    if (checked && selectedPlanIds.length >= 2) {
      toast(labels.errors.planSelectionMax)
      return
    }
    if (checked && planId === activePlanId) {
      setPlans(
        plans.map((plan) =>
          plan.id === activePlanId ? { ...plan, resultCodes: [...activeResultCodes], filterSteps: cloneSteps(steps) } : plan,
        ),
      )
    }
    setSelectedPlanIds(
      checked ? [...new Set([...selectedPlanIds, planId])] : selectedPlanIds.filter((id) => id !== planId),
    )
  }

  const restorePlan = (planId: string) => {
    const plan = plans.find((item) => item.id === planId)
    if (!plan || planId === activePlanId) return
    applyPlan(plan)
  }

  // ---------- 出站联动（源 goToPlanExtension / goToSetProcessing / goToHistoryReview） ----------
  const collectSelectedGroups = (mixedError: string): { firstPlan: FilterPlan; groups: string[][] } | null => {
    const selectedPlans = selectedPlanIds
      .map((id) => plans.find((plan) => plan.id === id))
      .filter((plan): plan is FilterPlan => Boolean(plan))
    if (!selectedPlans.length) {
      toast(labels.errors.planSelectionRequired)
      return null
    }
    const firstPlan = selectedPlans[0]
    if (
      selectedPlans.some((plan) => plan.lotteryType !== firstPlan.lotteryType || plan.digitCount !== firstPlan.digitCount)
    ) {
      toast(mixedError)
      return null
    }
    const groups = selectedPlans.map((plan) =>
      plan.resultCodes?.length ? plan.resultCodes : plan.id === activePlanId ? activeResultCodes : [],
    )
    if (groups.some((group) => !group.length)) {
      toast(labels.errors.planNoResult)
      return null
    }
    return { firstPlan, groups }
  }

  const goToPlanExtension = async () => {
    const collected = collectSelectedGroups(labels.errors.extensionMixed)
    if (!collected) return
    await writeToolPayload(STORAGE_KEYS.codeGroupExtensionPayload, {
      lotteryType: collected.firstPlan.lotteryType,
      digitCount: collected.firstPlan.digitCount,
      groups: collected.groups,
    })
    navigateTo({ url: '/pages/tools/code-group-extension/index' })
  }

  const goToSetProcessing = async () => {
    const collected = collectSelectedGroups(labels.errors.setProcessingMixed)
    if (!collected) return
    await writeToolPayload(STORAGE_KEYS.setProcessingPayload, {
      lotteryType: collected.firstPlan.lotteryType,
      groups: collected.groups,
    })
    navigateTo({ url: '/pages/tools/set-processing/index' })
  }

  const goToHistoryReview = async () => {
    const collected = collectSelectedGroups(labels.errors.historyReviewMixed)
    if (!collected) return
    await writeToolPayload(STORAGE_KEYS.historyReviewPayload, {
      lotteryType: collected.firstPlan.lotteryType,
      digitCount: collected.firstPlan.digitCount,
      codes: [...new Set(collected.groups.flat())],
    })
    navigateTo({ url: '/pages/tools/history-review/index' })
  }

  // ---------- 复制弹层 ----------
  const copyTargetLength = lotteryType === 'fc3d' ? 3 : 4
  const copyPadSourceLength = activeResultCodes[0]?.length ?? 0
  const copyPadCanApply = activeResultCodes.every((code) => code.length === copyPadSourceLength)
  const copyPadRequiredCount = copyPadCanApply ? Math.max(0, copyTargetLength - copyPadSourceLength) : 0

  const displayedCopyText = useMemo(
    () =>
      buildCopyText(
        activeResultCodes,
        copySeparator,
        copyPad,
        copyTargetLength,
        copyPadPositions,
        copyPadRequiredCount,
        copyPadCanApply,
      ),
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [activeResultCodes, copySeparator, copyPad, copyPadPositions, copyTargetLength, copyPadRequiredCount, copyPadCanApply],
  )

  const openCopyModal = () => {
    if (!activeResultCodes.length) return
    setCopyPadPositions(Array.from({ length: copyPadRequiredCount }, (_, index) => index))
    setCopyVisible(true)
  }

  const toggleCopyPadPosition = (position: number) => {
    if (copyPadPositions.includes(position)) {
      setCopyPadPositions(copyPadPositions.filter((item) => item !== position))
    } else if (copyPadPositions.length < copyPadRequiredCount) {
      setCopyPadPositions([...copyPadPositions, position])
    }
  }

  /** 补位校验（源 canCopyWithPad） */
  const canCopyWithPad = (): boolean => {
    if (!copyPad) return true
    if (!copyPadCanApply) {
      toast(labels.errors.padMixedLength)
      return false
    }
    if (copyPadPositions.length !== copyPadRequiredCount) {
      toast(labels.errors.padPositionsRequired(copyPadRequiredCount))
      return false
    }
    return true
  }

  const copyDisplayedText = async () => {
    if (!displayedCopyText || !canCopyWithPad()) return
    try {
      await Taro.setClipboardData({ data: displayedCopyText })
      setCopyVisible(false)
      toast(labels.copied(activeResultCodes.length))
    } catch {
      toast(labels.errors.copyFailed)
    }
  }

  /** 下载 txt：仅 H5（Blob + a[download]，动态创建 DOM 仅限该分支，RN 不渲染入口） */
  const downloadDisplayedText = () => {
    if (process.env.TARO_ENV !== 'h5' || !displayedCopyText || !canCopyWithPad()) return
    const blob = new Blob([displayedCopyText], { type: 'text/plain;charset=utf-8' })
    const link = document.createElement('a')
    link.href = URL.createObjectURL(blob)
    link.download = `${lotteryType}_筛选号码_${new Date().toISOString().slice(0, 10)}.txt`
    link.click()
    URL.revokeObjectURL(link.href)
    setCopyVisible(false)
  }

  const basePlaceholder = '01234，12345，…'.slice(0, digitCount + 1)

  const pickerQuickActions = (position: number) => [
    { text: labels.quickAll, onClick: () => setPickerDigits(position, [...Array.from({ length: 10 }, (_, i) => i)]) },
    { text: labels.quickClear, onClick: () => setPickerDigits(position, []) },
    { text: labels.quickLarge, onClick: () => setPickerDigits(position, [...LARGE_DIGITS]) },
    { text: labels.quickSmall, onClick: () => setPickerDigits(position, [...SMALL_DIGITS]) },
    { text: labels.quickOdd, onClick: () => setPickerDigits(position, [...ODD_DIGITS]) },
    { text: labels.quickEven, onClick: () => setPickerDigits(position, [...EVEN_DIGITS]) },
  ]

  return (
    <View className='ft-page'>
      {/* 彩种 + 定数 + 大底 */}
      <View className='ft-card'>
        <Text className='ft-label'>{labels.lotterySection}</Text>
        <View className='chips'>
          {LOTTERY_LIST.map((item) => {
            const active = item.toolKey === lotteryType
            return (
              <View
                key={item.code}
                className={`chip${active ? ' chip--active' : ''}`}
                onClick={() => isFilterLotteryType(item.toolKey) && changeLottery(item.toolKey)}
              >
                <Text className={`chip__text${active ? ' chip__text--active' : ''}`}>{item.label}</Text>
              </View>
            )
          })}
        </View>

        <View className='chips'>
          {digitCounts.map((count) => {
            const active = count === digitCount
            return (
              <View key={count} className={`chip${active ? ' chip--active' : ''}`} onClick={() => changeDigit(count)}>
                <Text className={`chip__text${active ? ' chip__text--active' : ''}`}>{labels.digitTab(count)}</Text>
              </View>
            )
          })}
        </View>

        <View className='ft-label-row'>
          <Text className='ft-label'>{labels.baseSection}</Text>
          <Text className='ft-hint'>{labels.baseHint}</Text>
        </View>
        <Textarea
          className='ft-textarea'
          value={baseInput}
          placeholder={labels.basePlaceholder(digitCount, basePlaceholder)}
          maxlength={-1}
          onInput={(e) => setBaseInput(e.detail.value)}
        />
      </View>

      {/* 逐位选号 */}
      <View className='ft-card'>
        <View className='ft-label-row'>
          <Text className='ft-label'>{labels.pickerSection}</Text>
          <Text className='ft-hint'>{labels.pickerHint}</Text>
        </View>
        {positionLabels.map((position, index) => (
          <View key={position} className='ft-position-block'>
            <Text className='ft-position-block__name'>{position}</Text>
            <DigitGrid selected={baseSelectedDigits[index] || []} onToggle={(digit) => togglePickerDigit(index, digit)} />
            <View className='chips ft-toolbar'>
              {pickerQuickActions(index).map((action) => (
                <View key={action.text} className='chip chip--small' onClick={action.onClick}>
                  <Text className='chip__text'>{action.text}</Text>
                </View>
              ))}
            </View>
          </View>
        ))}
      </View>

      {/* 筛选条件 */}
      <View className='ft-card'>
        <Text className='ft-label'>{labels.conditionSection}</Text>
        <View className='ft-conditions'>
          {CONDITION_KEYS.map((key) => {
            const active = activeCondition === key
            return (
              <View
                key={key}
                className={`ft-condition${active ? ' ft-condition--active' : ''}`}
                onClick={() => openCondition(key)}
              >
                <Text className={`ft-condition__label${active ? ' ft-condition__label--active' : ''}`}>
                  {CONDITION_LABELS[key]}
                </Text>
                {active ? (
                  <Text className='ft-condition__summary'>{conditionSummary(key, cond) || labels.conditionSet}</Text>
                ) : null}
              </View>
            )
          })}
        </View>

        <View className='ft-label-row'>
          <Text className='ft-label'>{labels.stepsTitle}</Text>
          {steps.length ? <Text className='ft-hint'>{labels.stepsCount(steps.length)}</Text> : null}
        </View>
        {steps.length ? (
          steps.map((step, index) => (
            <View key={step.id} className={`ft-step${index === steps.length - 1 ? ' ft-step--current' : ''}`}>
              <View className='ft-step__main'>
                <Text className='ft-step__label'>{`【${index + 1}】${step.label}`}</Text>
                <Text className='ft-step__summary'>{step.summary}</Text>
                <Text className='ft-step__flow'>{labels.stepFlow(step.inputCount, step.outputCount)}</Text>
              </View>
              <View className='ft-step__ops'>
                <Text className='ft-link' onClick={() => editFilterStep(index)}>
                  {labels.stepEdit}
                </Text>
                <Text className='ft-link ft-link--danger' onClick={() => removeFilterStep(index)}>
                  {labels.stepRemove}
                </Text>
              </View>
            </View>
          ))
        ) : (
          <Text className='ft-hint'>{labels.stepsEmpty}</Text>
        )}

        <View className='ft-actions'>
          <View className='ft-btn ft-btn--plain' onClick={createNewPlan}>
            <Text className='ft-btn__text ft-btn__text--plain'>{labels.newPlan}</Text>
          </View>
          <View className='ft-btn ft-btn--plain' onClick={resetFilters}>
            <Text className='ft-btn__text ft-btn__text--plain'>{labels.resetPlan}</Text>
          </View>
          <View className='ft-btn' onClick={runFilter}>
            <Text className='ft-btn__text'>{labels.runFilter}</Text>
          </View>
        </View>
      </View>

      {/* 结果面板 */}
      <ResultPanel
        plans={plans}
        activePlanId={activePlanId}
        selectedPlanIds={selectedPlanIds}
        onSwitchPlan={restorePlan}
        onToggleSelect={togglePlanSelection}
        onClosePlan={closePlan}
        results={results}
        displayCount={displayCount}
        onLoadMore={() => setDisplayCount(displayCount + RESULT_PAGE_SIZE)}
        onToggleDeleted={(index) =>
          setResults(results.map((item, i) => (i === index ? { ...item, deleted: !item.deleted } : item)))
        }
        onGoExtension={() => void goToPlanExtension()}
        onGoSetProcessing={() => void goToSetProcessing()}
        onGoHistoryReview={() => void goToHistoryReview()}
        onOpenCopy={openCopyModal}
        copyDisabled={activeResultCodes.length === 0}
      />

      {/* 条件配置弹层 */}
      <ConditionPopup
        visible={dialogVisible}
        kind={dialogKind}
        digitCount={digitCount}
        cond={cond}
        setCond={setCond}
        applying={applying}
        onCancel={cancelConditionDialog}
        onMaskClose={() => setDialogVisible(false)}
        onApply={(mode) => void applyConditionMode(mode)}
      />

      {/* 复制弹层 */}
      <Popup visible={copyVisible} closeable closeIcon={<PopupCloseIcon />} onClose={() => setCopyVisible(false)}>
        <View className='ft-sheet'>
          <Text className='ft-sheet__title'>{labels.copyModalTitle}</Text>
          <ScrollView scrollY className='ft-copy-preview'>
            <Text className='ft-copy-preview__text'>{displayedCopyText}</Text>
          </ScrollView>
          <View className='chips ft-toolbar'>
            {(['comma', 'space'] as const).map((item) => {
              const active = copySeparator === item
              return (
                <View
                  key={item}
                  className={`chip${active ? ' chip--active' : ''}`}
                  onClick={() => setCopySeparator(item)}
                >
                  <Text className={`chip__text${active ? ' chip__text--active' : ''}`}>
                    {item === 'comma' ? labels.separatorComma : labels.separatorSpace}
                  </Text>
                </View>
              )
            })}
            {[true, false].map((item) => {
              const active = copyPad === item
              return (
                <View
                  key={String(item)}
                  className={`chip${active ? ' chip--active' : ''}`}
                  onClick={() => setCopyPad(item)}
                >
                  <Text className={`chip__text${active ? ' chip__text--active' : ''}`}>
                    {item ? labels.pad : labels.noPad}
                  </Text>
                </View>
              )
            })}
          </View>
          {copyPad && copyPadRequiredCount > 0 ? (
            <>
              <Text className='ft-hint'>{labels.padPositionsTitle(copyPadPositions.length, copyPadRequiredCount)}</Text>
              <View className='chips'>
                {Array.from({ length: copyTargetLength }, (_, index) => {
                  const active = copyPadPositions.includes(index)
                  const disabled = !active && copyPadPositions.length >= copyPadRequiredCount
                  return (
                    <View
                      key={index}
                      className={`chip${active ? ' chip--active' : ''}${disabled ? ' chip--disabled' : ''}`}
                      onClick={() => toggleCopyPadPosition(index)}
                    >
                      <Text className={`chip__text${active ? ' chip__text--active' : ''}`}>
                        {labels.padPositionItem(index + 1)}
                      </Text>
                    </View>
                  )
                })}
              </View>
            </>
          ) : null}
          {copyPad && !copyPadCanApply ? <Text className='ft-hint'>{labels.padMixedLengthTip}</Text> : null}
          <View className='ft-sheet__footer'>
            <View className='ft-btn ft-btn--plain' onClick={() => setCopyVisible(false)}>
              <Text className='ft-btn__text ft-btn__text--plain'>{labels.cancel}</Text>
            </View>
            {process.env.TARO_ENV === 'h5' ? (
              <View className='ft-btn ft-btn--plain' onClick={downloadDisplayedText}>
                <Text className='ft-btn__text ft-btn__text--plain'>{labels.downloadTxt}</Text>
              </View>
            ) : null}
            <View className='ft-btn' onClick={() => void copyDisplayedText()}>
              <Text className='ft-btn__text'>{labels.confirmCopy}</Text>
            </View>
          </View>
        </View>
      </Popup>
    </View>
  )
}
