import { View } from '@tarojs/components'
import './index.css'

interface SkeletonProps {
  rows?: number
  /** 卡片式骨架（带圆角卡片容器） */
  card?: boolean
}

/** 骨架屏：信息流/卡片列表加载态（产品方案 §3.5 骨架屏优先） */
export default function Skeleton({ rows = 3, card = true }: SkeletonProps) {
  return (
    <View className='skeleton'>
      {Array.from({ length: rows }).map((_, idx) => (
        <View key={idx} className={card ? 'skeleton__card' : 'skeleton__plain'}>
          <View className='skeleton__line skeleton__line--title' />
          <View className='skeleton__line' />
          <View className='skeleton__line skeleton__line--short' />
        </View>
      ))}
    </View>
  )
}
