.draw-page {
  min-height: 100vh;
  padding-bottom: var(--sa-24, calc(24px + env(safe-area-inset-bottom)));
}

.segment {
  display: flex;
  flex-direction: row;
  background: var(--color-bg-card);
  padding: 8px 16px;
  gap: 8px;
}

.segment__item {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 48px;
  border-radius: var(--radius-sm);
}

.segment__item--active {
  background: var(--color-primary-light);
}

.segment__text {
  font-size: 15px;
  color: var(--color-text-secondary);
}

.segment__text--active {
  color: var(--color-primary);
  font-weight: 600;
}

.hero {
  margin: 16px;
  padding: 24px;
  background: var(--color-bg-card);
  border-radius: var(--radius-md);
}

.hero__head {
  display: flex;
  flex-direction: row;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 20px;
}

.hero__name {
  font-size: 20px;
  font-weight: 700;
  margin-right: 12px;
}

.hero__issue {
  font-size: 13px;
  color: var(--color-text-secondary);
}

.hero__live {
  display: flex;
  flex-direction: row;
  align-items: center;
  min-height: 48px;
  padding: 0 20px;
  border-radius: 999px;
  background: var(--color-primary);
}

.hero__live-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: #fff;
  margin-right: 8px;
}

.hero__live-text {
  color: #fff;
  font-size: 13px;
}

.hero__time {
  display: block;
  margin-top: 16px;
  font-size: 12px;
  color: var(--color-text-secondary);
}

.section-title {
  display: block;
  padding: 8px 24px;
  font-size: 17px;
  font-weight: 600;
}

.history-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: space-between;
  margin: 0 16px 12px;
  padding: 16px;
  gap: 16px;
  background: var(--color-bg-card);
  border-radius: var(--radius-md);
}

.history-card__issue {
  font-size: 14px;
  color: var(--color-text);
  margin-right: 16px;
}

.list-footer {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 64px;
}

.list-footer__text {
  font-size: 13px;
  color: var(--color-text-secondary);
}
