import Taro from '@tarojs/taro'
import { redirectToLogin } from '@/store/auth'
import { toolsLabels } from '@/labels/tools'
import { currentRoute } from '@/utils/nav'
import type { ToolItem } from '@/types'

/**
 * 工具门闸（首页工具区 / 工具列表页共用）：
 * /tool/list 返回的锁定状态在两处入口表现一致——置灰 + 点击分文案引导（PRD §9 门闸）。
 */

/** 工具列表按 toolId 索引 */
export function toToolAccessMap(list: ToolItem[]): Record<string, ToolItem> {
  return list.reduce<Record<string, ToolItem>>((acc, item) => {
    acc[item.toolId] = item
    return acc
  }, {})
}

/**
 * 工具点击门闸：返回 true 放行进入工具；
 * 锁定时 NOT_LOGIN 直接跳登录（回跳当前页），其余原因按 lockReason 分文案 toast 引导。
 * tool 为空（接口未返回该工具）时按未锁定放行。
 */
export function guardToolAccess(tool?: Pick<ToolItem, 'locked' | 'lockReason'> | null): boolean {
  if (!tool?.locked) return true
  if (tool.lockReason === 'NOT_LOGIN') {
    redirectToLogin(currentRoute())
    return false
  }
  const tip = tool.lockReason
    ? toolsLabels.lockReasonTips[tool.lockReason]
    : toolsLabels.lockReasonTips.NOT_SUBSCRIBED
  Taro.showToast({ title: tip, icon: 'none' })
  return false
}
