/**
 * 集合处理工具纯计算内核（移植自 lottery_web SetProcessingEntry.vue parseCodes / runProcessing）
 * 不依赖 Taro / DOM，H5 与 RN 通用。
 */
import { dedupeCodes, isValidCodeFormat, parseCodes } from './numberCodes'

export type SetOperation = 'intersection' | 'union' | 'difference'

export interface SetGroupParseResult {
  /** 去重后的号码（保持出现顺序）；存在非法码时为空数组 */
  codes: string[]
  /** 首个非法码（号码仅支持数字与 X 占位），全部合法时为 null */
  invalid: string | null
}

/**
 * 解析一组号码输入：分隔符与 numberCodes.parseCodes 一致，统一转大写后校验 ^[0-9X]+$ 并去重。
 * X 占位码作为普通字符串参与后续集合运算（对齐源实现）。
 */
export function parseSetGroup(text: string): SetGroupParseResult {
  const tokens = parseCodes(text).map((code) => code.toUpperCase())
  const invalid = tokens.find((code) => !isValidCodeFormat(code)) || null
  if (invalid) return { codes: [], invalid }
  return { codes: dedupeCodes(tokens), invalid: null }
}

/**
 * 集合运算（对齐源 runProcessing：输入已去重，结果保持组一优先的出现顺序）。
 * intersection：保留两组都存在的号码；union：合并去重；difference：组一有而组二没有的号码。
 */
export function runSetOperation(first: string[], second: string[], operation: SetOperation): string[] {
  const secondSet = new Set(second)
  switch (operation) {
    case 'union':
      return dedupeCodes([...first, ...second])
    case 'difference':
      return first.filter((code) => !secondSet.has(code))
    case 'intersection':
    default:
      return first.filter((code) => secondSet.has(code))
  }
}
