import { View, Text } from '@tarojs/components'
import { ReactNode } from 'react'
import { mineLabels } from '@/labels/mine'
import { isRealDevice } from '@/utils/device'
import './index.css'

/**
 * 渠道显示规则：dev 构建且非真机（H5 / 模拟器）只显示 MOCK；真机（含 dev 包）与 prod 构建
 * 只显示微信/支付宝（服务端仅 dev 启用 MOCK，fail-closed 守卫在 PayChannelFactory）；
 * 是否补调 /pay/complete 由 @/utils/pay 按 payParams.mockPayToken 服务端信号驱动，不看构建期
 */
const SHOW_MOCK = process.env.NODE_ENV === 'development' && !isRealDevice()

export type CashChannel = 'MOCK' | 'WX_PAY' | 'ALIPAY'

interface Props {
  /** 应付金额（元），用于按钮文案 */
  price: number
  paying: boolean
  /** 协议勾选状态；与 onAgreeChange 成对传入才渲染协议行（PRD §9.2 会员购买强制勾选） */
  agreed?: boolean
  onAgreeChange?: (agreed: boolean) => void
  /** 虚拟商品不退款提示（合规要求，必传） */
  noRefundHint: string
  /** 渠道按钮为主行动按钮时用品牌红主色（默认描边次级样式） */
  primary?: boolean
  /** 插入在协议/提示与现金渠道按钮之间的业务按钮（如会员页的积分支付） */
  children?: ReactNode
  onPay: (channel: CashChannel) => void
}

/**
 * 现金渠道支付按钮组（会员购买 / 积分充值共用）：协议勾选 + 不退款提示 + 渠道按钮。
 * 自绘按钮（NutButton 在 RN 端样式丢失且 loading 图标崩溃，禁用），提交态文案切换 + 调用方 ref 锁防重。
 */
export default function CashPayButtons({
  price,
  paying,
  agreed,
  onAgreeChange,
  noRefundHint,
  primary,
  children,
  onPay,
}: Props) {
  const needAgreement = typeof onAgreeChange === 'function'
  const disabled = paying || (needAgreement && !agreed)
  const actionCls = `cash-pay__action${primary ? ' cash-pay__action--primary' : ''}${disabled ? ' cash-pay__action--disabled' : ''}`
  const textCls = `cash-pay__action-text${primary ? ' cash-pay__action-text--primary' : ''}`

  const renderChannel = (channel: CashChannel, label: string) => (
    <View className={actionCls} onClick={() => !disabled && onPay(channel)}>
      <Text className={textCls}>{paying ? mineLabels.memberPaySubmitting : label}</Text>
    </View>
  )

  return (
    <View className='cash-pay'>
      {needAgreement ? (
        <View className='cash-pay__agreement' onClick={() => onAgreeChange(!agreed)}>
          <View className={`cash-pay__checkbox${agreed ? ' cash-pay__checkbox--checked' : ''}`}>
            {agreed ? <Text className='cash-pay__checkmark'>✓</Text> : null}
          </View>
          <Text className='cash-pay__agreement-text'>{mineLabels.memberPayAgreement}</Text>
        </View>
      ) : null}
      <Text className='cash-pay__hint'>{noRefundHint}</Text>
      {children}
      {SHOW_MOCK ? (
        renderChannel('MOCK', mineLabels.memberPayMock(price))
      ) : (
        <>
          {renderChannel('WX_PAY', mineLabels.memberPayWx(price))}
          {renderChannel('ALIPAY', mineLabels.memberPayAlipay(price))}
        </>
      )}
    </View>
  )
}
