import type { CommentNode, FlattenedReply } from '@/types'

/**
 * 将评论的 childComments 树 DFS 拍平为一层列表（两层「楼中楼」展示用）。
 * 移植自 lottery_web utils/forumComments.ts。
 */
export function flattenReplies(comment: CommentNode): FlattenedReply[] {
  const result: FlattenedReply[] = []

  const walk = (node: CommentNode, replyToNickname?: string) => {
    const children = Array.isArray(node.childComments) ? node.childComments : []
    for (const child of children) {
      const { childComments: _omit, ...rest } = child
      result.push({ ...rest, replyToNickname })
      const nickname = String(child.nickname || '').trim()
      walk(child, nickname || undefined)
    }
  }

  walk(comment)
  return result
}

/** 将接口分页返回的子评论列表拍平为两层展示列表 */
export function flattenThreadRows(rows: CommentNode[]): FlattenedReply[] {
  const result: FlattenedReply[] = []
  if (!Array.isArray(rows)) return result

  for (const row of rows) {
    const nickname = String(row?.nickname || '').trim()
    const { childComments: _omit, ...rest } = row
    result.push({ ...rest })
    for (const reply of flattenReplies(row)) {
      result.push({ ...reply, replyToNickname: reply.replyToNickname || nickname || undefined })
    }
  }
  return result
}
