/** 预测维度 / 位置模式矩阵（移植自 lottery_web utils/forecastOptions.ts，契约见 Web PRD §12.2） */

export type DimensionCode = '-2' | '2' | '3' | '4' | '5'
export type KillType = 'killOne' | 'killTwo'
export type ForecastLotteryCode = '04' | '350133' | '3d'

export interface FilterOption<T extends string = string> {
  label: string
  value: T
}

export const FORECAST_MODE_MATRIX: Record<
  ForecastLotteryCode,
  Partial<Record<DimensionCode, string[]>>
> = {
  '04': {
    '-2': ['杀A', '杀B', '杀C', '杀D', '杀E', '杀F', '杀G'],
    '2': ['ABXX', 'AXCX', 'AXXD', 'XBCX', 'XBXD', 'XXCD'],
    '3': ['ABCX', 'ABXD', 'AXCD', 'XBCD'],
    '4': ['ABCD'],
    '5': ['ABCDE'],
  },
  '350133': {
    '-2': ['杀A', '杀B', '杀C', '杀D', '杀E'],
    '2': ['ABXX', 'AXCX', 'AXXD', 'XBCX', 'XBXD', 'XXCD'],
    '3': ['ABCX', 'ABXD', 'AXCD', 'XBCD'],
    '4': ['ABCD'],
    '5': ['ABCDE'],
  },
  '3d': {
    '-2': ['杀A', '杀B', '杀C'],
    '2': ['ABX', 'AXC', 'XBC'],
    '3': ['ABC'],
  },
}

export const FORECAST_DIMENSION_OPTIONS: Array<FilterOption<DimensionCode>> = [
  { label: '一定', value: '-2' },
  { label: '二定', value: '2' },
  { label: '三定', value: '3' },
  { label: '四定', value: '4' },
  { label: '五定', value: '5' },
]

export function getDimensionOptions(
  lotteryCode: ForecastLotteryCode,
  inputMode: 'standard' | 'free' = 'standard',
) {
  const matrix = FORECAST_MODE_MATRIX[lotteryCode] || {}
  return FORECAST_DIMENSION_OPTIONS.filter((item) => {
    if (!Array.isArray(matrix[item.value]) || matrix[item.value]!.length === 0) return false
    if (inputMode === 'free' && item.value === '-2') return false
    return true
  })
}

export function getCodeModeOptions(lotteryCode: ForecastLotteryCode, dimension: DimensionCode) {
  return (FORECAST_MODE_MATRIX[lotteryCode] || {})[dimension] || []
}

/**
 * 选号规模（precision）选项：杀码维度（-2）为「杀2」；
 * 定码维度为 6/7 按维度位数重复（二定 6*6/7*7，三定 6*6*6/7*7*7，以此类推）。
 */
export function getPrecisionOptions(dimension: DimensionCode | '') {
  if (!dimension) return []
  if (dimension === '-2') return ['杀2']
  const count = Number(dimension)
  return [Array(count).fill('6').join('*'), Array(count).fill('7').join('*')]
}

/** 计划期数（计划模式 forecastPhase=1）允许的上下界；客户端按维度收紧，BFF 兜底 [3,8] */
export const PLAN_NUM_MIN = 3
export const PLAN_NUM_MAX = 8

/** 计划期数随维度收紧：三/四/五定支持 3~8 期，其余 3~6 期 */
export function getPlanNumOptions(dimension: DimensionCode): number[] {
  const max = dimension === '3' || dimension === '4' || dimension === '5' ? PLAN_NUM_MAX : 6
  return Array.from({ length: max - PLAN_NUM_MIN + 1 }, (_, i) => PLAN_NUM_MIN + i)
}

export function toBackendCodeMode(mode?: string) {
  const value = String(mode || '').trim().toUpperCase()
  if (!value) return ''
  return value.startsWith('杀') ? `KILL${value.replace('杀', '')}` : value
}

export function resolveRankModeSelection(
  mode: string,
  dimension: DimensionCode,
  killType: KillType,
) {
  const codeMode = toBackendCodeMode(mode)
  const planMode = dimension === '-2' ? (killType === 'killOne' ? '-1' : '-2') : dimension
  return { planMode, codeMode }
}
