/**
 * 码组扩展计算内核（移植自 lottery_web CodeGroupExtensionEntry.vue，纯前端计算零 API）
 * 纯 TS，不依赖 Taro / DOM，H5 与 RN 通用。
 * 错误以结构化 EngineError 返回，由页面映射 codeGroupExtensionLabels.errors 文案。
 */

import { dedupeCodes, generateSuffixes, parseCodes } from './numberCodes'

/** 工具内部彩种键（对齐源 lotteryType；与 constants/lottery.ts 的 toolKey 一致） */
export type ExtensionLotteryType = 'pl5' | 'qxc' | 'fc3d'

export interface ExtensionRule {
  /** 支持的定数 */
  counts: number[]
  /** 总位数 */
  positions: number
}

/** 彩种规则（源 137-141 行） */
export const EXTENSION_RULES: Record<ExtensionLotteryType, ExtensionRule> = {
  pl5: { counts: [2, 3, 4, 5], positions: 5 },
  qxc: { counts: [2, 3, 4], positions: 7 },
  fc3d: { counts: [2, 3], positions: 3 },
}

/** 位置名（源 positionNames），按彩种 slice 末 N 位 */
export const POSITION_NAMES = ['百万位', '十万位', '万位', '千位', '百位', '十位', '个位']

export interface PositionOption {
  label: string
  value: number
}

/** 结果项：code 为目标位号码，paddedCode 用 X 占位表达补位位置（源 paddedCode 语义） */
export interface ResultItem {
  code: string
  paddedCode?: string
}

/** 错误 key 与 codeGroupExtensionLabels.errors 一一对应 */
export type EngineErrorKey =
  | 'noExpandTarget'
  | 'positionsMismatch'
  | 'targetMustContainSource'
  | 'invalidCode'
  | 'positionGroupsRequired'
  | 'locationTargetMin'
  | 'locationTargetMax'
  | 'locationUnitRequired'
  | 'locationUnitPositionsMin'
  | 'locationUnitPositionsInTarget'
  | 'locationUnitCodesRequired'

export interface EngineError {
  key: EngineErrorKey
  params: Array<string | number>
}

/** noop：输入为空时静默中止（对齐源 parseCodes 返回空数组后直接 return，不动旧结果） */
export type EngineOutcome =
  | { status: 'ok'; results: ResultItem[] }
  | { status: 'error'; error: EngineError }
  | { status: 'noop' }

function err(key: EngineErrorKey, params: Array<string | number> = []): EngineOutcome {
  return { status: 'error', error: { key, params } }
}

/** 位置标签：按彩种总位数取末 N 个位置名（源 positionLabels） */
export function getPositionLabels(rule: ExtensionRule): string[] {
  return POSITION_NAMES.slice(-rule.positions)
}

/** 定位组合可选位置：qxc 只允许后 4 位（源 171-174 行） */
export function getLocationPositionOptions(type: ExtensionLotteryType, rule: ExtensionRule): PositionOption[] {
  const options = getPositionLabels(rule).map((label, value) => ({ label, value }))
  return type === 'qxc' ? options.slice(-4) : options
}

/** 定位组合最大定数（源 maxLocationCount） */
export function getMaxLocationCount(rule: ExtensionRule): number {
  return Math.max(...rule.counts)
}

/** 默认位置：末 N 位（源 resetExpandPositions / defaultLocationTargetPositions） */
export function defaultTailPositions(totalPositions: number, count: number): number[] {
  return Array.from({ length: count }, (_, index) => totalPositions - count + index)
}

/** 基础号码组位置标识，如 [0,1,2] → '123位'（源 locationPositionKey） */
export function locationPositionKey(positions: number[]): string {
  return positions.length
    ? `${[...positions].sort((left, right) => left - right).map((position) => position + 1).join('')}位`
    : ''
}

type ParseOutcome = { codes: string[] } | { error: EngineError }

/** 解析定长号码组：去重；发现非 N 位纯数字即报 invalidCode（源 parseCodes） */
function parseLengthCodes(input: string, length: number): ParseOutcome {
  const codes = parseCodes(input)
  const pattern = new RegExp(`^\\d{${length}}$`)
  const invalid = codes.find((code) => !pattern.test(code))
  if (invalid) return { error: { key: 'invalidCode', params: [length, invalid] } }
  return { codes: dedupeCodes(codes) }
}

export interface ExpansionParams {
  baseInput: string
  sourceCount: number
  targetCount: number
  sourcePositions: number[]
  targetPositions: number[]
}

/** 定数扩展（源 runExpansion）：原定数+原位置 → 扩展定数+目标位置（目标必须包含原位置），新增位 0-9 全排列补全 */
export function runExpansion(rule: ExtensionRule, params: ExpansionParams): EngineOutcome {
  const { baseInput, sourceCount, targetCount, sourcePositions, targetPositions } = params
  if (!targetCount) return err('noExpandTarget')
  if (sourcePositions.length !== sourceCount || targetPositions.length !== targetCount) {
    return err('positionsMismatch')
  }
  const sourceList = [...sourcePositions].sort((a, b) => a - b)
  const targetList = [...targetPositions].sort((a, b) => a - b)
  if (sourceList.some((position) => !targetList.includes(position))) return err('targetMustContainSource')
  const parsed = parseLengthCodes(baseInput, sourceCount)
  if ('error' in parsed) return { status: 'error', error: parsed.error }
  if (!parsed.codes.length) return { status: 'noop' }
  const extensionPositions = targetList.filter((position) => !sourceList.includes(position))
  const suffixes = generateSuffixes(extensionPositions.length)
  const items = parsed.codes.flatMap((code) =>
    suffixes.map((suffix) => {
      const digits = Array.from({ length: rule.positions }, () => 'X')
      sourceList.forEach((position, index) => {
        digits[position] = code[index]
      })
      extensionPositions.forEach((position, index) => {
        digits[position] = suffix[index]
      })
      return { code: targetList.map((position) => digits[position]).join(''), paddedCode: digits.join('') }
    }),
  )
  return { status: 'ok', results: [...new Map(items.map((item) => [item.paddedCode, item])).values()] }
}

export interface PositionGroupInput {
  positions: number[]
  input: string
}

/** 指定号码位置填充（源 runPositionFill）：两组号码各占一组互斥位置，笛卡尔组合 */
export function runPositionFill(
  rule: ExtensionRule,
  first: PositionGroupInput,
  second: PositionGroupInput,
): EngineOutcome {
  if (!first.positions.length || !second.positions.length) return err('positionGroupsRequired')
  const firstParsed = parseLengthCodes(first.input, first.positions.length)
  if ('error' in firstParsed) return { status: 'error', error: firstParsed.error }
  const secondParsed = parseLengthCodes(second.input, second.positions.length)
  if ('error' in secondParsed) return { status: 'error', error: secondParsed.error }
  if (!firstParsed.codes.length || !secondParsed.codes.length) return { status: 'noop' }
  const items = firstParsed.codes.flatMap((firstCode) =>
    secondParsed.codes.map((secondCode) => {
      const digits = Array.from({ length: rule.positions }, () => 'X')
      first.positions.forEach((position, index) => {
        digits[position] = firstCode[index]
      })
      second.positions.forEach((position, index) => {
        digits[position] = secondCode[index]
      })
      return { code: digits.filter((digit) => digit !== 'X').join(''), paddedCode: digits.join('') }
    }),
  )
  return { status: 'ok', results: [...new Map(items.map((item) => [item.paddedCode, item])).values()] }
}

/**
 * 定位组合（源 runLocationCombination）：组合目标选 ≥2 位，多个基础号码组各占 ≥2 位且落在目标内；
 * 枚举目标定数全组合，保留同时命中所有基础组的组合。
 * 注：源在号码非法时先报 invalidCode 再报 locationUnitCodesRequired（双提示），移动端收敛为单条 invalidCode。
 */
export function runLocationCombination(
  rule: ExtensionRule,
  targetPositionsInput: number[],
  units: PositionGroupInput[],
): EngineOutcome {
  const targetPositions = [...targetPositionsInput].sort((left, right) => left - right)
  if (targetPositions.length < 2) return err('locationTargetMin')
  const maxLocationCount = getMaxLocationCount(rule)
  if (targetPositions.length > maxLocationCount) return err('locationTargetMax', [maxLocationCount])
  const targetPositionSet = new Set(targetPositions)
  const configuredUnits = units.filter((unit) => unit.positions.length || unit.input.trim())
  if (!configuredUnits.length) return err('locationUnitRequired')
  const parsedUnits: Array<{ positions: number[]; codes: Set<string> }> = []
  for (let index = 0; index < configuredUnits.length; index += 1) {
    const unit = configuredUnits[index]
    const positions = [...unit.positions].sort((left, right) => left - right)
    if (positions.length < 2) return err('locationUnitPositionsMin', [index])
    if (positions.some((position) => !targetPositionSet.has(position))) {
      return err('locationUnitPositionsInTarget', [index])
    }
    const parsed = parseLengthCodes(unit.input, positions.length)
    if ('error' in parsed) return { status: 'error', error: parsed.error }
    if (!parsed.codes.length) return err('locationUnitCodesRequired', [index, positions.length])
    parsedUnits.push({ positions, codes: new Set(parsed.codes) })
  }
  const positionIndexMap = new Map(targetPositions.map((position, index) => [position, index]))
  const items = generateSuffixes(targetPositions.length)
    .filter((targetCode) =>
      parsedUnits.every((unit) => {
        const unitCode = unit.positions.map((position) => targetCode[positionIndexMap.get(position)!]).join('')
        return unit.codes.has(unitCode)
      }),
    )
    .map((code) => {
      const digits = Array.from({ length: rule.positions }, () => 'X')
      targetPositions.forEach((position, index) => {
        digits[position] = code[index]
      })
      return { code, paddedCode: digits.join('') }
    })
  return { status: 'ok', results: items }
}
