import { useEffect, useMemo, useState } from 'react'
import { ScrollView, Text, Textarea, View } from '@tarojs/components'
import Taro from '@tarojs/taro'
import Popup from '@/components/SheetPopup'
import Empty from '@/components/Empty'
import PopupCloseIcon from '@/components/PopupCloseIcon'
import { LOTTERY_LIST, type LotteryCode } from '@/constants/lottery'
import { setProcessingLabels as labels } from '@/labels/tools'
import { navigateTo } from '@/utils/nav'
import { formatCopyCode } from '@/utils/tools/numberCodes'
import { parseSetGroup, runSetOperation, type SetOperation } from '@/utils/tools/setOps'
import { codeToToolKey, readToolPayloadOnce, toolKeyToCode, writeToolPayload } from '@/utils/tools/toolPayload'
import { STORAGE_KEYS } from '@/utils/storage'
import './index.css'

const PAGE_SIZE = 20

/** 筛选工具支持的定数（对齐源 SetProcessingEntry.vue filterDigitCounts，按彩种 code 索引） */
const FILTER_DIGIT_COUNTS: Record<LotteryCode, number[]> = {
  '350133': [2, 3, 4, 5],
  '04': [2, 3, 4],
  '3d': [2, 3],
}

const OPERATIONS: { value: SetOperation; label: string; tip: string }[] = [
  { value: 'intersection', label: labels.operationIntersection, tip: labels.operationTipIntersection },
  { value: 'union', label: labels.operationUnion, tip: labels.operationTipUnion },
  { value: 'difference', label: labels.operationDifference, tip: labels.operationTipDifference },
]

type CopySeparator = 'comma' | 'space'

function toast(title: string) {
  Taro.showToast({ title, icon: 'none' })
}

/** 集合处理工具（免费，纯前端计算零 API；移植自 lottery_web SetProcessingEntry.vue） */
export default function SetProcessingPage() {
  const [code, setCode] = useState<LotteryCode>('350133')
  const [firstInput, setFirstInput] = useState('')
  const [secondInput, setSecondInput] = useState('')
  const [operation, setOperation] = useState<SetOperation>('intersection')
  const [results, setResults] = useState<string[]>([])
  const [displayCount, setDisplayCount] = useState(PAGE_SIZE)
  const [copyVisible, setCopyVisible] = useState(false)
  const [copySeparator, setCopySeparator] = useState<CopySeparator>('space')
  const [copyPad, setCopyPad] = useState(false)

  /** 复制补位目标位数（对齐源 copyTargetLength）：fc3d 补到 3 位，其余补到 4 位 */
  const copyTargetLength = code === '3d' ? 3 : 4

  // 跨工具入站 payload（如筛选工具带入两组号码）：读取即删，结构 {lotteryType, groups}
  useEffect(() => {
    void (async () => {
      const payload = await readToolPayloadOnce<{ lotteryType?: string; groups?: string[][] }>(
        STORAGE_KEYS.setProcessingPayload,
      )
      if (!payload) return
      const targetCode = toolKeyToCode(payload.lotteryType)
      if (!targetCode || !Array.isArray(payload.groups) || !payload.groups.length) return
      setCode(targetCode)
      setFirstInput((payload.groups[0] || []).join(' '))
      setSecondInput((payload.groups[1] || []).join(' '))
    })()
  }, [])

  const runProcessing = () => {
    const first = parseSetGroup(firstInput)
    if (first.invalid) {
      toast(labels.errors.invalidCode(first.invalid))
      return
    }
    const second = parseSetGroup(secondInput)
    if (second.invalid) {
      toast(labels.errors.invalidCode(second.invalid))
      return
    }
    setResults(runSetOperation(first.codes, second.codes, operation))
    setDisplayCount(PAGE_SIZE)
  }

  const swapInputs = () => {
    const current = firstInput
    setFirstInput(secondInput)
    setSecondInput(current)
    setResults([])
    setDisplayCount(PAGE_SIZE)
  }

  const clearInputs = () => {
    setFirstInput('')
    setSecondInput('')
    setResults([])
    setDisplayCount(PAGE_SIZE)
  }

  /** 跳筛选工具：纯数字 / 同定数 / 彩种支持校验（对齐源 goToFilterTool） */
  const goToFilterTool = async () => {
    const codes = [...new Set(results)]
    if (!codes.length) return
    if (codes.some((item) => !/^\d+$/.test(item))) {
      toast(labels.errors.filterOnlyDigits)
      return
    }
    const digitCount = codes[0].length
    if (codes.some((item) => item.length !== digitCount)) {
      toast(labels.errors.filterMixedDigit)
      return
    }
    if (!FILTER_DIGIT_COUNTS[code].includes(digitCount)) {
      toast(labels.errors.filterUnsupportedDigit(digitCount))
      return
    }
    const lotteryType = codeToToolKey(code)
    if (!lotteryType) return
    await writeToolPayload(STORAGE_KEYS.filterToolPayload, { lotteryType, digitCount, codes })
    navigateTo({ url: '/pages/tools/filter/index' })
  }

  const displayedCopyText = useMemo(() => {
    const codes = [...new Set(results.map((item) => (copyPad ? formatCopyCode(item, copyTargetLength) : item)))]
    return codes.join(copySeparator === 'comma' ? ',' : ' ')
  }, [results, copyPad, copySeparator, copyTargetLength])

  const openCopyModal = () => {
    if (!results.length) return
    setCopyVisible(true)
  }

  const copyResults = async () => {
    if (!displayedCopyText) return
    try {
      await Taro.setClipboardData({ data: displayedCopyText })
      setCopyVisible(false)
      toast(labels.copied(results.length))
    } catch {
      toast(labels.errors.copyFailed)
    }
  }

  /** 下载 txt：仅 H5（Blob + a[download]，动态创建 DOM 仅限该分支，RN 不渲染入口） */
  const downloadResults = () => {
    if (process.env.TARO_ENV !== 'h5' || !displayedCopyText) return
    const blob = new Blob([displayedCopyText], { type: 'text/plain;charset=utf-8' })
    const link = document.createElement('a')
    link.href = URL.createObjectURL(blob)
    link.download = labels.downloadFileName
    link.click()
    URL.revokeObjectURL(link.href)
  }

  const operationTip = OPERATIONS.find((item) => item.value === operation)?.tip || ''

  return (
    <View className='sp-page'>
      {/* 操作区 */}
      <View className='sp-card'>
        <Text className='sp-label'>{labels.lotterySection}</Text>
        <View className='chips'>
          {LOTTERY_LIST.map((item) => (
            <View
              key={item.code}
              className={`chip${item.code === code ? ' chip--active' : ''}`}
              onClick={() => setCode(item.code)}
            >
              <Text className={`chip__text${item.code === code ? ' chip__text--active' : ''}`}>{item.label}</Text>
            </View>
          ))}
        </View>

        <View className='sp-label-row'>
          <Text className='sp-label'>{labels.firstGroupSection}</Text>
          <Text className='sp-hint'>{labels.inputHint}</Text>
        </View>
        <Textarea
          className='sp-textarea'
          value={firstInput}
          placeholder={labels.firstPlaceholder}
          maxlength={-1}
          onInput={(e) => setFirstInput(e.detail.value)}
        />

        <View className='sp-swap-row'>
          <View className='sp-swap-btn' onClick={swapInputs}>
            <Text className='sp-swap-btn__icon'>⇅</Text>
          </View>
          <Text className='sp-hint'>{labels.swapGroups}</Text>
        </View>

        <View className='sp-label-row'>
          <Text className='sp-label'>{labels.secondGroupSection}</Text>
          <Text className='sp-hint'>{labels.inputHint}</Text>
        </View>
        <Textarea
          className='sp-textarea'
          value={secondInput}
          placeholder={labels.secondPlaceholder}
          maxlength={-1}
          onInput={(e) => setSecondInput(e.detail.value)}
        />

        <Text className='sp-label'>{labels.operationSection}</Text>
        <View className='chips'>
          {OPERATIONS.map((item) => (
            <View
              key={item.value}
              className={`chip${item.value === operation ? ' chip--active' : ''}`}
              onClick={() => setOperation(item.value)}
            >
              <Text className={`chip__text${item.value === operation ? ' chip__text--active' : ''}`}>
                {item.label}
              </Text>
            </View>
          ))}
        </View>
        <Text className='sp-tip'>{operationTip}</Text>

        <View className='sp-actions'>
          <View className='sp-btn sp-btn--plain' onClick={clearInputs}>
            <Text className='sp-btn__text sp-btn__text--plain'>{labels.clear}</Text>
          </View>
          <View className='sp-btn' onClick={runProcessing}>
            <Text className='sp-btn__text'>{labels.run}</Text>
          </View>
        </View>
      </View>

      {/* 结果区 */}
      <View className='sp-card'>
        <View className='sp-result-head'>
          <Text className='sp-label'>{labels.resultTitle}</Text>
          <Text className='sp-result-count'>{labels.resultCount(results.length)}</Text>
        </View>

        {results.length === 0 ? (
          <Empty text={labels.resultEmpty} />
        ) : (
          <>
            <View className='sp-row sp-row--head'>
              <Text className='sp-row__index'>{labels.columnIndex}</Text>
              <Text className='sp-row__code'>{labels.columnCode}</Text>
            </View>
            {results.slice(0, displayCount).map((item, index) => (
              <View key={`${item}-${index}`} className='sp-row'>
                <Text className='sp-row__index'>{index + 1}</Text>
                <Text className='sp-row__code'>{item}</Text>
              </View>
            ))}
            {displayCount < results.length ? (
              <View className='load-more' onClick={() => setDisplayCount(displayCount + PAGE_SIZE)}>
                <Text className='load-more__text'>{labels.loadMore}</Text>
              </View>
            ) : null}
            <View className='sp-result-actions'>
              <View className='sp-btn sp-btn--plain' onClick={goToFilterTool}>
                <Text className='sp-btn__text sp-btn__text--plain'>{labels.goFilter}</Text>
              </View>
              <View className='sp-btn' onClick={openCopyModal}>
                <Text className='sp-btn__text'>{labels.copy}</Text>
              </View>
            </View>
          </>
        )}
      </View>

      {/* 复制弹层 */}
      <Popup visible={copyVisible} closeable closeIcon={<PopupCloseIcon />} onClose={() => setCopyVisible(false)}>
        <View className='sp-sheet'>
          <Text className='sp-sheet__title'>{labels.copyModalTitle}</Text>
          <ScrollView scrollY className='sp-copy-preview'>
            <Text className='sp-copy-preview__text'>{displayedCopyText}</Text>
          </ScrollView>

          <View className='sp-sheet__settings'>
            <View className='chips'>
              {(['comma', 'space'] as CopySeparator[]).map((item) => (
                <View
                  key={item}
                  className={`chip${item === copySeparator ? ' chip--active' : ''}`}
                  onClick={() => setCopySeparator(item)}
                >
                  <Text className={`chip__text${item === copySeparator ? ' chip__text--active' : ''}`}>
                    {item === 'comma' ? labels.separatorComma : labels.separatorSpace}
                  </Text>
                </View>
              ))}
            </View>
            <View className='chips'>
              {[true, false].map((item) => (
                <View
                  key={String(item)}
                  className={`chip${item === copyPad ? ' chip--active' : ''}`}
                  onClick={() => setCopyPad(item)}
                >
                  <Text className={`chip__text${item === copyPad ? ' chip__text--active' : ''}`}>
                    {item ? labels.pad : labels.noPad}
                  </Text>
                </View>
              ))}
            </View>
          </View>

          <View className='sp-sheet__actions'>
            <View className='sp-btn sp-btn--plain' onClick={() => setCopyVisible(false)}>
              <Text className='sp-btn__text sp-btn__text--plain'>{labels.cancel}</Text>
            </View>
            {process.env.TARO_ENV === 'h5' ? (
              <View className='sp-btn sp-btn--plain' onClick={downloadResults}>
                <Text className='sp-btn__text sp-btn__text--plain'>{labels.downloadTxt}</Text>
              </View>
            ) : null}
            <View className='sp-btn' onClick={copyResults}>
              <Text className='sp-btn__text'>{labels.confirmCopy}</Text>
            </View>
          </View>
        </View>
      </Popup>
    </View>
  )
}
