/* 现金渠道支付按钮组（会员购买 / 积分充值共用；自绘按钮，NutButton 禁用原因见 AGENTS.md） */

.cash-pay__agreement {
  display: flex;
  flex-direction: row;
  align-items: center;
  margin-top: 16px;
  min-height: 44px;
}

.cash-pay__checkbox {
  width: 18px;
  height: 18px;
  margin-right: 8px;
  border-radius: 9px;
  border: 1px solid var(--color-border-strong);
  display: flex;
  align-items: center;
  justify-content: center;
}

.cash-pay__checkbox--checked {
  background: var(--color-primary);
  border-color: var(--color-primary);
}

.cash-pay__checkmark {
  font-size: 12px;
  line-height: 18px;
  color: #fff;
}

.cash-pay__agreement-text {
  font-size: 12px;
  color: var(--color-text-secondary);
}

.cash-pay__hint {
  display: block;
  margin-top: 4px;
  font-size: 11px;
  color: var(--color-text-placeholder);
}

.cash-pay__action {
  margin-top: 16px;
  min-height: 46px;
  padding: 6px 16px;
  border-radius: 23px;
  border: 1px solid var(--color-border);
  display: flex;
  align-items: center;
  justify-content: center;
}

.cash-pay__action--primary {
  background: var(--color-primary);
  border-color: var(--color-primary);
}

.cash-pay__action--disabled {
  opacity: 0.6;
}

.cash-pay__action-text {
  font-size: 15px;
  color: var(--color-text);
}

.cash-pay__action-text--primary {
  font-weight: 600;
  color: #fff;
}
