:root,
page {
  --nut-scale-f: 1;
  --nut-scale-font: var(--nut-scale-f, 1);
  --nut-scale-icon: var(--nut-scale-f, 1);
  --nut-icon-height: calc(16px * var(--nut-scale-icon, var(--nut-scale-f, 1))) !important;
  --nut-icon-width: calc(16px * var(--nut-scale-icon, var(--nut-scale-f, 1))) !important;
  --nut-icon-line-height: calc(16px * var(--nut-scale-icon, var(--nut-scale-f, 1))) !important;
}

.nut-swiper {
  width: 100%;
  height: 100%;
  overflow: hidden;
  position: relative;
}
.nut-swiper-canmove-horizontal {
  touch-action: pan-y;
}
.nut-swiper-canmove-vertical {
  touch-action: pan-x;
}
.nut-swiper-indicator {
  display: flex;
  flex-direction: row;
  justify-content: center;
  position: absolute;
  height: calc(4px * var(--nut-scale-f, 1));
  width: 100%;
  top: 89.33%;
  z-index: 10;
}
.nut-swiper-indicator-vertical {
  width: calc(8px * var(--nut-scale-f, 1));
  height: 100%;
  top: 0;
  left: calc(12px * var(--nut-scale-f, 1));
  flex-direction: column;
  justify-content: center;
  z-index: 1;
}

.nut-swiper-inner {
  width: 100%;
  height: 100%;
  display: flex;
  position: relative;
}
.nut-swiper-inner-vertical {
  flex-direction: column;
}

.nut-swiper-slide {
  width: 100%;
  height: 100%;
  position: relative;
  flex-shrink: 0;
}

.nut-swiper-item {
  width: 100%;
  height: 100%;
}

[dir=rtl] .nut-swiper-indicator,
.nut-rtl .nut-swiper-indicator {
  left: auto;
  right: 50%;
}
[dir=rtl] .nut-swiper-indicator-vertical,
.nut-rtl .nut-swiper-indicator-vertical {
  left: auto;
  right: calc(12px * var(--nut-scale-f, 1));
}