import Taro from '@tarojs/taro'

/** 站内导航辅助：统一跳转参数携带（产品方案 §4.3：帖子卡片携带 from 记录来源） */

/** 全局导航锁窗口（ms）：覆盖一次页面跳转动画。Taro 导航 API 无内置防抖，
    快速连点会把同一页面重复 push 入栈（需连返多次），窗口内的重复导航调用直接忽略 */
const NAV_LOCK_MS = 600
let navLockUntil = 0

/** 命中导航锁返回 true（调用方应忽略本次导航）；未命中则上锁并放行 */
function navLocked(): boolean {
  const now = Date.now()
  if (now < navLockUntil) return true
  navLockUntil = now + NAV_LOCK_MS
  return false
}

/** 防连点版导航原语：页面内需要直接导航时一律用这几个，不要直接调 Taro.navigateTo 等 */
export function navigateTo(options: Parameters<typeof Taro.navigateTo>[0]) {
  if (navLocked()) return
  Taro.navigateTo(options)
}

export function switchTab(options: Parameters<typeof Taro.switchTab>[0]) {
  if (navLocked()) return
  Taro.switchTab(options)
}

export function redirectTo(options: Parameters<typeof Taro.redirectTo>[0]) {
  if (navLocked()) return
  Taro.redirectTo(options)
}

export function navigateBack(options?: Parameters<typeof Taro.navigateBack>[0]) {
  if (navLocked()) return
  Taro.navigateBack(options)
}

export function currentRoute(): string {
  const inst = Taro.getCurrentInstance()
  const path = inst?.router?.path || ''
  const params = inst?.router?.params || {}
  const query = Object.entries(params)
    .map(([k, v]) => `${k}=${encodeURIComponent(String(v))}`)
    .join('&')
  return query ? `${path}?${query}` : path
}

export function goPostDetail(params: { partition: string; type: 'exchange' | 'prediction'; id: number | string }) {
  const from = encodeURIComponent(currentRoute())
  navigateTo({
    url: `/pages/forum-detail/index?partition=${params.partition}&type=${params.type}&id=${params.id}&from=${from}`,
  })
}

