/** 一级 Tab 页路径（switchTab 跳转判断用） */
export const TAB_PAGES = [
  '/pages/home/index',
  '/pages/trend/index',
  '/pages/analysis/index',
  '/pages/forum/index',
  '/pages/profile/index',
]

/** 运营位（Banner 等）站内跳转：tab 页走 switchTab（不支持 query，参数丢弃），其余 navigateTo */
export function goPageLink(url: string) {
  const path = url.split('?')[0]
  if (TAB_PAGES.includes(path)) {
    switchTab({ url: path })
  } else {
    navigateTo({ url })
  }
}

/** 返回：优先 navigateBack，兜底到指定页（默认社区） */
export function goBack(fallback = '/pages/forum/index') {
  const pages = Taro.getCurrentPages()
  if (pages.length > 1) {
    navigateBack()
  } else if (TAB_PAGES.includes(fallback)) {
    switchTab({ url: fallback })
  } else {
    redirectTo({ url: fallback })
  }
}

/** 认证成功后的站内回跳（登录/注册共用）：仅接受站内路径（以 / 开头），Tab 页用 switchTab。
 *  安全校验集中在此，避免两页各留一份白名单规则产生漂移 */
export function goAfterAuth(raw: string | null | undefined, fallback = '/pages/profile/index') {
  const target = String(raw || '').trim()
  const safe = target.startsWith('/') ? target : fallback
  const path = safe.split('?')[0]
  if (TAB_PAGES.includes(path)) {
    switchTab({ url: path })
  } else {
    redirectTo({ url: safe })
  }
}
