import { get, post, unwrapAjaxData } from './request'

/**
 * 开奖结果归一化（移植自 lottery_web server/utils/drawResults.ts / lotteryBackend.ts）。
 * 直连 Java 后端后，原 BFF 服务端的字段重命名、排序、fallback 加工全部移到客户端。
 */

export interface NormalizedDrawResult {
  lotteryType: string
  lotteryCode: string
  drawNum: string
  numbers: string[]
  drawTime: string
}

interface BackendDrawResult {
  lotteryName?: string
  lotteryType?: string
  lotteryCode?: string
  lotteryDrawNum?: string
  lotteryDrawResult?: string
  lotteryDrawTime?: string
  drawNum?: string
  result?: string
  drawTime?: string
}

/** 开奖号串按逗号/空白拆分 */
export function safeSplitNumbers(raw: string | null | undefined): string[] {
  if (!raw) return []
  return String(raw)
    .split(/[,\s]+/)
    .map((item) => item.trim())
    .filter(Boolean)
}

function lotteryLabel(code: string, fallback?: string) {
  const map: Record<string, string> = {
    '350133': '排列五',
    '04': '七星彩',
    '3d': '福彩3D',
  }
  const normalized = code.toLowerCase() === '3d' ? '3d' : code
  return String(fallback || '').trim() || map[normalized] || code
}

function drawNumScore(drawNum: string) {
  const numeric = Number(String(drawNum || '').replace(/\D/g, ''))
  return Number.isFinite(numeric) ? numeric : 0
}

function timeScore(drawTime: string) {
  const timestamp = new Date(drawTime).getTime()
  return Number.isFinite(timestamp) ? timestamp : 0
}

function normalizeDrawResult(item: BackendDrawResult, code: string): NormalizedDrawResult {
  return {
    lotteryType: lotteryLabel(code, item.lotteryName || item.lotteryType),
    lotteryCode: String(item.lotteryCode || code || '').trim(),
    drawNum: String(item.lotteryDrawNum || item.drawNum || '').trim(),
    numbers: safeSplitNumbers(item.lotteryDrawResult || item.result),
    drawTime: String(item.lotteryDrawTime || item.drawTime || '').trim(),
  }
}

function sortDrawResults(rows: NormalizedDrawResult[]) {
  return rows
    .filter((item) => item.drawNum && item.numbers.length)
    .sort((a, b) => {
      const drawDiff = drawNumScore(b.drawNum) - drawNumScore(a.drawNum)
      if (drawDiff !== 0) return drawDiff
      return timeScore(b.drawTime) - timeScore(a.drawTime)
    })
}

export interface DrawResultsPage {
  rows: NormalizedDrawResult[]
  /** 后端开奖记录总数（一期一行，即历史总期数）；fallback 路径无 total 时按当前行数估算 */
  total: number
}

/**
 * 拉取一页开奖记录并归一化：POST /lotteryInfo/list（分页走 query，彩种走 body），
 * 列表为空时 fallback GET /lotteryInfo/dailyDetail 的 history。
 */
export async function fetchDrawResultsPage(code: string, pageSize = 120): Promise<DrawResultsPage> {
  const lotteryCode = String(code || '350133').trim()

  const page = await post<{ rows: any[]; total: number }>(
    `/lotteryInfo/list?pageNum=1&pageSize=${pageSize}`,
    { lotteryCode },
    { paged: true, silent401: true },
  )

  const rows = sortDrawResults(
    (page.rows || []).map((item: BackendDrawResult) => normalizeDrawResult(item, lotteryCode)),
  )

  if (rows.length) {
    return { rows, total: Number(page.total) || rows.length }
  }

  const detail = await get<any>('/lotteryInfo/dailyDetail', { code: lotteryCode, pageNum: 1, pageSize }, { silent401: true })
  const detailData = unwrapAjaxData<any>(detail) || {}
  const detailRows = Array.isArray(detailData.history) ? detailData.history : []
  const fallbackRows = sortDrawResults(
    detailRows.map((item: BackendDrawResult) => normalizeDrawResult(item, lotteryCode)),
  )
  return { rows: fallbackRows, total: fallbackRows.length }
}

/** 直播源地址（dailyDetail 的 liveSource 字段），失败由调用方 catch 降级为 null */
export async function fetchDrawLiveSource(code: string) {
  const lotteryCode = String(code || '350133').trim()
  const resp = await get<any>('/lotteryInfo/dailyDetail', { code: lotteryCode }, { silent401: true })
  return unwrapAjaxData<any>(resp)?.liveSource || null
}
