import Taro from '@tarojs/taro'
import { completePayOrder, createPayOrder, queryPayOrder } from '@/services/api'
import { launchWxAppPay } from '@/utils/wxPay'

/**
 * 支付链路共享助手（会员购买 / 积分充值共用）：
 * - 购买链路：/pay/create → 拉起渠道支付 → /pay/query 轮询至 PAID/CLOSED 终态
 * - MOCK 渠道（服务端 dev 自动启用）无真实网关回调：payParams 带 mockPayToken，
 *   下单后需主动调 /pay/complete/{orderNo} 模拟付款；真实渠道由网关回调履约，客户端只轮询
 * - 后端 payParams 结构（PayChannel 各实现）：微信 H5 {mode:'redirect', h5Url}、
 *   支付宝 {mode:'payForm', payForm}、MOCK {mockPayToken, payUrl:'mock://...'}、
 *   APP 场景 {mode:'app', orderInfo}（RN 端经 @/utils/wxPay 走 react-native-wechat-lib 原生 SDK）
 */

export type PollResult = 'paid' | 'closed' | 'timeout'

/** 轮询查单：先查后睡，识别 PAID/CLOSED 终态，~10s 截止时间（单次查询 retry:false，见 api.ts） */
const POLL_INTERVAL = 800
const POLL_TIMEOUT = 10000

const sleep = (ms: number) => new Promise<void>((resolve) => setTimeout(resolve, ms))

export async function pollOrderPaid(orderNo: string): Promise<PollResult> {
  const deadline = Date.now() + POLL_TIMEOUT
  for (;;) {
    try {
      const order = await queryPayOrder(orderNo)
      const status = String(order?.status || '').toUpperCase()
      if (status === 'PAID') return 'paid'
      if (status === 'CLOSED') return 'closed'
    } catch {
      // 单次查询失败不中断轮询
    }
    if (Date.now() >= deadline) return 'timeout'
    await sleep(POLL_INTERVAL)
  }
}

interface ParsedPayParams {
  /** 跳转链接（微信 H5 h5Url 等）；空串表示非链接参数 */
  url: string
  /** 支付宝支付表单 HTML（需自渲染提交） */
  payForm: string
  /** MOCK 渠道标识：存在即需客户端补调 /pay/complete 模拟付款 */
  mockPayToken: string
  /** APP 支付参数（mode:'app' 时的 orderInfo，JSON 字符串或对象）；RN 端走微信原生 SDK */
  appOrderInfo: unknown
}

/** 解析 payParams（兼容 JSON 字符串 / 对象；字段名白名单含后端实际使用的 h5Url/payForm/mockPayToken） */
function parsePayParams(payParams: unknown): ParsedPayParams {
  const result: ParsedPayParams = { url: '', payForm: '', mockPayToken: '', appOrderInfo: null }
  if (!payParams) return result
  let obj: any = payParams
  if (typeof payParams === 'string') {
    const text = payParams.trim()
    if (/^https?:\/\//.test(text)) {
      result.url = text
      return result
    }
    try {
      obj = JSON.parse(text)
    } catch {
      return result
    }
  }
  if (typeof obj !== 'object' || !obj) return result
  for (const key of ['payUrl', 'payurl', 'url', 'h5Url', 'mwebUrl', 'mweb_url', 'cashierUrl', 'orderUrl']) {
    const value = String(obj[key] || '').trim()
    if (/^https?:\/\//.test(value)) {
      result.url = value
      break
    }
  }
  result.payForm = String(obj.payForm || '').trim()
  result.mockPayToken = String(obj.mockPayToken || '').trim()
  if (String(obj.mode || '').toLowerCase() === 'app' && obj.orderInfo) {
    result.appOrderInfo = obj.orderInfo
  }
  return result
}

/** H5：渲染并提交支付宝支付表单（pageExecute 返回的 HTML 内嵌 script 不执行，需手动 submit） */
function submitPayForm(payForm: string) {
  const div = document.createElement('div')
  div.innerHTML = payForm
  document.body.appendChild(div)
  const form = div.querySelector('form')
  if (form) {
    form.submit()
  } else {
    div.remove()
  }
}

export type LaunchResult = 'launched' | 'unsupported'

/**
 * 拉起渠道支付，返回是否成功拉起。
 * - APP 支付参数（mode:'app'）：RN 端经 @/utils/wxPay 调 react-native-wechat-lib 拉起微信；
 *   H5 端返回 unsupported。
 * - 跳转链接：H5 当前页跳转（window.open 在 await 之后会被浏览器拦截丢失用户激活态，
 *   且微信 H5 支付本就要求当前页跳转）；RN 走 Taro.openUrl 调起系统浏览器。
 * - 支付宝支付表单：仅 H5 可渲染提交，RN 端返回 unsupported。
 */
export async function launchChannelPay(payParams: unknown): Promise<LaunchResult> {
  const { url, payForm, appOrderInfo } = parsePayParams(payParams)
  if (appOrderInfo) {
    if (process.env.TARO_ENV !== 'h5') {
      return (await launchWxAppPay(appOrderInfo)) ? 'launched' : 'unsupported'
    }
    return 'unsupported'
  }
  if (process.env.TARO_ENV === 'h5') {
    if (payForm) {
      submitPayForm(payForm)
      return 'launched'
    }
    if (url) {
      window.location.href = url
      return 'launched'
    }
    return 'unsupported'
  }
  if (url) {
    // openUrl 为 taro-rn 专有 API（@tarojs/taro 公共类型未声明，故 as any）
    ;(Taro as any).openUrl?.({ url })
    return 'launched'
  }
  return 'unsupported'
}

/** runCashPay 各环节文案（调用方按业务传入） */
export interface CashPayLabels {
  /** 轮询 loading */
  polling: string
  success: string
  /** 轮询超时（订单仍 PENDING） */
  confirming: string
  /** 订单 CLOSED 终态（用户取消/未支付被关单） */
  closed: string
  /** 下单失败兜底 */
  fail: string
  /** 当前端无法拉起支付（如 RN 遇支付表单） */
  launchFail: string
}

/**
 * 现金渠道支付编排：下单 → 拉起渠道支付（MOCK 按 mockPayToken 信号补调 complete 模拟付款）
 * → loading 轮询至终态 → toast。返回是否已 PAID；调用方负责 paying 防重与成功后的刷新动作。
 */
export async function runCashPay(options: {
  bizType: 'MEMBER_SUBSCRIPTION' | 'INTEGRAL_RECHARGE'
  bizId: number
  channel: 'MOCK' | 'WX_PAY' | 'ALIPAY'
  labels: CashPayLabels
}): Promise<boolean> {
  const { labels } = options
  try {
    const order = await createPayOrder({
      bizId: options.bizId,
      bizType: options.bizType,
      channel: options.channel,
    })
    const orderNo = String(order?.orderNo || '')
    if (!orderNo) {
      Taro.showToast({ title: labels.fail, icon: 'none' })
      return false
    }
    if (parsePayParams(order?.payParams).mockPayToken) {
      // MOCK 渠道（仅 dev 联调）：无真实网关回调，需客户端主动调 complete 模拟付款，
      // 后端走与真实回调同一套 markPaid（归属/渠道/mock 开关/幂等四道闸，重复调用不二次履约）
      await completePayOrder(orderNo)
    } else if ((await launchChannelPay(order?.payParams)) === 'unsupported') {
      // 订单已创建（PENDING）但当前端无法拉起支付，以后端订单状态为准
      Taro.showToast({ title: labels.launchFail, icon: 'none' })
      return false
    }
    Taro.showLoading({ title: labels.polling, mask: true })
    let result: PollResult
    try {
      result = await pollOrderPaid(orderNo)
    } finally {
      Taro.hideLoading()
    }
    if (result === 'paid') {
      Taro.showToast({ title: labels.success, icon: 'success' })
      return true
    }
    // 轮询超时/关单：以后端订单状态为准，提示用户稍后查看
    Taro.showToast({ title: result === 'closed' ? labels.closed : labels.confirming, icon: 'none' })
    return false
  } catch (error: any) {
    // 后端业务错误信息原样透出
    Taro.showToast({ title: error?.message || labels.fail, icon: 'none' })
    return false
  }
}
