import { DeviceEventEmitter } from 'react-native'

/**
 * RN 端 polyfill：RN >=0.71 从 EventEmitter 上移除了 removeListener，
 * 但 @tarojs/components-rn 内置的 @ant-design/react-native Portal.Host
 * 卸载时仍调用 TopViewEventEmitter.removeListener，直接抛错。
 * 这里包一层 addListener：
 * - 给返回的订阅对象包装 remove()：惯用 sub.remove() 移除路径同样清理记录，不漏记
 * - 同一 listener 重复注册按数组记录，removeListener 移除最新一条（对齐 RN 老版语义）
 * 需在 Portal.Host 挂载前执行（app.tsx 顶部导入）。
 */
const emitter = DeviceEventEmitter as any
if (emitter && typeof emitter.removeListener !== 'function') {
  const subs = new Map<any, Array<{ remove: () => void }>>()
  const rawAddListener = emitter.addListener.bind(emitter)

  emitter.addListener = (eventType: string, listener: any, context?: any) => {
    const sub = rawAddListener(eventType, listener, context)
    const rawRemove = sub.remove.bind(sub)
    const list = subs.get(listener) || []
    list.push(sub)
    subs.set(listener, list)

    sub.remove = () => {
      rawRemove()
      const current = subs.get(listener)
      if (current) {
        const index = current.indexOf(sub)
        if (index >= 0) current.splice(index, 1)
        if (!current.length) subs.delete(listener)
      }
    }
    return sub
  }

  emitter.removeListener = (_eventType: string, listener: any) => {
    const list = subs.get(listener)
    const sub = list && list[list.length - 1]
    if (sub) {
      sub.remove()
    }
  }
}
