// ── 纯函数：codeMode / 号码行（移植自 Web publish.vue，规则见 Web PRD §6.7.2） ──

function normalizeCodeMode(m?: string) {
  const v = String(m || '').trim().toUpperCase()
  return !v ? '' : v.startsWith('KILL') ? `杀${v.replace('KILL', '')}` : v
}

function lettersFromMode(mode: string): string[] {
  const n = normalizeCodeMode(mode)
  if (!n) return []
  if (n.startsWith('杀')) {
    const l = n.replace('杀', '').replace(/X/g, '').trim()
    return l ? [l] : []
  }
  return n.replace(/X/g, '').split('').filter(Boolean)
}

function isKillCodeMode(m?: string) {
  return normalizeCodeMode(m).startsWith('杀')
}

function killPositionLabel(m?: string) {
  const l = lettersFromMode(String(m || ''))[0] || ''
  return l ? publishLabels.positionSuffix(l) : String(m || '')
}

function normalizeDigitList(list: string[]) {
  return Array.from(new Set(list.filter((i) => /^\d$/.test(i)))).sort((a, b) => Number(a) - Number(b))
}

function parseDigitString(raw?: string | number | null) {
  return String(raw || '')
    .split(/[\s,，;；]+/)
    .map((s) => s.trim())
    .filter((s) => /^\d$/.test(s))
}

function selectionLimitForMode(plan: PredictionPlanState) {
  if (plan.dimension === '-2') return plan.killType === 'killOne' ? 1 : 2
  if (isKillCodeMode(plan.codeMode)) return 2
  return parseInt(plan.scaleSize) || 6
}

/** 链式子集修剪：看好 ⊆ 已选、主攻 ⊆ 看好、重点 ⊆ 主攻；上级 ≤1 个时下级清空 */
function pruneRow(row: PositionInput, plan: PredictionPlanState): PositionInput {
  const limit = selectionLimitForMode(plan)
  const selected = normalizeDigitList(row.selectedNumbers).slice(0, limit)
  const empty = { lookGoodNumbers: [], mainNumbers: [], pointNumbers: [] }
  if (isKillCodeMode(plan.codeMode) || plan.dimension === '-2' || selected.length <= 1) {
    return { ...row, selectedNumbers: selected, ...empty }
  }
  const lookGood = normalizeDigitList(row.lookGoodNumbers.filter((i) => selected.includes(i)))
  if (lookGood.length <= 1) return { ...row, selectedNumbers: selected, lookGoodNumbers: lookGood, mainNumbers: [], pointNumbers: [] }
  const main = normalizeDigitList(row.mainNumbers.filter((i) => lookGood.includes(i)))
  if (main.length <= 1) return { ...row, selectedNumbers: selected, lookGoodNumbers: lookGood, mainNumbers: main, pointNumbers: [] }
  const point = normalizeDigitList(row.pointNumbers.filter((i) => main.includes(i)))
  return { position: row.position, selectedNumbers: selected, lookGoodNumbers: lookGood, mainNumbers: main, pointNumbers: point }
}

/** 按 codeMode 重建号码行；新旧均非杀码时按位置字母保留已选号码 */
function rebuildRows(plan: PredictionPlanState, prevRows: PositionInput[], preserve: boolean): PositionInput[] {
  const prevMap = prevRows.reduce<Record<string, PositionInput>>((acc, r) => {
    acc[r.position] = r
    return acc
  }, {})
  return lettersFromMode(plan.codeMode).map((letter) =>
    pruneRow(
      {
        position: letter,
        selectedNumbers: preserve ? normalizeDigitList(prevMap[letter]?.selectedNumbers || []) : [],
        lookGoodNumbers: preserve ? normalizeDigitList(prevMap[letter]?.lookGoodNumbers || []) : [],
        mainNumbers: preserve ? normalizeDigitList(prevMap[letter]?.mainNumbers || []) : [],
        pointNumbers: preserve ? normalizeDigitList(prevMap[letter]?.pointNumbers || []) : [],
      },
      plan,
    ),
  )
}

function summaryDigits(list: string[]) {
  return normalizeDigitList(list).join('')
}

/** 选号模式自动生成 predictionData 文本（`【ABXX】\nA:123看好1主攻2…`） */
function buildAutoPredictionSummary(plan: PredictionPlanState): string {
  const km = isKillCodeMode(plan.codeMode)
  const lines = plan.rows
    .map((row) => {
      const s = summaryDigits(row.selectedNumbers)
      if (!s) return ''
      if (km || plan.dimension === '-2') return `${row.position}：杀${s}`
      const lg = summaryDigits(row.lookGoodNumbers.filter((i) => row.selectedNumbers.includes(i)))
      const m = summaryDigits(row.mainNumbers.filter((i) => row.lookGoodNumbers.includes(i)))
      const p = summaryDigits(row.pointNumbers.filter((i) => row.mainNumbers.includes(i)))
      return `${row.position}:${s}${lg ? `看好${lg}` : ''}${m ? `主攻${m}` : ''}${p ? `重点${p}` : ''}`
    })
    .filter(Boolean)
  return lines.length ? [`【${plan.codeMode}】`, ...lines].join('\n') : ''
}

/** codeMode/planMode 归一化：杀X → KILLX，planMode 杀一码 -1 / 杀二码 -2 / 其余按非 X 位数 */
function resolveModeMapping(cm: string, plan: PredictionPlanState) {
  let m = normalizeCodeMode(cm)
  let pm = ''
  if (m.startsWith('杀')) {
    m = m.replace('杀', 'KILL')
    pm = plan.killType === 'killOne' ? '-1' : '-2'
  } else if (m.includes('X')) {
    pm = String(m.replace(/X/g, '').length)
  } else {
    const c = m.replace(/[^A-Z]/g, '').length
    pm = String(c >= 5 ? 5 : c)
  }
  return { codeMode: m, planMode: pm }
}

/** 编辑回填：后端 codeMode → 矩阵中最接近的前端 codeMode */
function matchFrontendCodeMode(backendCode: string, lotteryCode: string, dimension: string) {
  const normalized = normalizeCodeMode(backendCode)
  if (normalized.startsWith('杀')) {
    const pos = normalized.replace('杀', '').trim() || 'A'
    return `杀${pos}`
  }
  const letters = normalized.replace(/X/g, '').split('').filter(Boolean).join('')
  const options = getCodeModeOptions(lotteryCode as LotteryCode, dimension as DimensionCode)
  const matched = options.find((opt) => opt.replace(/X/g, '').split('').filter(Boolean).join('') === letters)
  return matched || options[0] || backendCode
}

function createDefaultPlan(): PredictionPlanState {
  return {
    dimension: '2',
    inputMode: 'standard',
    codeMode: '',
    scaleSize: '6*6',
    killType: 'killTwo',
    predictionData: '',
    freeModeFocus: '',
    freeModeMain: '',
    freeModeRangeType: 'lower',
    rows: [],
  }
}

/** 彩种切换后收敛方案的维度/位置/规模并重建号码行 */
function fixPlanForLottery(plan: PredictionPlanState, lotteryCode: LotteryCode): PredictionPlanState {
  const dims = getDimensionOptions(lotteryCode, plan.inputMode)
  let dimension = plan.dimension
  if (!dims.some((d) => d.value === dimension)) dimension = (dims[0]?.value || '2') as DimensionCode
  const modes = getCodeModeOptions(lotteryCode, dimension)
  let codeMode = plan.codeMode
  if (!modes.includes(codeMode)) codeMode = modes[0] || ''
  const sizes = getPrecisionOptions(dimension)
  let scaleSize = plan.scaleSize
  if (sizes.length && !sizes.includes(scaleSize)) scaleSize = sizes[0]
  const next: PredictionPlanState = { ...plan, dimension, codeMode, scaleSize }
  const preserve = !isKillCodeMode(plan.codeMode) && !isKillCodeMode(codeMode)
  next.rows = rebuildRows(next, plan.rows, preserve)
  return next
}

/** 期号选项归一化：当期置首，「待开奖」期优先，最多 21 项 */
function normalizeSingleIssueOptions(list: IssueItem[], lotteryCode: string, currentDrawNum: string): IssueOption[] {
  const map = new Map<string, IssueOption>()
  const current = String(currentDrawNum || '').trim()
  if (current) map.set(current, { drawNum: current, label: `第${current}期 当期` })
  const pending: IssueOption[] = []
  const fallback: IssueOption[] = []
  list
    .filter((item) => !lotteryCode || item.lotteryCode === lotteryCode)
    .forEach((item) => {
      const drawNum = String(item.drawNum || '').trim()
      const label = String(item.label || '').trim()
      if (!drawNum || map.has(drawNum)) return
      const option: IssueOption = { drawNum, label: label || `第${drawNum}期` }
      ;(label.includes('待开奖') ? pending : fallback).push(option)
    })
  pending.forEach((opt) => map.set(opt.drawNum, opt))
  fallback.forEach((opt) => map.set(opt.drawNum, opt))
  return Array.from(map.values()).slice(0, 21)
}

/** 计划期数取各方案维度允许上限的交集 */
function effectivePlanNumOptions(list: PredictionPlanState[]): number[] {
  if (!list.length) return getPlanNumOptions('2')
  const globalMax = Math.min(
    ...list.map((p) => {
      const opts = getPlanNumOptions(p.dimension)
      return opts[opts.length - 1] || 6
    }),
  )
  return getPlanNumOptions('3').filter((n) => n <= globalMax)
}

// ── 草稿（非编辑模式 500ms 防抖持久化；结构对齐 Web publishDraft 新格式） ──

interface PublishDraft {
  exchange: { title: string; content: string; lotteryCode: string }
  prediction: {
    lotteryCode: string
    forecastPhase: string
    planNum: number
    lotteryDrawNum: string
    title: string
    summarize: string
  }
  plans: PredictionPlanState[]
  activePlanIndex?: number
}

async function loadPublishDraft(): Promise<PublishDraft | null> {
  try {
    const res = await Taro.getStorage({ key: STORAGE_KEYS.publishDraft })
    const raw = res.data
    if (!raw) return null
    const parsed = JSON.parse(typeof raw === 'string' ? raw : String(raw))
    if (!parsed || typeof parsed !== 'object' || !Array.isArray(parsed.plans) || !parsed.plans.length) return null
    return {
      exchange: {
        title: String(parsed.exchange?.title || ''),
        content: String(parsed.exchange?.content || ''),
        lotteryCode: String(parsed.exchange?.lotteryCode || ''),
      },
      prediction: {
        lotteryCode: String(parsed.prediction?.lotteryCode || ''),
        forecastPhase: String(parsed.prediction?.forecastPhase || '0'),
        planNum: Number(parsed.prediction?.planNum || 3),
        lotteryDrawNum: String(parsed.prediction?.lotteryDrawNum || ''),
        title: String(parsed.prediction?.title || ''),
        summarize: String(parsed.prediction?.summarize || ''),
      },
      plans: parsed.plans.map((plan: any) => ({
        dimension: (plan.dimension || '2') as DimensionCode,
        inputMode: (plan.inputMode || 'standard') as PredictionInputMode,
        codeMode: String(plan.codeMode || ''),
        scaleSize: String(plan.scaleSize || '6*6'),
        killType: (plan.killType || 'killTwo') as KillTypeValue,
        predictionData: String(plan.predictionData || ''),
        freeModeFocus: String(plan.freeModeFocus || ''),
        freeModeMain: String(plan.freeModeMain || ''),
        freeModeRangeType: (plan.freeModeRangeType === 'upper' ? 'upper' : 'lower') as FreeRangeType,
        rows: Array.isArray(plan.rows)
          ? plan.rows.map((row: any) => ({
              position: String(row.position || ''),
              selectedNumbers: Array.isArray(row.selectedNumbers) ? row.selectedNumbers.map(String) : [],
              lookGoodNumbers: Array.isArray(row.lookGoodNumbers) ? row.lookGoodNumbers.map(String) : [],
              mainNumbers: Array.isArray(row.mainNumbers) ? row.mainNumbers.map(String) : [],
              pointNumbers: Array.isArray(row.pointNumbers) ? row.pointNumbers.map(String) : [],
            }))
          : [],
      })),
      activePlanIndex: Math.max(0, Math.min(Number(parsed.activePlanIndex || 0), parsed.plans.length - 1)),
    }
  } catch {
    return null
  }
}

function clearPublishDraft() {
  Taro.removeStorage({ key: STORAGE_KEYS.publishDraft }).catch(() => {})
}

function toast(title: string) {
  Taro.showToast({ title, icon: 'none' })
}

/**
 * 发帖/编辑页（产品方案 §6.6、Web PRD §6.7.2）：
 * `?type=exchange|prediction&partition={slug|all}&mode=edit&id=`
 */
export default function PublishPage() {
  const params = Taro.getCurrentInstance().router?.params || {}
  const publishType: PublishType = params.type === 'prediction' ? 'prediction' : 'exchange'
  const isEditMode = params.mode === 'edit' && !!params.id
  const editPostId = String(params.id || '')
  const partitionSlug = String(params.partition || '')
  const partitionCode = getLotteryCodeBySlug(partitionSlug)
  const isAllPartition = !partitionCode
  // 具体分区进入时彩种锁定为分区对应彩种；all/未知分区由用户选择（默认排列五）
  const partitionLotteryCode: LotteryCode = partitionCode || '350133'

  const { state: authState, isLoggedIn, profile } = useAuth()

  // ── 交流帖表单 ──
  const [exchangeTitle, setExchangeTitle] = useState('')
  const [exchangeContent, setExchangeContent] = useState('')
  const [exchangeLotteryCode, setExchangeLotteryCode] = useState<LotteryCode>(partitionLotteryCode)
  const [exchangePics, setExchangePics] = useState<string[]>([])

  // ── 预测帖帖子级表单 ──
  const [predForm, setPredForm] = useState({
    lotteryCode: '' as string,
    forecastPhase: '0' as '0' | '1',
    planNum: 3,
    lotteryDrawNum: '',
    title: '',
    summarize: '',
  })
  const [plans, setPlans] = useState<PredictionPlanState[]>([createDefaultPlan()])
  const [activePlanIndex, setActivePlanIndex] = useState(0)
  const [titleSuffix, setTitleSuffix] = useState('')
  const [termMap, setTermMap] = useState<Record<string, string>>({})
  const [issueOptions, setIssueOptions] = useState<IssueOption[]>([])
  const [loadingTermMeta, setLoadingTermMeta] = useState(false)
  const [editPlanStartIssue, setEditPlanStartIssue] = useState('')
  const [editingSourceType, setEditingSourceType] = useState('F')
  const [editingExchangeUserId, setEditingExchangeUserId] = useState<number | undefined>(undefined)
  const [publishing, setPublishing] = useState(false)
  const [loadingEdit, setLoadingEdit] = useState(false)
  /** 草稿/编辑回填完成后才开启草稿自动保存，避免空表单覆盖storage中的草稿 */
  const [formReady, setFormReady] = useState(false)

  const currentPlan = plans[activePlanIndex] || plans[0] || createDefaultPlan()
  const predLotteryCode = (predForm.lotteryCode || '') as LotteryCode

  // ── 期号 / 标题前缀派生 ──
  const currentPredictionIssue = issueOptions[0]?.drawNum || termMap[predForm.lotteryCode] || ''

  const planIssueRange = useMemo(() => {
    const start = (isEditMode && editPlanStartIssue) || currentPredictionIssue
    if (!start) return null
    const count = Number(predForm.planNum) || 0
    if (count < 1) return null
    // 升序期号列表定位起始期后第 planNum 个；定位不到按数字递增兜底（跨年期号可能不准，仅保证前缀不消失）
    const sorted = issueOptions
      .map((opt) => opt.drawNum)
      .filter((d) => /^\d+$/.test(d))
      .sort((a, b) => Number(a) - Number(b))
    const startIdx = sorted.indexOf(start)
    const listed = startIdx !== -1 ? sorted[startIdx + count - 1] : undefined
    if (listed) return { start, end: listed }
    const startNum = Number(start)
    if (!Number.isFinite(startNum)) return null
    return { start, end: String(startNum + count - 1).padStart(start.length, '0') }
  }, [isEditMode, editPlanStartIssue, currentPredictionIssue, predForm.planNum, issueOptions])

  const predictionTitlePrefix = useMemo(() => {
    if (!predForm.lotteryCode) return ''
    const label = getLotteryLabel(predForm.lotteryCode)
    if (predForm.forecastPhase === '1') {
      return planIssueRange ? `${label}${planIssueRange.start}~${planIssueRange.end}期计划` : ''
    }
    return currentPredictionIssue ? `${label}${currentPredictionIssue}期预测` : ''
  }, [predForm.lotteryCode, predForm.forecastPhase, planIssueRange, currentPredictionIssue])

  // 期号加载完成仍无当期期号时给出可见反馈
  const termMetaMissing = !loadingTermMeta && !!predForm.lotteryCode && !predictionTitlePrefix

  const suffixMaxLength = Math.max(0, POST_TITLE_MAX_LENGTH - predictionTitlePrefix.length)

  function parseTitleSuffix(title: string, prefix: string): string {
    const t = String(title || '').trim()
    if (!t) return ''
    if (prefix && t.startsWith(prefix)) return t.slice(prefix.length).trim().replace(/^-\s*/, '')
    // 兼容旧格式：[彩种] 期号期预测 / 期计划 - 用户标题
    const oldFormatMatch = t.match(/^\[([^\]]+)\]\s*(.+?(?:预测|计划))(?:\s*-\s*(.*))?$/)
    if (oldFormatMatch) return (oldFormatMatch[3] || '').trim()
    // 兜底：按「期预测 / 期计划」截断保留用户后缀
    for (const marker of ['期预测', '期计划']) {
      const idx = t.indexOf(marker)
      if (idx !== -1) return t.slice(idx + marker.length).trim().replace(/^-\s*/, '')
    }
    return t
  }

  function composeTitle(prefix: string, suffix: string): string {
    const s = suffix.trim()
    if (!prefix) return s.slice(0, POST_TITLE_MAX_LENGTH)
    return (s ? `${prefix} ${s}` : prefix).slice(0, POST_TITLE_MAX_LENGTH)
  }

  // 非编辑模式：标题 = 自动前缀 + 用户后缀，随前缀/后缀变化自动重组
  useEffect(() => {
    if (isEditMode || publishType !== 'prediction') return
    setPredForm((f) => {
      const next = composeTitle(predictionTitlePrefix, titleSuffix)
      return f.title === next ? f : { ...f, title: next }
    })
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [predictionTitlePrefix, titleSuffix, isEditMode, publishType])

  // ── 期号加载（term 失败重试一次；issues 失败降级仅有当期） ──
  const latestMetaCodeRef = useRef('')
  async function loadPredictionMeta(lotteryCode: string) {
    if (!lotteryCode) return
    latestMetaCodeRef.current = lotteryCode
    setLoadingTermMeta(true)
    const fetchTermWithRetry = async () => {
      try {
        return await fetchForumTerm(lotteryCode)
      } catch {
        return fetchForumTerm(lotteryCode)
      }
    }
    try {
      const [termResult, issueResult] = await Promise.allSettled([fetchTermWithRetry(), fetchForumIssues(lotteryCode)])
      if (latestMetaCodeRef.current !== lotteryCode) return
      let current = ''
      if (termResult.status === 'fulfilled') {
        const map = termResult.value?.map || {}
        setTermMap((prev) => ({ ...prev, ...map }))
        current = String(map[lotteryCode] || termResult.value?.current || '')
      }
      const list = issueResult.status === 'fulfilled' && Array.isArray(issueResult.value?.list) ? issueResult.value.list : []
      const options = normalizeSingleIssueOptions(list, lotteryCode, current)
      setIssueOptions(options)
      // 单期模式锁定当期：当前期号不在列表内时回落到当期
      setPredForm((f) => {
        if (f.forecastPhase !== '0') return f
        if (options.some((o) => o.drawNum === f.lotteryDrawNum)) return f
        return { ...f, lotteryDrawNum: options[0]?.drawNum || '' }
      })
    } catch {
      /* ignore：期号未加载由 termMetaMissing 兜底提示 */
    } finally {
      if (latestMetaCodeRef.current === lotteryCode) setLoadingTermMeta(false)
    }
  }

  // ── 方案操作 ──
  function clampPlanNum(nextPlans: PredictionPlanState[]) {
    setPredForm((f) => {
      if (f.forecastPhase !== '1') return f
      const opts = effectivePlanNumOptions(nextPlans)
      if (opts.includes(f.planNum)) return f
      return { ...f, planNum: opts[opts.length - 1] }
    })
  }

  function applyPlans(next: PredictionPlanState[]) {
    setPlans(next)
    clampPlanNum(next)
  }

  function updatePlanAt(index: number, updater: (p: PredictionPlanState) => PredictionPlanState) {
    applyPlans(plans.map((p, i) => (i === index ? updater(p) : p)))
  }

  const handleDimension = (index: number, value: string) => {
    const lotteryCode = predLotteryCode || partitionLotteryCode
    updatePlanAt(index, (p) => {
      const dimension = value as DimensionCode
      const modes = getCodeModeOptions(lotteryCode, dimension)
      const codeMode = modes.includes(p.codeMode) ? p.codeMode : modes[0] || ''
      const sizes = getPrecisionOptions(dimension)
      const scaleSize = sizes.length && !sizes.includes(p.scaleSize) ? sizes[0] : p.scaleSize
      const next: PredictionPlanState = { ...p, dimension, codeMode, scaleSize }
      const preserve = !isKillCodeMode(p.codeMode) && !isKillCodeMode(codeMode)
      next.rows = rebuildRows(next, p.rows, preserve)
      return next
    })
  }

  const handleCodeMode = (index: number, value: string) => {
    updatePlanAt(index, (p) => {
      const next: PredictionPlanState = { ...p, codeMode: value }
      const preserve = !isKillCodeMode(p.codeMode) && !isKillCodeMode(value)
      next.rows = rebuildRows(next, p.rows, preserve)
      return next
    })
  }

  const handleInputMode = (index: number, value: string) => {
    const lotteryCode = predLotteryCode || partitionLotteryCode
    updatePlanAt(index, (p) => {
      const inputMode = value as PredictionInputMode
      let next: PredictionPlanState = { ...p, inputMode }
      if (inputMode === 'free') {
        // 自由模式禁选杀码维度；清空号码数据与区间
        let dimension = next.dimension
        if (dimension === '-2') {
          const dims = getDimensionOptions(lotteryCode, 'free')
          dimension = (dims[0]?.value || '2') as DimensionCode
        }
        const modes = getCodeModeOptions(lotteryCode, dimension)
        const codeMode = modes.includes(next.codeMode) ? next.codeMode : modes[0] || ''
        const sizes = getPrecisionOptions(dimension)
        const scaleSize = sizes.length && !sizes.includes(next.scaleSize) ? sizes[0] : next.scaleSize
        next = {
          ...next,
          dimension,
          codeMode,
          scaleSize,
          predictionData: '',
          freeModeFocus: '',
          freeModeMain: '',
          freeModeRangeType: 'lower',
        }
      }
      next.rows = rebuildRows(next, [], false)
      return next
    })
  }

  const handleKillType = (index: number, value: string) => {
    updatePlanAt(index, (p) => {
      const next: PredictionPlanState = { ...p, killType: value as KillTypeValue }
      next.rows = next.rows.map((r) => pruneRow(r, next))
      return next
    })
  }

  const handleScaleSize = (index: number, value: string) => {
    updatePlanAt(index, (p) => {
      const next: PredictionPlanState = { ...p, scaleSize: value }
      next.rows = next.rows.map((r) => pruneRow(r, next))
      return next
    })
  }

  const handleRangeType = (index: number, value: FreeRangeType) => {
    updatePlanAt(index, (p) => ({
      ...p,
      freeModeRangeType: value,
      // lower 预填 23 个示例号码；upper 清空三栏
      predictionData: value === 'lower' ? RANGE_LOWER_NUMBERS : '',
      freeModeFocus: '',
      freeModeMain: '',
    }))
  }

  const handleToggleDigit = (index: number, position: string, digit: string) => {
    const plan = plans[index]
    const row = plan?.rows.find((r) => r.position === position)
    if (!plan || !row) return
    const limit = selectionLimitForMode(plan)
    if (!row.selectedNumbers.includes(digit) && row.selectedNumbers.length >= limit) {
      toast(publishLabels.digitOverflow(limit))
      return
    }
    updatePlanAt(index, (p) => ({
      ...p,
      rows: p.rows.map((r) => {
        if (r.position !== position) return r
        const selected = r.selectedNumbers.includes(digit)
          ? r.selectedNumbers.filter((x) => x !== digit)
          : normalizeDigitList([...r.selectedNumbers, digit])
        return pruneRow({ ...r, selectedNumbers: selected }, p)
      }),
    }))
  }

  const handleToggleMark = (index: number, position: string, digit: string, level: MarkLevel) => {
    updatePlanAt(index, (p) => ({
      ...p,
      rows: p.rows.map((r) => {
        if (r.position !== position) return r
        const toggle = (list: string[], allow: boolean) => {
          if (!allow) return list
          return list.includes(digit) ? list.filter((x) => x !== digit) : normalizeDigitList([...list, digit])
        }
        const next: PositionInput = {
          ...r,
          lookGoodNumbers: level === 'lookGood' ? toggle(r.lookGoodNumbers, r.selectedNumbers.includes(digit)) : r.lookGoodNumbers,
          mainNumbers: level === 'main' ? toggle(r.mainNumbers, r.lookGoodNumbers.includes(digit)) : r.mainNumbers,
          pointNumbers: level === 'point' ? toggle(r.pointNumbers, r.mainNumbers.includes(digit)) : r.pointNumbers,
        }
        return pruneRow(next, p)
      }),
    }))
  }

  const addPlan = () => {
    if (plans.length >= FORECAST_PLAN_MAX) {
      toast(publishLabels.maxPlanReached)
      return
    }
    const base = currentPlan
    const newPlan: PredictionPlanState = {
      dimension: base.dimension,
      inputMode: base.inputMode,
      codeMode: base.codeMode,
      scaleSize: base.scaleSize,
      killType: base.killType,
      predictionData: '',
      freeModeFocus: '',
      freeModeMain: '',
      freeModeRangeType: 'lower',
      rows: [],
    }
    newPlan.rows = rebuildRows(newPlan, [], false)
    applyPlans([...plans, newPlan])
    setActivePlanIndex(plans.length)
  }

  const removePlan = (index: number) => {
    if (plans.length <= 1) {
      toast(publishLabels.atLeastOnePlan)
      return
    }
    Taro.showModal({
      title: publishLabels.removePlanConfirmTitle,
      content: publishLabels.removePlanConfirmMessage,
      confirmText: publishLabels.removePlanConfirmButton,
      confirmColor: '#b83237',
    }).then((res) => {
      if (!res.confirm) return
      const next = plans.filter((_, i) => i !== index)
      applyPlans(next)
      setActivePlanIndex((a) => Math.min(a, next.length - 1))
    })
  }

  // ── 帖子级配置变更 ──
  const handleLotteryChange = (code: string) => {
    const lotteryCode = code as LotteryCode
    setPredForm((f) => ({ ...f, lotteryCode }))
    applyPlans(plans.map((p) => fixPlanForLottery(p, lotteryCode)))
    loadPredictionMeta(lotteryCode)
  }

  const handlePhase = (phase: string) => {
    if (phase === '0') {
      setPredForm((f) => ({
        ...f,
        forecastPhase: '0',
        lotteryDrawNum: issueOptions.some((o) => o.drawNum === f.lotteryDrawNum)
          ? f.lotteryDrawNum
          : issueOptions[0]?.drawNum || '',
      }))
    } else {
      setPredForm((f) => ({ ...f, forecastPhase: '1', lotteryDrawNum: '' }))
      clampPlanNum(plans)
    }
  }

  // ── 编辑回填 ──
  function backToDetail() {
    const pages = Taro.getCurrentPages()
    if (pages.length > 1) {
      navigateBack()
    } else {
      goPostDetail({ partition: partitionSlug || 'all', type: publishType, id: editPostId })
    }
  }

  function buildPlanFromBackend(plan: any, lotteryCode: string): PredictionPlanState {
    const valueType = String(plan.valueType || '1')
    const inputMode: PredictionInputMode = valueType === '0' ? 'free' : 'standard'
    const backendCodeMode = String(plan.codeMode || '')
    const normalizedCode = normalizeCodeMode(backendCodeMode)

    let dimension: DimensionCode = '2'
    let killType: KillTypeValue = 'killTwo'
    if (normalizedCode.startsWith('杀')) {
      dimension = '-2'
      killType = String(plan.planMode || '') === '-1' ? 'killOne' : 'killTwo'
    } else {
      const letters = normalizedCode.replace(/X/g, '').split('').filter(Boolean)
      const dim = String(letters.length)
      dimension = (['2', '3', '4', '5'].includes(dim) ? dim : '2') as DimensionCode
    }

    const codeMode = matchFrontendCodeMode(backendCodeMode, lotteryCode, dimension)

    let scaleSize = '6*6'
    if (dimension !== '-2' && valueType === '1') {
      const precision = String(plan.precision || '').trim()
      if (/^\d+(?:\*\d+)+$/.test(precision)) {
        scaleSize = precision
      } else {
        const firstPos = lettersFromMode(codeMode)[0]
        const firstValue = firstPos ? String(plan[`${firstPos}Value`] || '') : ''
        const count = parseDigitString(firstValue).length
        const sizes = getPrecisionOptions(dimension)
        scaleSize = (count === 7 ? sizes[1] : sizes[0]) || '6*6'
      }
    }

    const partial: PredictionPlanState = {
      dimension,
      inputMode,
      codeMode,
      scaleSize,
      killType,
      predictionData: '',
      freeModeFocus: '',
      freeModeMain: '',
      freeModeRangeType: 'lower',
      rows: lettersFromMode(codeMode).map((pos) => ({
        position: pos,
        selectedNumbers: normalizeDigitList(parseDigitString(plan[`${pos}Value`])),
        lookGoodNumbers: normalizeDigitList(parseDigitString(plan[`${pos}LookGood`])),
        mainNumbers: normalizeDigitList(parseDigitString(plan[`${pos}Main`])),
        pointNumbers: normalizeDigitList(parseDigitString(plan[`${pos}Point`])),
      })),
      backendId: plan.id,
      backendInfoId: plan.infoId,
    }
    partial.rows = partial.rows.map((r) => pruneRow(r, partial))

    if (valueType === '0' && dimension !== '-2') {
      // 自由模式：有标记严格分栏；无标记旧帖回退 diffuseValue
      const sections = parseFreeModeSectionsForEdit(plan.summarize, plan.diffuseValue)
      partial.predictionData = sections.base
      partial.freeModeFocus = sections.focus
      partial.freeModeMain = sections.main
    }
    return partial
  }

  async function loadExchangeForEdit() {
    setLoadingEdit(true)
    try {
      const detail = await fetchForumDetail(editPostId)
      const currentUserId = Number(profile?.id || 0)
      const postUserId = Number(detail?.userId || 0)
      if (!currentUserId || currentUserId !== postUserId) {
        toast(publishLabels.noPermission)
        backToDetail()
        return
      }
      setExchangeTitle(String(detail.title || ''))
      // 轻量编辑器只保留纯文本（Web 富文本历史帖降级为去标签文本）
      setExchangeContent(String(detail.content || '').replace(/<[^>]+>/g, ''))
      setExchangeLotteryCode((detail.lotteryCode as LotteryCode) || partitionLotteryCode)
      setExchangePics(Array.isArray(detail.picsList) ? detail.picsList.map(String) : [])
      setEditingExchangeUserId(detail.userId)
      setFormReady(true)
    } catch (e: any) {
      toast(e?.message || publishLabels.loadFailed)
      goBack()
    } finally {
      setLoadingEdit(false)
    }
  }

  async function loadPredictionForEdit() {
    setLoadingEdit(true)
    try {
      const detail = await fetchPredictionDetail(editPostId)
      const currentUserId = Number(profile?.id || 0)
      const postUserId = Number(detail?.bizUserId || (detail as any)?.userId || 0)
      if (!currentUserId || currentUserId !== postUserId) {
        toast(publishLabels.noPermission)
        backToDetail()
        return
      }
      const planVOList = Array.isArray(detail?.planVOList) ? detail.planVOList : []
      if (!planVOList.length) throw new Error('未找到预测方案数据')

      const lotteryCode = String(detail.lotteryCode || partitionLotteryCode)
      const forecastPhase = String(detail.forecastPhase || '0') as '0' | '1'
      const title = String(detail.title || '')

      setPredForm({
        lotteryCode,
        forecastPhase,
        planNum: Number((detail as any).planNum || 3),
        lotteryDrawNum: String(detail.lotteryDrawNum || ''),
        title,
        summarize: '',
      })
      // 计划帖：从原标题解析起始期号，保持标题前缀稳定
      setEditPlanStartIssue(forecastPhase === '1' ? title.match(/(\d+)~(\d+)期计划/)?.[1] || '' : '')
      setEditingSourceType(String(detail.sourceType || 'F').trim() || 'F')
      setPlans(planVOList.map((plan: any) => buildPlanFromBackend(plan, lotteryCode)))
      setActivePlanIndex(0)
      // 标题后缀：前缀未知时用「期预测/期计划」标记截断兜底
      setTitleSuffix(parseTitleSuffix(title, ''))

      // 数据总结：取第一个方案 summarize 的【数据总结】段作为帖子级内容
      const firstPlan = planVOList[0]
      const rawSummarize = String(firstPlan?.summarize || '')
      const valueType = String(firstPlan?.valueType || '1')
      if (valueType === '0') {
        setPredForm((f) => ({
          ...f,
          summarize: rawSummarize.replace(/^【预测数据】[\s\S]*?【数据总结】\s*/, '').replace(/^【数据总结】\s*/, ''),
        }))
      } else {
        const notesMatch = rawSummarize.match(/【数据总结】\s*([\s\S]*)$/)
        setPredForm((f) => ({ ...f, summarize: notesMatch ? notesMatch[1].trim() : '' }))
      }

      // 加载期号；保留原单期期号，避免已开奖期号被当前期覆盖
      const originalDrawNum = String(detail.lotteryDrawNum || '')
      await loadPredictionMeta(lotteryCode)
      if (forecastPhase === '0' && originalDrawNum) {
        setIssueOptions((prev) => {
          if (prev.some((o) => o.drawNum === originalDrawNum)) return prev
          return [{ drawNum: originalDrawNum, label: `第${originalDrawNum}期` }, ...prev]
        })
        setPredForm((f) => ({ ...f, lotteryDrawNum: originalDrawNum }))
      }
      setTitleSuffix(parseTitleSuffix(title, ''))
      setFormReady(true)
    } catch (e: any) {
      toast(e?.message || publishLabels.loadFailed)
      goBack()
    } finally {
      setLoadingEdit(false)
    }
  }

  // ── 初始化：登录校验 → 编辑回填 / 草稿恢复 / 新建 ──
  useEffect(() => {
    if (!authState.initialized) return
    if (!isLoggedIn) {
      redirectToLogin(currentRoute())
      return
    }
    if (isEditMode) {
      Taro.setNavigationBarTitle({ title: publishLabels.pageTitleEdit })
      if (publishType === 'exchange') loadExchangeForEdit()
      else loadPredictionForEdit()
      return
    }
    void (async () => {
      const draft = await loadPublishDraft()
      if (draft) {
        setExchangeTitle(draft.exchange.title)
        setExchangeContent(draft.exchange.content)
        setExchangeLotteryCode((draft.exchange.lotteryCode as LotteryCode) || partitionLotteryCode)
        setPredForm({
          lotteryCode: draft.prediction.lotteryCode,
          forecastPhase: draft.prediction.forecastPhase === '1' ? '1' : '0',
          planNum: draft.prediction.planNum,
          lotteryDrawNum: draft.prediction.lotteryDrawNum,
          title: draft.prediction.title,
          summarize: draft.prediction.summarize,
        })
        setPlans(draft.plans)
        setActivePlanIndex(draft.activePlanIndex || 0)
        setTitleSuffix(parseTitleSuffix(draft.prediction.title, ''))
        setFormReady(true)
        loadPredictionMeta(draft.prediction.lotteryCode || partitionLotteryCode)
      } else {
        // 无草稿：初始化彩种 → 收敛方案维度/位置 → 拉期号（标题前缀由前缀 effect 自动重组）
        const lotteryCode = partitionLotteryCode
        setPredForm((f) => ({ ...f, lotteryCode }))
        setPlans((prev) => prev.map((p) => fixPlanForLottery(p, lotteryCode)))
        setFormReady(true)
        loadPredictionMeta(lotteryCode)
      }
    })()
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [authState.initialized, isLoggedIn])

  // ── 草稿自动保存（500ms 防抖；编辑模式不写草稿） ──
  const draftTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null)
  useEffect(() => {
    if (!formReady || isEditMode) return
    if (draftTimerRef.current) clearTimeout(draftTimerRef.current)
    draftTimerRef.current = setTimeout(() => {
      try {
        const draft: PublishDraft = {
          exchange: { title: exchangeTitle, content: exchangeContent, lotteryCode: exchangeLotteryCode },
          prediction: { ...predForm },
          plans: plans.map((p) => ({ ...p, backendId: undefined, backendInfoId: undefined })),
          activePlanIndex,
        }
        Taro.setStorage({ key: STORAGE_KEYS.publishDraft, data: JSON.stringify(draft) }).catch(() => {})
      } catch {
        // 存储失败：草稿非关键路径，忽略
      }
    }, 500)
    return () => {
      if (draftTimerRef.current) clearTimeout(draftTimerRef.current)
    }
  }, [formReady, isEditMode, exchangeTitle, exchangeContent, exchangeLotteryCode, predForm, plans, activePlanIndex])

  // ── 提交 ──
  function ensureLoggedIn(): boolean {
    if (isLoggedIn) return true
    redirectToLogin(currentRoute())
    return false
  }

  async function submitExchange() {
    if (!ensureLoggedIn()) return
    if (!exchangeTitle.trim()) {
      toast(publishLabels.titleRequired)
      return
    }
    const content = exchangeContent.trim()
    if (!content || content === '<p></p>') {
      toast(publishLabels.contentRequired)
      return
    }
    const lotteryCode = isAllPartition ? exchangeLotteryCode : partitionLotteryCode
    if (!lotteryCode) {
      toast(publishLabels.lotteryRequired)
      return
    }
    setPublishing(true)
    try {
      // MVP：项目暂无通用图片上传接口，本地图片仅占位预览；picList 只提交远端 URL（新建为空数组）。
      // 接入点：上传服务就绪后，在 chooseImage 成功回调里上传并替换为远端 URL 即可。
      const remotePics = exchangePics.filter((p) => /^https?:\/\//.test(p))
      if (isEditMode) {
        await editForumPost({
          id: editPostId,
          title: exchangeTitle,
          content,
          lotteryCode,
          picList: remotePics,
          userId: editingExchangeUserId,
        })
        toast(publishLabels.editSuccess)
      } else {
        await publishForumPost({ title: exchangeTitle, content, lotteryCode, picList: [] })
        toast(publishLabels.publishSuccess)
      }
      clearPublishDraft()
      goBack()
    } catch (e: any) {
      toast(e?.message || (isEditMode ? publishLabels.editFailed : publishLabels.publishFailed))
    } finally {
      setPublishing(false)
    }
  }

  function buildPlanPayload(plan: PredictionPlanState): Record<string, any> {
    const mm = resolveModeMapping(plan.codeMode, plan)
    const payload: Record<string, any> = { codeMode: mm.codeMode, planMode: mm.planMode }
    const notes = predForm.summarize.trim()

    if (plan.inputMode === 'free' && plan.dimension !== '-2') {
      const base = plan.predictionData.trim()
      const focus = plan.freeModeFocus.trim()
      const main = plan.freeModeMain.trim()
      payload.valueType = '0'
      payload.diffuseValue = combineNumberTokens(base, focus, main)
      payload.summarize = `【预测数据】\n${serializeFreeModeSections(base, focus, main)}`
      if (notes) payload.summarize = `${payload.summarize}\n【数据总结】\n${notes}`
      if (plan.backendId) payload.id = plan.backendId
      if (plan.backendInfoId) payload.infoId = plan.backendInfoId
      return payload
    }

    const asum = buildAutoPredictionSummary(plan).trim()
    payload.summarize = asum
    if (notes) payload.summarize = asum ? `${asum}\n【数据总结】\n${notes}` : `【数据总结】\n${notes}`

    plan.rows.forEach((row) => {
      const v = normalizeDigitList(row.selectedNumbers).join(' ')
      if (v) payload[`${row.position}Value`] = v
    })
    if (plan.dimension !== '-2' && plan.scaleSize) payload.precision = plan.scaleSize
    if (plan.backendId) payload.id = plan.backendId
    if (plan.backendInfoId) payload.infoId = plan.backendInfoId
    if (isKillCodeMode(plan.codeMode) || plan.dimension === '-2') return payload

    plan.rows.forEach((row) => {
      const lg = normalizeDigitList(row.lookGoodNumbers.filter((i) => row.selectedNumbers.includes(i))).join(' ')
      const ma = normalizeDigitList(row.mainNumbers.filter((i) => row.lookGoodNumbers.includes(i))).join(' ')
      const pt = normalizeDigitList(row.pointNumbers.filter((i) => row.mainNumbers.includes(i))).join(' ')
      if (lg) payload[`${row.position}LookGood`] = lg
      if (ma) payload[`${row.position}Main`] = ma
      if (pt) payload[`${row.position}Point`] = pt
    })
    return payload
  }

  function validatePredictionForm(): string {
    if (!predForm.title.trim()) return publishLabels.titleRequired
    if (predForm.forecastPhase === '0' && !predForm.lotteryDrawNum) return publishLabels.issueNotReady
    if (predForm.forecastPhase === '1') {
      const opts = effectivePlanNumOptions(plans)
      if (!opts.includes(Number(predForm.planNum))) return publishLabels.planNumInvalid(opts[opts.length - 1])
    }
    if (!plans.length) return publishLabels.needOnePlan

    for (let i = 0; i < plans.length; i++) {
      const plan = plans[i]
      const label = publishLabels.planLabel(i)
      if (!plan.codeMode) return `${label}：${publishLabels.needCodeMode}`

      if (plan.inputMode === 'free' && plan.dimension !== '-2') {
        // 计数口径：纯数字 token 且按文本去重；非数字内容直接拦截
        const baseInvalid = findNonNumericTokens(plan.predictionData)
        if (baseInvalid.length) return `${label}：${publishLabels.nonNumeric(publishLabels.freeBase, baseInvalid.join(' '))}`
        const focusInvalid = findNonNumericTokens(plan.freeModeFocus)
        if (focusInvalid.length) return `${label}：${publishLabels.nonNumeric(publishLabels.freeFocus, focusInvalid.join(' '))}`
        const mainInvalid = findNonNumericTokens(plan.freeModeMain)
        if (mainInvalid.length) return `${label}：${publishLabels.nonNumeric(publishLabels.freeMain, mainInvalid.join(' '))}`
        const baseCount = countNumberTokens(plan.predictionData)
        const focusCount = countNumberTokens(plan.freeModeFocus)
        const mainCount = countNumberTokens(plan.freeModeMain)
        if (!baseCount && !focusCount && !mainCount) return `${label}：${publishLabels.atLeastOneFreeSection}`
        if (!baseCount) return `${label}：${publishLabels.baseRequired}`
        if (baseCount < FREE_MODE_BASE_MIN) return `${label}：${publishLabels.baseMin(FREE_MODE_BASE_MIN, baseCount)}`
        const focusLimit = Math.floor(baseCount * FREE_MODE_FOCUS_RATIO)
        if (focusCount > focusLimit) return `${label}：${publishLabels.focusOverLimit(focusCount, focusLimit)}`
        const mainLimit = Math.floor(baseCount * FREE_MODE_MAIN_RATIO)
        if (mainCount > mainLimit) return `${label}：${publishLabels.mainOverLimit(mainCount, mainLimit)}`
        continue
      }

      if (!plan.rows.some((r) => r.selectedNumbers.length > 0)) return `${label}：${publishLabels.needAnyPosition}`
      if (plan.dimension === '-2') {
        const required = plan.killType === 'killOne' ? 1 : 2
        const msg = plan.killType === 'killOne' ? publishLabels.killOneNeed : publishLabels.killTwoNeed
        if (plan.rows.some((r) => r.selectedNumbers.length !== required)) return `${label}：${msg}`
      }
      if (plan.dimension !== '-2' && isKillCodeMode(plan.codeMode) && plan.rows.some((r) => r.selectedNumbers.length !== 2)) {
        return `${label}：${publishLabels.killTwoNeed}`
      }
    }
    return ''
  }

  async function submitPrediction() {
    if (!ensureLoggedIn()) return
    const err = validatePredictionForm()
    if (err) {
      toast(err)
      return
    }
    setPublishing(true)
    try {
      const planVOList = plans.map((plan) => buildPlanPayload(plan))
      const basePayload: ForecastPublishPayload = {
        title: predForm.title,
        lotteryCode: predForm.lotteryCode,
        forecastPhase: predForm.forecastPhase,
        sourceType: isEditMode ? (editingSourceType as 'F') : 'F',
        planVOList,
      }
      if (predForm.forecastPhase === '1') basePayload.planNum = Number(predForm.planNum)
      else basePayload.lotteryDrawNum = predForm.lotteryDrawNum
      if (isEditMode) {
        await editPrediction({ ...basePayload, id: editPostId })
        toast(publishLabels.editSuccess)
      } else {
        await publishPrediction(basePayload)
        toast(publishLabels.publishSuccess)
      }
      clearPublishDraft()
      goBack()
    } catch (e: any) {
      toast(e?.message || (isEditMode ? publishLabels.editFailed : publishLabels.publishFailed))
    } finally {
      setPublishing(false)
    }
  }

  // ── 图片插位（交流帖） ──
  const pickImages = async () => {
    const remain = FORUM_PIC_MAX - exchangePics.length
    if (remain <= 0) {
      toast(publishLabels.imageLimit(FORUM_PIC_MAX))
      return
    }
    try {
      const res = await Taro.chooseImage({ count: remain })
      const paths = res.tempFilePaths || []
      if (paths.length) {
        setExchangePics((prev) => [...prev, ...paths].slice(0, FORUM_PIC_MAX))
        // 图片上传服务未接入：本地路径仅占位展示
        toast(publishLabels.imageUploadPending)
      }
    } catch {
      // 用户取消选择
    }
  }

  // ── 渲染派生 ──
  const lotteryChipOptions = FORUM_PARTITIONS.map((p) => ({ label: p.label, value: p.lotteryCode as string }))
  const currentIssueLabel =
    issueOptions[0]?.label || (loadingTermMeta ? publishLabels.issueLoading : publishLabels.singlePhaseFallback)
  const isFreeMode = currentPlan.inputMode === 'free'
  const isKillDimension = currentPlan.dimension === '-2'
  const isKillMode = isKillCodeMode(currentPlan.codeMode)
  const dimensionOptions = getDimensionOptions(predLotteryCode || partitionLotteryCode, currentPlan.inputMode).map((d) => ({
    label: d.label,
    value: d.value as string,
  }))
  const codeModeOptions = getCodeModeOptions(predLotteryCode || partitionLotteryCode, currentPlan.dimension).map((mode) => ({
    label: isKillMode ? killPositionLabel(mode) : mode,
    value: mode,
  }))
  const scaleSizeOptions = getPrecisionOptions(currentPlan.dimension).map((s) => ({ label: s, value: s }))
  const planNumOptions = effectivePlanNumOptions(plans).map((n) => ({
    label: publishLabels.planNumOption(n),
    value: String(n),
  }))
  const standardSummary = useMemo(
    () => (isFreeMode && !isKillDimension ? '' : buildAutoPredictionSummary(currentPlan)),
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [currentPlan, isFreeMode, isKillDimension],
  )

  const busy = publishing || loadingEdit
  const submitLabel = busy ? publishLabels.submitting : isEditMode ? publishLabels.save : publishLabels.submit

  return (
    <View className='publish-page'>
      {publishType === 'exchange' ? (
        <>
          <View className='pub-card'>
            <View className='pub-field'>
              <Text className='pub-field__label'>{publishLabels.lotteryLabel}</Text>
              <ChipGroup
                options={lotteryChipOptions}
                value={isAllPartition ? exchangeLotteryCode : partitionLotteryCode}
                locked={!isAllPartition}
                onChange={(v) => setExchangeLotteryCode(v as LotteryCode)}
              />
            </View>
            <View className='pub-field'>
              <Input
                className='pub-input'
                value={exchangeTitle}
                placeholder={publishLabels.exchangeTitlePlaceholder}
                maxlength={POST_TITLE_MAX_LENGTH}
                onInput={(e) => setExchangeTitle(e.detail.value)}
              />
            </View>
            <View className='pub-field'>
              <Textarea
                className='pub-textarea'
                value={exchangeContent}
                placeholder={publishLabels.exchangeContentPlaceholder}
                maxlength={-1}
                onInput={(e) => setExchangeContent(e.detail.value)}
              />
            </View>
            <View className='pub-field'>
              <View className='pic-grid'>
                {exchangePics.map((pic, idx) => (
                  <View key={`${idx}-${pic}`} className='pic-grid__item'>
                    <Image className='pic-grid__image' src={pic} mode='aspectFill' />
                    <View
                      className='pic-grid__remove'
                      onClick={() => setExchangePics((prev) => prev.filter((_, i) => i !== idx))}
                    >
                      <Text className='pic-grid__remove-text'>×</Text>
                    </View>
                  </View>
                ))}
                {exchangePics.length < FORUM_PIC_MAX ? (
                  <View className='pic-grid__add' onClick={pickImages}>
                    <Text className='pic-grid__add-icon'>+</Text>
                    <Text className='pic-grid__add-text'>{publishLabels.addImage}</Text>
                  </View>
                ) : null}
              </View>
            </View>
          </View>
        </>
      ) : (
        <>
          {/* 发布配置（帖子级） */}
          <View className='pub-card'>
            <View className='pub-field'>
              <Text className='pub-field__label'>{publishLabels.lotteryLabel}</Text>
              <ChipGroup
                options={lotteryChipOptions}
                value={predForm.lotteryCode}
                locked={!isAllPartition}
                onChange={handleLotteryChange}
              />
            </View>
            <View className='pub-field'>
              <Text className='pub-field__label'>{publishLabels.forecastPhaseLabel}</Text>
              <ChipGroup
                options={[
                  { label: currentIssueLabel, value: '0' },
                  { label: publishLabels.planPhase, value: '1' },
                ]}
                value={predForm.forecastPhase}
                onChange={handlePhase}
              />
            </View>
            {predForm.forecastPhase === '1' ? (
              <View className='pub-field'>
                <Text className='pub-field__label'>{publishLabels.planNumLabel}</Text>
                <ChipGroup
                  options={planNumOptions}
                  value={String(predForm.planNum)}
                  onChange={(v) => setPredForm((f) => ({ ...f, planNum: Number(v) }))}
                />
              </View>
            ) : null}
          </View>

          {/* 标题：自动前缀 + 用户后缀 */}
          <View className='pub-card'>
            <View className='title-composer'>
              {predictionTitlePrefix ? (
                <Text className='title-composer__prefix'>{predictionTitlePrefix}</Text>
              ) : termMetaMissing ? (
                <Text className='title-composer__prefix title-composer__prefix--missing'>
                  {publishLabels.issueMissing}
                </Text>
              ) : null}
              <Input
                className='title-composer__suffix'
                value={titleSuffix}
                placeholder={publishLabels.titleSuffixPlaceholder}
                maxlength={suffixMaxLength}
                onInput={(e) => setTitleSuffix(e.detail.value)}
              />
            </View>
          </View>

          {/* 方案 Tab：横向滑动分段选择器，末尾「+」新增，长按删除 */}
          <View className='pub-card'>
            <PlanTabs
              count={plans.length}
              active={activePlanIndex}
              max={FORECAST_PLAN_MAX}
              labelOf={publishLabels.planLabel}
              addLabel={publishLabels.addPlan}
              onSwitch={setActivePlanIndex}
              onAdd={addPlan}
              onRemove={removePlan}
            />
          </View>

          {/* 方案明细（当前方案） */}
          <View className='pub-card'>
            <View className='plan-head'>
              <Text className='pub-card__title'>{publishLabels.planDetailTitle}</Text>
              <Text className='plan-head__hint'>
                {isKillMode && !isKillDimension
                  ? publishLabels.hintSelectPositionFirst
                  : isKillDimension
                    ? currentPlan.killType === 'killOne'
                      ? publishLabels.hintKillOne
                      : publishLabels.hintKillTwo
                    : !isFreeMode
                      ? publishLabels.hintSelectCount(String(selectionLimitForMode(currentPlan)))
                      : publishLabels.hintFreeMode}
              </Text>
            </View>
            <View className='pub-field'>
              <Text className='pub-field__label'>{publishLabels.dimensionLabel}</Text>
              <ChipGroup options={dimensionOptions} value={currentPlan.dimension} onChange={(v) => handleDimension(activePlanIndex, v)} />
            </View>
            <View className='pub-field'>
              <Text className='pub-field__label'>{publishLabels.inputModeLabel}</Text>
              <ChipGroup
                options={[
                  { label: publishLabels.inputModeStandard, value: 'standard' },
                  { label: publishLabels.inputModeFree, value: 'free' },
                ]}
                value={currentPlan.inputMode}
                onChange={(v) => handleInputMode(activePlanIndex, v)}
              />
            </View>
            <View className='pub-field'>
              <Text className='pub-field__label'>{publishLabels.positionLabel}</Text>
              <ChipGroup options={codeModeOptions} value={currentPlan.codeMode} onChange={(v) => handleCodeMode(activePlanIndex, v)} />
            </View>
            {!isFreeMode && isKillDimension ? (
              <View className='pub-field'>
                <Text className='pub-field__label'>{publishLabels.killTypeLabel}</Text>
                <ChipGroup
                  options={[{ label: publishLabels.killTwo, value: 'killTwo' }]}
                  value={currentPlan.killType}
                  onChange={(v) => handleKillType(activePlanIndex, v)}
                />
              </View>
            ) : null}
            {!isFreeMode && !isKillMode && !isKillDimension ? (
              <View className='pub-field'>
                <Text className='pub-field__label'>{publishLabels.scaleSizeLabel}</Text>
                <ChipGroup options={scaleSizeOptions} value={currentPlan.scaleSize} onChange={(v) => handleScaleSize(activePlanIndex, v)} />
              </View>
            ) : null}

            {/* 选号模式 / 自由模式号码录入 */}
            {!isFreeMode || isKillDimension ? (
              <PositionSelector
                rows={currentPlan.rows}
                isKill={isKillMode || isKillDimension}
                limit={selectionLimitForMode(currentPlan)}
                onToggleDigit={(pos, digit) => handleToggleDigit(activePlanIndex, pos, digit)}
                onToggleMark={(pos, digit, level) => handleToggleMark(activePlanIndex, pos, digit, level)}
              />
            ) : null}
          </View>

          {/* 预测数据 */}
          <View className='pub-card'>
            <Text className='pub-card__title'>
              {publishLabels.predictionDataTitle}
              <Text className='pub-card__subtitle'>{publishLabels.predictionDataSubtitle}</Text>
            </Text>
            {isFreeMode && !isKillDimension ? (
              <FreeModePanels
                dimension={currentPlan.dimension}
                rangeType={currentPlan.freeModeRangeType}
                base={currentPlan.predictionData}
                focus={currentPlan.freeModeFocus}
                main={currentPlan.freeModeMain}
                onRangeChange={(v) => handleRangeType(activePlanIndex, v)}
                onBaseChange={(v) => updatePlanAt(activePlanIndex, (p) => ({ ...p, predictionData: v }))}
                onFocusChange={(v) => updatePlanAt(activePlanIndex, (p) => ({ ...p, freeModeFocus: v }))}
                onMainChange={(v) => updatePlanAt(activePlanIndex, (p) => ({ ...p, freeModeMain: v }))}
              />
            ) : (
              <View className={`prediction-data${standardSummary ? '' : ' prediction-data--empty'}`}>
                <Text>{standardSummary || publishLabels.predictionDataPlaceholder}</Text>
              </View>
            )}
          </View>

          {/* 数据总结（可选，提交时拼到【数据总结】段） */}
          <View className='pub-card'>
            <Text className='pub-card__title'>
              {publishLabels.summaryTitle}
              <Text className='pub-card__subtitle'>{publishLabels.summarySubtitle}</Text>
            </Text>
            <Textarea
              className='pub-textarea pub-textarea--summary'
              value={predForm.summarize}
              placeholder={publishLabels.summaryPlaceholder}
              maxlength={-1}
              onInput={(e) => setPredForm((f) => ({ ...f, summarize: e.detail.value }))}
            />
          </View>
        </>
      )}

      {/* 底部固定操作栏 */}
      <View className='publish-actions'>
        <View className='publish-actions__btn' onClick={() => goBack()}>
          <Text className='publish-actions__btn-text'>{publishLabels.cancel}</Text>
        </View>
        <View
          className={`publish-actions__btn publish-actions__btn--primary${busy ? ' publish-actions__btn--disabled' : ''}`}
          onClick={() => {
            if (busy) return
            if (publishType === 'exchange') submitExchange()
            else submitPrediction()
          }}
        >
          <Text className='publish-actions__btn-text publish-actions__btn-text--primary'>{submitLabel}</Text>
        </View>
      </View>
    </View>
  )
}
