import { useEffect, useState } from 'react'
import { Text, Video, View, WebView } from '@tarojs/components'
import Taro from '@tarojs/taro'
import { LOTTERY_LIST, getLotteryMeta, normalizeLotteryCode, type LotteryCode } from '@/constants/lottery'
import { fetchDrawDailyDetail } from '@/services/api'
import { getLiveWindowState, isDirectVideoSource } from '@/utils/live'
import { liveLabels } from '@/labels/live'
import type { DrawDailyDetail } from '@/types'
import './index.css'

/** 开奖直播（二级页）：播放器三级降级 + 其他直播源 + 频道切换（产品方案 §6.2、Web PRD §6.3） */
export default function LivePage() {
  const [code, setCode] = useState<LotteryCode>(() =>
    normalizeLotteryCode(Taro.getCurrentInstance().router?.params?.code),
  )
  const [detail, setDetail] = useState<DrawDailyDetail | null>(null)
  const [now, setNow] = useState(() => Date.now())

  // 直播状态徽标 / 倒计时每秒刷新，卸载清理定时器
  useEffect(() => {
    const timer = setInterval(() => setNow(Date.now()), 1000)
    return () => clearInterval(timer)
  }, [])

  useEffect(() => {
    let cancelled = false
    fetchDrawDailyDetail(code)
      .then((res) => {
        if (!cancelled) setDetail(res || null)
      })
      .catch(() => {
        if (!cancelled) setDetail(null) // 开奖接口异常显示空态不崩溃（Web PRD §10.3）
      })
    return () => {
      cancelled = true
    }
  }, [code])

  const meta = getLotteryMeta(code)
  const live = getLiveWindowState(new Date(now))

  // 播放区三级降级：直连视频 → H5 WebView → 占位 + 外链
  const rawSource = typeof detail?.liveSource === 'string' ? detail.liveSource.trim() : ''
  const directVideoSource = rawSource && isDirectVideoSource(rawSource) ? rawSource : ''
  const webSource = !directVideoSource && /^https?:\/\//i.test(rawSource) ? rawSource : ''
  const sourceLinks = code === '3d' ? liveLabels.sourceLinks.welfare : liveLabels.sourceLinks.physical

  const openExternal = (url: string) => {
    if (process.env.TARO_ENV === 'h5') {
      window.open(url, '_blank', 'noopener,noreferrer')
      return
    }
    // 其他端无法内嵌外链：复制链接并提示
    Taro.setClipboardData({ data: url }).then(() => {
      Taro.showToast({ title: liveLabels.player.linkCopied, icon: 'none' })
    })
  }

  return (
    <View className='live-page'>
      {/* 品牌条 */}
      <View className='brand-strip'>
        <Text className='brand-strip__title'>{liveLabels.brand.title}</Text>
        <Text className='brand-strip__schedule'>{liveLabels.brand.schedule}</Text>
      </View>

      {/* 播放器卡 */}
      <View className='player'>
        <View className='player__head'>
          <View className='player__head-main'>
            <Text className='player__title'>{liveLabels.room.title(meta.label)}</Text>
            <Text className='player__desc'>{liveLabels.room.description[code]}</Text>
          </View>
          <View className={`player__status${live.isLive ? ' player__status--live' : ''}`}>
            <View className='player__status-dot' />
            <Text className='player__status-text'>
              {live.isLive ? liveLabels.player.liveOn : liveLabels.player.liveOff}
            </Text>
          </View>
        </View>

        <View className='player__meta'>
          <Text className='player__meta-item'>{detail?.lotteryType || meta.label}</Text>
          <Text className='player__meta-item'>
            {detail?.drawNum ? liveLabels.player.issue(detail.drawNum) : liveLabels.player.issuePlaceholder}
          </Text>
        </View>

        <View className='player__frame'>
          {directVideoSource ? (
            <Video className='player__media' src={directVideoSource} controls />
          ) : webSource && process.env.TARO_ENV === 'h5' ? (
            <WebView className='player__media' src={webSource} />
          ) : (
            <View className='player__placeholder'>
              <Text className='player__placeholder-name'>{meta.label}</Text>
              <Text className='player__placeholder-hint'>
                {live.isLive ? liveLabels.player.liveWindowHint : live.statusText}
              </Text>
              <Text className='player__placeholder-countdown'>
                {live.isLive ? liveLabels.player.watchLive : live.buttonText}
              </Text>
              <View className='player__placeholder-btn' onClick={() => openExternal(meta.liveSourceUrl)}>
                <Text className='player__placeholder-btn-text'>
                  {liveLabels.player.openPrimarySource(meta.liveSourceLabel)}
                </Text>
              </View>
            </View>
          )}
        </View>

        {/* 其他直播源 */}
        <View className='source-row'>
          <Text className='source-row__label'>{liveLabels.player.otherSources}</Text>
          {sourceLinks.map((source) => (
            <Text key={source.href} className='source-row__link' onClick={() => openExternal(source.href)}>
              {source.label}
            </Text>
          ))}
        </View>
      </View>

      {/* 频道列表（点击切换本页彩种，不改 URL） */}
      <View className='channel-card'>
        <Text className='channel-card__title'>{liveLabels.channel.title}</Text>
        {LOTTERY_LIST.map((item) => (
          <View
            key={item.code}
            className={`channel-item${item.code === code ? ' channel-item--active' : ''}`}
            onClick={() => setCode(item.code)}
          >
            <View className='channel-item__icon'>
              <Text className='channel-item__icon-text'>{liveLabels.channelShort[item.code]}</Text>
            </View>
            <View className='channel-item__copy'>
              <Text className='channel-item__name'>{item.label}</Text>
              <Text className='channel-item__schedule'>
                {liveLabels.channel.schedulePrefix}
                {liveLabels.brand.schedule}
              </Text>
            </View>
          </View>
        ))}
      </View>
    </View>
  )
}
