.rank-page {
  min-height: 100vh;
  padding-bottom: var(--sa-24, calc(24px + env(safe-area-inset-bottom)));
}

/* 顶部两行横滑筛选条 */
.filter-bars {
  background: var(--color-bg-card);
  padding: 8px 0;
}

.filter-bar {
  white-space: nowrap;
}

.filter-bar__inner {
  display: flex;
  flex-direction: row;
  align-items: center;
  padding: 4px 16px;
  gap: 8px;
}

.filter-bar__label {
  flex-shrink: 0;
  font-size: 13px;
  color: var(--color-text-secondary);
  margin-right: 2px;
}

.chip {
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 44px;
  padding: 0 16px;
  border-radius: 999px;
  background: var(--color-bg);
}

.chip--active {
  background: var(--color-primary-light);
}

.chip__text {
  font-size: 13px;
  color: var(--color-text-secondary);
}

.chip__text--active {
  color: var(--color-primary);
  font-weight: 600;
}

.filter-trigger {
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 44px;
  padding: 0 16px;
  border-radius: 999px;
  border: 1px solid var(--color-primary);
}

.filter-trigger__text {
  font-size: 13px;
  color: var(--color-primary);
  font-weight: 600;
}

/* 榜单卡片 */
.expert-card {
  margin: 12px 16px 0;
  padding: 20px;
  background: var(--color-bg-card);
  border-radius: var(--radius-md);
}

.expert-card__head {
  display: flex;
  flex-direction: row;
  align-items: center;
}

.expert-card__badge {
  flex-shrink: 0;
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: var(--color-bg);
  color: var(--color-text-secondary);
  font-size: 14px;
  font-weight: 700;
  text-align: center;
  line-height: 32px;
  margin-right: 12px;
}

.expert-card__badge--1 {
  background: #f6c844;
  color: #6c4f00;
}

.expert-card__badge--2 {
  background: #d7dce5;
  color: #4b5563;
}

.expert-card__badge--3 {
  background: #e8b08a;
  color: #7c3f12;
}

.expert-card__info {
  flex: 1;
  min-width: 0;
  margin-left: 12px;
}

.expert-card__name-row {
  display: flex;
  flex-direction: row;
  align-items: center;
}

.expert-card__name {
  font-size: 16px;
  font-weight: 600;
  margin-right: 8px;
}

.expert-card__verified {
  font-size: 11px;
  color: var(--color-warning);
  border: 1px solid var(--color-warning);
  border-radius: 999px;
  padding: 1px 8px;
}

.expert-card__meta {
  display: flex;
  flex-direction: row;
  align-items: center;
  flex-wrap: wrap;
  margin-top: 6px;
}

.expert-card__rate {
  font-size: 16px;
  font-weight: 700;
  color: var(--color-primary);
  margin-right: 12px;
}

.expert-card__meta-item {
  font-size: 12px;
  color: var(--color-text-secondary);
  margin-right: 12px;
}

.expert-card__follow {
  flex-shrink: 0;
  display: flex;
  align-items: center;
  min-height: 44px;
}

.expert-card__record {
  display: flex;
  flex-direction: row;
  align-items: center;
  justify-content: space-between;
  margin-top: 14px;
  padding-top: 12px;
  border-top: 1px solid var(--color-border);
}

.expert-card__record-text {
  font-size: 13px;
  color: var(--color-text);
  font-weight: 600;
}

.expert-card__trend {
  font-size: 12px;
  color: var(--color-text-secondary);
}

.expert-card__trend--up {
  color: var(--color-success);
}

.expert-card__trend--down {
  color: var(--color-danger);
}

/* 底部宣传 banner */
.banner {
  margin: 16px 16px 0;
  padding: 24px;
  background: var(--color-bg-card);
  border-radius: var(--radius-md);
}

.banner--primary {
  background-color: #1a1a6e; /* RN 端不支持渐变，降级为纯色 */
  background-image: linear-gradient(135deg, #1a1a6e 0%, #16213e 100%);
}

.banner__title {
  display: block;
  font-size: 16px;
  font-weight: 700;
  margin-bottom: 8px;
}

.banner__title--light {
  color: #fff;
}

.banner__desc {
  display: block;
  font-size: 13px;
  color: var(--color-text-secondary);
  line-height: 1.6;
}

.banner__desc--light {
  color: rgba(255, 255, 255, 0.8);
}

/* 筛选面板 */
.panel {
  padding: 24px 20px var(--sa-20, calc(20px + env(safe-area-inset-bottom)));
}

.panel__title {
  display: block;
  font-size: 17px;
  font-weight: 700;
  margin-bottom: 16px;
}

.panel__group {
  margin-bottom: 16px;
}

.panel__label {
  display: block;
  font-size: 13px;
  color: var(--color-text-secondary);
  margin-bottom: 8px;
}

.panel__chips {
  display: flex;
  flex-direction: row;
  flex-wrap: wrap;
  gap: 8px;
}

.panel__footer {
  display: flex;
  flex-direction: row;
  gap: 12px;
  margin-top: 8px;
}

.panel__btn {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 48px;
  border-radius: var(--radius-sm);
  background: var(--color-bg);
}

.panel__btn--primary {
  background: var(--color-primary);
}

.panel__btn-text {
  font-size: 15px;
  color: var(--color-text);
}

.panel__btn-text--primary {
  color: #fff;
  font-weight: 600;
}
