import { Text } from '@tarojs/components'
import { getLotteryMeta } from '@/constants/lottery'
import './index.css'

interface LotteryTagProps {
  code?: string | null
}

/** 彩种灰标签 */
export default function LotteryTag({ code }: LotteryTagProps) {
  if (!code) return null
  return <Text className='lottery-tag'>{getLotteryMeta(code).forumLabel}</Text>
}
