import { View, Text, Image } from '@tarojs/components'
import { avatarBg, avatarText } from '@/utils/avatar'
import './index.css'

interface AvatarProps {
  src?: string
  name?: string
  size?: number
}

/** 头像：无图时用昵称末两位 + 稳定兜底色块 */
export default function Avatar({ src, name, size = 40 }: AvatarProps) {
  const style = { width: `${size}px`, height: `${size}px` }
  if (src) {
    return <Image className='avatar' style={style} src={src} mode='aspectFill' />
  }
  return (
    <View className='avatar avatar--fallback' style={{ ...style, background: avatarBg(name) }}>
      <Text className='avatar__text' style={{ fontSize: Math.max(12, size / 3) }}>
        {avatarText(name)}
      </Text>
    </View>
  )
}
