import { View, Text } from '@tarojs/components'
import type { FeedItem } from '@/types'
import Avatar from '@/components/Avatar'
import LotteryTag from '@/components/LotteryTag'
import { forumDetailLabels } from '@/labels/forumDetail'
import { formatTime } from '@/utils/formatTime'
import './index.css'

interface FeedExchangeRowProps {
  item: FeedItem
}

/** 信息流交流帖行：彩种标签 + 标题（单行省略）+ 作者/时间/评论/点赞（产品方案 §6.5） */
export default function FeedExchangeRow({ item }: FeedExchangeRowProps) {
  const author = item.nickName || forumDetailLabels.anonymous
  // 空标题回退正文去标签截 50 字
  const title =
    item.title?.trim() ||
    (item.content || '').replace(/<[^>]+>/g, '').trim().slice(0, 50) ||
    forumDetailLabels.noTitle

  return (
    <View className='feed-exchange'>
      <View className='feed-exchange__main'>
        <LotteryTag code={item.lotteryCode} />
        <Text className='feed-exchange__title'>{title}</Text>
      </View>
      <View className='feed-exchange__meta'>
        <Avatar src={item.avatar} name={author} size={24} />
        <Text className='feed-exchange__author'>{author}</Text>
        <Text className='feed-exchange__time'>{formatTime(item.createTime)}</Text>
        <Text className='feed-exchange__stat'>评论 {item.commentNum || 0}</Text>
        <Text className='feed-exchange__stat'>点赞 {item.likeNum || 0}</Text>
      </View>
    </View>
  )
}
