import { useState } from 'react'
import { Text } from '@tarojs/components'
import Taro from '@tarojs/taro'
import { useAuth, redirectToLogin } from '@/store/auth'
import { followUser } from '@/services/api'
import { commonLabels } from '@/labels'
import './index.css'

interface FollowButtonProps {
  userId: number | string
  isFollowed: boolean
  onChange?: (followed: boolean) => void
}

/** 关注按钮：未登录跳登录；乐观更新 + 失败回滚（Web PRD §10.4） */
export default function FollowButton({ userId, isFollowed, onChange }: FollowButtonProps) {
  const { isLoggedIn } = useAuth()
  const [followed, setFollowed] = useState(isFollowed)
  const [pending, setPending] = useState(false)

  const toggle = async () => {
    if (pending) return
    if (!isLoggedIn) {
      redirectToLogin()
      return
    }
    const next = !followed
    setFollowed(next) // 乐观更新
    setPending(true)
    try {
      // 语义：followed=true 表示当前已关注 → 执行取关（Web PRD §7.9）
      const res = await followUser(userId, followed)
      const finalState = typeof res?.followed === 'boolean' ? res.followed : next
      setFollowed(finalState)
      onChange?.(finalState)
    } catch (err: any) {
      setFollowed(!next) // 失败回滚
      Taro.showToast({ title: err?.message || '操作失败', icon: 'none' })
    } finally {
      setPending(false)
    }
  }

  return (
    <Text className={`follow-btn${followed ? ' follow-btn--active' : ''}`} onClick={toggle}>
      {followed ? commonLabels.followed : `+ ${commonLabels.follow}`}
    </Text>
  )
}
