import { useEffect, useRef, useState } from 'react'
import { View, Text, Input } from '@tarojs/components'
import Taro from '@tarojs/taro'
import { sendForgotPasswordCodeApi, resetPasswordApi } from '@/services/api'
import { authLabels } from '@/labels/auth'
import { goBack } from '@/utils/nav'
import { useCodeSender } from '@/hooks/useCodeSender'
import '@/styles/auth-shared.css'
import './index.css'

/** 邮箱基础格式校验 */
function isValidEmail(value: string) {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value)
}

/** 重置成功提示的停留时长（toast 展示完再返回登录页） */
const RESET_SUCCESS_DELAY_MS = 1200

/** 忘记密码页：账号 + 绑定邮箱 + 邮箱验证码 + 新密码，重置成功后返回登录页 */
export default function ForgotPasswordPage() {
  const [account, setAccount] = useState('')
  const [email, setEmail] = useState('')
  const [code, setCode] = useState('')
  const [newPassword, setNewPassword] = useState('')
  const [confirmPassword, setConfirmPassword] = useState('')
  const [showPassword, setShowPassword] = useState(false)
  const [submitting, setSubmitting] = useState(false)
  const { countdown, disabled: sendDisabled, sendCode } = useCodeSender(
    () => sendForgotPasswordCodeApi({ account: account.trim(), email: email.trim() }),
    { sentTitle: authLabels.forgotPassword.codeSent, failTitle: authLabels.errors.resetFailed },
  )
  /** 重置成功后的延时返回定时器：卸载前用户手动离开时需清理，避免重复出栈 */
  const redirectTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null)

  useEffect(
    () => () => {
      if (redirectTimerRef.current) clearTimeout(redirectTimerRef.current)
    },
    [],
  )

  /** 从公开页唤起时用户可放弃：优先返回上一页，栈空（直达/刷新）回首页 */
  const closeModal = () => goBack('/pages/home/index')

  const clickSendCode = () => {
    const trimmedAccount = account.trim()
    const trimmedEmail = email.trim()
    if (!trimmedAccount) {
      Taro.showToast({ title: authLabels.errors.accountRequired, icon: 'none' })
      return
    }
    if (!trimmedEmail) {
      Taro.showToast({ title: authLabels.errors.emailRequired, icon: 'none' })
      return
    }
    if (!isValidEmail(trimmedEmail)) {
      Taro.showToast({ title: authLabels.errors.emailInvalid, icon: 'none' })
      return
    }
    sendCode()
  }

  const submit = async () => {
    if (submitting) return
    if (!account.trim()) {
      Taro.showToast({ title: authLabels.errors.accountRequired, icon: 'none' })
      return
    }
    if (!email.trim()) {
      Taro.showToast({ title: authLabels.errors.emailRequired, icon: 'none' })
      return
    }
    if (!isValidEmail(email.trim())) {
      Taro.showToast({ title: authLabels.errors.emailInvalid, icon: 'none' })
      return
    }
    if (!code.trim()) {
      Taro.showToast({ title: authLabels.errors.smsCodeRequired, icon: 'none' })
      return
    }
    if (!newPassword) {
      Taro.showToast({ title: authLabels.errors.passwordRequired, icon: 'none' })
      return
    }
    if (newPassword !== confirmPassword) {
      Taro.showToast({ title: authLabels.errors.passwordMismatch, icon: 'none' })
      return
    }
    setSubmitting(true)
    try {
      await resetPasswordApi({
        account: account.trim(),
        email: email.trim(),
        code: code.trim(),
        newPassword,
        confirmNewPassword: confirmPassword,
      })
      Taro.showToast({ title: authLabels.forgotPassword.success, icon: 'none' })
      // 与 closeModal 同款回退（含栈空兜底）；定时器存 ref，提前离开页面时清理避免二次出栈
      redirectTimerRef.current = setTimeout(closeModal, RESET_SUCCESS_DELAY_MS)
    } catch (err: any) {
      Taro.showToast({ title: err?.message || authLabels.errors.resetFailed, icon: 'none' })
    } finally {
      setSubmitting(false)
    }
  }

  return (
    <View className='auth-page'>
      {/* 关闭入口仅 H5 渲染：RN 端默认导航栏自带返回键（栈空兜底场景仅存在于 H5 直达/刷新） */}
      {process.env.TARO_ENV === 'h5' && (
        <View className='auth-page__close' onClick={closeModal}>
          <Text className='auth-page__close-icon'>✕</Text>
        </View>
      )}

      <Text className='auth-page__title'>{authLabels.forgotPassword.title}</Text>

      <View className='auth-field'>
        <Input
          className='auth-field__input'
          value={account}
          placeholder={authLabels.forgotPassword.accountPlaceholder}
          onInput={(e) => setAccount(e.detail.value)}
        />
      </View>

      <View className='auth-field'>
        <Input
          className='auth-field__input'
          value={email}
          placeholder={authLabels.forgotPassword.emailPlaceholder}
          onInput={(e) => setEmail(e.detail.value)}
        />
      </View>

      <View className='auth-field'>
        <Input
          className='auth-field__input'
          type='number'
          maxlength={6}
          value={code}
          placeholder={authLabels.forgotPassword.codePlaceholder}
          onInput={(e) => setCode(e.detail.value)}
        />
        <Text
          className={`auth-field__toggle${sendDisabled ? ' auth-field__toggle--disabled' : ''}`}
          onClick={clickSendCode}
        >
          {countdown > 0 ? authLabels.forgotPassword.resendAfter(countdown) : authLabels.forgotPassword.sendCode}
        </Text>
      </View>

      <View className='auth-field'>
        <Input
          className='auth-field__input'
          value={newPassword}
          password={!showPassword}
          placeholder={authLabels.forgotPassword.newPasswordPlaceholder}
          onInput={(e) => setNewPassword(e.detail.value)}
        />
        <Text className='auth-field__toggle' onClick={() => setShowPassword(!showPassword)}>
          {showPassword ? authLabels.hidePassword : authLabels.showPassword}
        </Text>
      </View>

      <View className='auth-field'>
        <Input
          className='auth-field__input'
          value={confirmPassword}
          password={!showPassword}
          placeholder={authLabels.forgotPassword.confirmPlaceholder}
          onInput={(e) => setConfirmPassword(e.detail.value)}
        />
      </View>

      <View className={`auth-submit${submitting ? ' auth-submit--disabled' : ''}`} onClick={submit}>
        <Text className='auth-submit__text'>
          {submitting ? authLabels.forgotPassword.submitting : authLabels.forgotPassword.submit}
        </Text>
      </View>
    </View>
  )
}
