import { useState } from 'react'
import { View, Text } from '@tarojs/components'
import { useDidShow } from '@tarojs/taro'
import { fetchToolList } from '@/services/api'
import type { ToolItem } from '@/types'
import { TOOL_ID, type ToolId } from '@/constants/tools'
import { toolsLabels } from '@/labels/tools'
import { navigateTo } from '@/utils/nav'
import { guardToolAccess, toToolAccessMap } from '@/utils/toolAccess'
import './index.css'

/** 本地工具注册表（Web PRD §6.8；深度遗漏已下线不展示）。
    id 为后端权限配置契约（见 @/constants/tools）；名称/描述/跳转路径以本地为准，
    接口 /tool/list 只驱动排序、权益角标与锁定状态；
    fallbackLevel 为接口不可用时的兜底权益（对齐原静态 subscription 标记） */
const TOOL_REGISTRY: { id: ToolId; path: string; fallbackLevel: 'FREE' | 'TIER_1' }[] = [
  { id: TOOL_ID.FILTER, path: '/pages/tools/filter/index', fallbackLevel: 'TIER_1' },
  { id: TOOL_ID.CODE_GROUP_EXTENSION, path: '/pages/tools/code-group-extension/index', fallbackLevel: 'TIER_1' },
  { id: TOOL_ID.HISTORY_REVIEW, path: '/pages/tools/history-review/index', fallbackLevel: 'FREE' },
  { id: TOOL_ID.SET_PROCESSING, path: '/pages/tools/set-processing/index', fallbackLevel: 'TIER_1' },
  { id: TOOL_ID.DRAW_RULE, path: '/pages/tools/draw-rule/index', fallbackLevel: 'TIER_1' },
]

interface MergedTool {
  id: ToolId
  path: string
  index: number
  requiredLevel: string
  locked: boolean
  lockReason: ToolItem['lockReason']
  remoteSort: number | null
}

/** 实用工具列表：卡片网格 2 列（产品方案 §6.8），锁定状态由 GET /tool/list 驱动 */
export default function ToolsPage() {
  // 每次进页刷新（登录/开通会员后返回即更新锁定状态）；失败保持注册表兜底（全部解锁）
  const [remoteTools, setRemoteTools] = useState<Record<string, ToolItem>>({})

  useDidShow(() => {
    fetchToolList()
      .then((list) => setRemoteTools(toToolAccessMap(list)))
      .catch(() => {})
  })

  const tools: MergedTool[] = TOOL_REGISTRY.map((meta, index) => {
    const remote = remoteTools[meta.id]
    return {
      id: meta.id,
      path: meta.path,
      index,
      requiredLevel: remote?.requiredLevel || meta.fallbackLevel,
      locked: remote?.locked ?? false,
      lockReason: remote?.lockReason ?? null,
      remoteSort: remote ? remote.sort : null,
    }
  }).sort((a, b) => {
    if (a.remoteSort !== null && b.remoteSort !== null) return a.remoteSort - b.remoteSort
    return a.index - b.index
  })

  const open = (tool: MergedTool) => {
    if (!guardToolAccess(tool)) return
    navigateTo({ url: tool.path })
  }

  return (
    <View className='tools-page'>
      <View className='tools-grid'>
        {tools.map((tool) => {
          const meta = toolsLabels.items[tool.id]
          const isFree = tool.requiredLevel === 'FREE'
          const badgeText = tool.locked
            ? toolsLabels.lockedBadge
            : isFree
              ? toolsLabels.freeBadge
              : toolsLabels.subscriptionBadge
          const badgeClass = `tool-card__badge${isFree ? ' tool-card__badge--free' : ''}${tool.locked ? ' tool-card__badge--locked' : ''}`
          return (
            <View
              key={tool.id}
              className={`tool-card${tool.locked ? ' tool-card--locked' : ''}`}
              onClick={() => open(tool)}
            >
              <Text className={badgeClass}>{badgeText}</Text>
              <Text className='tool-card__name'>{meta.name}</Text>
              <Text className='tool-card__desc'>{meta.desc}</Text>
            </View>
          )
        })}
      </View>
    </View>
  )
}
