import { Input, ScrollView, Text, View } from '@tarojs/components'
import Taro from '@tarojs/taro'
import { fetchDrawDailyDetail } from '@/services/api'
import { getLotteryLabel, LOTTERY_OPTIONS } from '@/constants/lottery'
import { drawRuleLabels as labels } from '@/labels/tools'
import DrawBoard from './board'
import DrawEngine from './engine'
import { savePngToDevice } from './saveImage'
import {
  BasicSettingSheet,
  ColorSheet,
  PredictionSheet,
  SmartSettingSheet,
  ToolSheet,
  TOOL_ICON_TEXT,
  type PredictionConfirmPayload,
  type SmartSetting,
} from './panels'
import {
  PERIOD_MAX,
  PERIOD_MIN,
  PERIOD_STEP,
  SMART_LINE_HOLD_DELAY,
  STAGE_CLICK_DEDUPE_DELAY,
  STAGE_CLICK_DEDUPE_DISTANCE,
  STROKE_OPTIONS,
  TEXT_DEFAULT_HEIGHT,
  buildBoardRows,
  buildSmartLineDraftSegments,
  buildSmartLineSegments,
  computeBoardGeometry,
  computeMarkedDigitCells,
  computePredictionRenderMarks,
  computeSimplePredictionCells,
  createDrawId,
  digitCellAnchor,
  digitCellKey,
  drawCountOf,
  isShapeTool,
  measureTextWidth,
  normalizeEllipse,
  normalizeRect,
  pointDistance,
  predictionColumnsForActiveCondition,
  predictionColumnsForMark,
  predictionMarkColumnsForCommit,
  resolveDigitCell,
  shapeFillColor,
  smartLineControlPatch,
  sumDigitCountOf,
  type BoardRow,
  type DigitCellTarget,
  type DraftState,
  type DrawEngineHit,
  type DrawEngineRef,
  type DrawHistoryInput,
  type DrawItem,
  type DrawPoint,
  type DrawTool,
  type PredictionMark,
  type SimplePredictionMark,
} from './model'
import './index.css'

function toast(title: string) {
  Taro.showToast({ title, icon: 'none' })
}

/** 彩种默认 04（七星彩）；路由 ?code= 合法时优先（goDrawRule 传入） */
function initialLotteryCode() {
  const raw = Taro.getCurrentInstance().router?.params?.code
  const code = String(raw || '').trim()
  return LOTTERY_OPTIONS.some((item) => item.value === code) ? code : '04'
}

function normalizePeriodCount(count: number) {
  const stepped = Math.round(count / PERIOD_STEP) * PERIOD_STEP
  return Math.min(PERIOD_MAX, Math.max(PERIOD_MIN, stepped))
}

function formatExportTimestamp(date: Date) {
  const pad = (value: number) => String(value).padStart(2, '0')
  return [
    date.getFullYear(),
    pad(date.getMonth() + 1),
    pad(date.getDate()),
    pad(date.getHours()),
    pad(date.getMinutes()),
    pad(date.getSeconds()),
  ].join('')
}

interface TextEditorState {
  point: DrawPoint
  editingId: string | null
}

export default function DrawRulePage() {
  const [lotteryCode, setLotteryCode] = useState(initialLotteryCode)
  const [periodCount, setPeriodCount] = useState(10)
  const [history, setHistory] = useState<DrawHistoryInput[]>([])
  const [pending, setPending] = useState(true)
  const [viewportWidth] = useState(() => {
    try {
      return Taro.getSystemInfoSync().windowWidth || 375
    } catch {
      return 375
    }
  })

  const [drawItems, setDrawItems] = useState<DrawItem[]>([])
  const [redoItems, setRedoItems] = useState<DrawItem[]>([])
  const [markedDigitKeys, setMarkedDigitKeys] = useState<Set<string>>(new Set())
  const [markedDigitColors, setMarkedDigitColors] = useState<Record<string, string>>({})
  const [predictionMarks, setPredictionMarks] = useState<PredictionMark[]>([])
  const [simplePredictionMarks, setSimplePredictionMarks] = useState<SimplePredictionMark[]>([])

  const [activeTool, setActiveTool] = useState<DrawTool>('智能线')
  const [activeStroke, setActiveStroke] = useState('细线')
  const [activeColor, setActiveColor] = useState('#ff0707')
  const [isScrollMode, setIsScrollMode] = useState(false)

  const [smart, setSmart] = useState<SmartSetting>({
    enabled: true,
    colorMode: 'single',
    lineShape: 'straight',
    gap: 0,
    penCount: 1,
  })

  const [activeSmartControlLineId, setActiveSmartControlLineId] = useState<string | null>(null)
  const [activeTextItemId, setActiveTextItemId] = useState<string | null>(null)
  const [draft, setDraft] = useState<DraftState | null>(null)
  const [previewStartCells, setPreviewStartCells] = useState<DigitCellTarget[]>([])
  const [previewTargetCells, setPreviewTargetCells] = useState<DigitCellTarget[]>([])
  const [textEditor, setTextEditor] = useState<TextEditorState | null>(null)
  const [textValue, setTextValue] = useState('')

  const [toolSheetVisible, setToolSheetVisible] = useState(false)
  const [colorSheetVisible, setColorSheetVisible] = useState(false)
  const [smartSheetVisible, setSmartSheetVisible] = useState(false)
  const [basicSheetVisible, setBasicSheetVisible] = useState(false)
  const [predictionCell, setPredictionCell] = useState<DigitCellTarget | null>(null)
  const [predictionSheetVisible, setPredictionSheetVisible] = useState(false)

  const [scrollTop, setScrollTop] = useState(0)
  const [scrollAnchor, setScrollAnchor] = useState(0)
  const [saving, setSaving] = useState(false)

  const engineRef = useRef<DrawEngineRef | null>(null)
  const draftStartRef = useRef<DrawPoint | null>(null)
  const draftPointsRef = useRef<number[]>([])
  const smartHoldTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null)
  const smartStartCellRef = useRef<DigitCellTarget | null>(null)
  const smartDraggingRef = useRef(false)
  const previewCellRef = useRef<DigitCellTarget | null>(null)
  const lastPointerRef = useRef<DrawPoint | null>(null)
  const suppressNextClickRef = useRef(false)
  const suppressUntilRef = useRef(0)
  const suppressPointRef = useRef<DrawPoint | null>(null)
  const lastTapRef = useRef<{ time: number; point: DrawPoint } | null>(null)

  // ---------- 数据 ----------

  const drawCount = drawCountOf(lotteryCode)
  const sumDigitCount = sumDigitCountOf(lotteryCode)

  useEffect(() => {
    let cancelled = false
    setPending(true)
    fetchDrawDailyDetail(lotteryCode, periodCount)
      .then((res) => {
        if (cancelled) return
        setHistory(
          (res.history || []).map((row) => ({
            drawNum: row.drawNum,
            numbers: row.numbers,
            drawTime: row.drawTime || '',
          })),
        )
      })
      .catch(() => {
        if (!cancelled) toast(labels.errors.drawsLoadFailed)
      })
      .finally(() => {
        if (!cancelled) setPending(false)
      })
    return () => {
      cancelled = true
    }
  }, [lotteryCode, periodCount])

  const boardRows = useMemo<BoardRow[]>(
    () => buildBoardRows(history, periodCount, drawCount, sumDigitCount),
    [history, periodCount, drawCount, sumDigitCount],
  )
  const geometry = useMemo(
    () => computeBoardGeometry(viewportWidth, drawCount, boardRows.length),
    [viewportWidth, drawCount, boardRows.length],
  )
  const boardSignature = useMemo(
    () => `${lotteryCode}:${boardRows.map((row) => row.key).join('|')}`,
    [lotteryCode, boardRows],
  )

  // 换彩种/期数（棋盘结构变化）→ 清空全部绘制内容并滚到底部（源 watch boardSignature + resetGuideLines）
  useEffect(() => {
    cancelTextEditor()
    cancelSmartLineInteraction()
    setActiveSmartControlLineId(null)
    setActiveTextItemId(null)
    setRedoItems([])
    setMarkedDigitKeys(new Set())
    setMarkedDigitColors({})
    setPredictionMarks([])
    setSimplePredictionMarks([])
    setDrawItems([])
    setScrollAnchor(boardRows.length * geometry.rowHeight + 1)
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [boardSignature])

  const activeStrokeWidth = STROKE_OPTIONS.find((item) => item.label === activeStroke)?.width || 2

  const markedDigitCells = useMemo(
    () => computeMarkedDigitCells(geometry, boardRows, drawCount, markedDigitKeys, markedDigitColors, activeColor),
    [geometry, boardRows, drawCount, markedDigitKeys, markedDigitColors, activeColor],
  )
  const simplePredictionCells = useMemo(
    () => computeSimplePredictionCells(geometry, boardRows, drawCount, simplePredictionMarks),
    [geometry, boardRows, drawCount, simplePredictionMarks],
  )
  const predictionRenderMarks = useMemo(
    () => computePredictionRenderMarks(geometry, boardRows, drawCount, predictionMarks),
    [geometry, boardRows, drawCount, predictionMarks],
  )
  const digitMarks = useMemo(
    () => [...markedDigitCells, ...simplePredictionCells],
    [markedDigitCells, simplePredictionCells],
  )

  const hasDrawableContent =
    drawItems.length > 0 ||
    markedDigitKeys.size > 0 ||
    predictionMarks.length > 0 ||
    simplePredictionMarks.length > 0

  // ---------- 绘制内容增删（撤销双栈：源 3588-3606） ----------

  function findDrawItem(id: string) {
    return drawItems.find((item) => item.id === id)
  }

  function commitDrawItem(item: DrawItem) {
    setDrawItems((prev) => [...prev, item])
    setRedoItems([])
  }

  function commitDrawItems(items: DrawItem[]) {
    if (!items.length) return
    setDrawItems((prev) => [...prev, ...items])
    setRedoItems([])
  }

  function updateDrawItem(id: string, patch: Partial<DrawItem>, resetRedo = true) {
    setDrawItems((prev) => prev.map((item) => (item.id === id ? { ...item, ...patch } : item)))
    if (resetRedo) setRedoItems([])
  }

  function removeDrawItem(id: string) {
    if (activeSmartControlLineId === id) setActiveSmartControlLineId(null)
    if (activeTextItemId === id) setActiveTextItemId(null)
    setDrawItems((prev) => prev.filter((item) => item.id !== id))
    setRedoItems([])
  }

  function undoDrawItem() {
    if (!drawItems.length) return
    const last = drawItems[drawItems.length - 1]
    if (activeSmartControlLineId === last.id) setActiveSmartControlLineId(null)
    if (activeTextItemId === last.id) setActiveTextItemId(null)
    setDrawItems(drawItems.slice(0, -1))
    setRedoItems([last, ...redoItems])
  }

  function redoDrawItem() {
    const next = redoItems[0]
    if (!next) return
    setRedoItems(redoItems.slice(1))
    setDrawItems([...drawItems, next])
  }

  function clearDrawItems() {
    cancelTextEditor()
    cancelSmartLineInteraction()
    cancelDraft()
    setActiveSmartControlLineId(null)
    setActiveTextItemId(null)
    setRedoItems(drawItems)
    setMarkedDigitKeys(new Set())
    setMarkedDigitColors({})
    setPredictionMarks([])
    setSimplePredictionMarks([])
    setDrawItems([])
  }

  // ---------- 点击抑制（源 suppressUpcomingStageClicks 系列） ----------

  function suppressUpcomingStageClicks(point?: DrawPoint | null) {
    suppressNextClickRef.current = true
    suppressUntilRef.current = Date.now() + STAGE_CLICK_DEDUPE_DELAY
    suppressPointRef.current = point ? { x: point.x, y: point.y } : null
    lastTapRef.current = null
  }

  function shouldSuppressStageClick(pointer: DrawPoint) {
    const now = Date.now()
    if (suppressNextClickRef.current) {
      suppressNextClickRef.current = false
      lastTapRef.current = null
      return true
    }
    if (
      suppressUntilRef.current > now &&
      (!suppressPointRef.current || pointDistance(suppressPointRef.current, pointer) <= STAGE_CLICK_DEDUPE_DISTANCE)
    ) {
      lastTapRef.current = null
      return true
    }
    if (suppressUntilRef.current <= now) {
      suppressUntilRef.current = 0
      suppressPointRef.current = null
    }
    return false
  }

  /** H5 端 Konva 同时触发 click/tap，按时间+位置去重 */
  function shouldSkipDuplicateTap(pointer: DrawPoint) {
    const now = Date.now()
    const last = lastTapRef.current
    if (last && now - last.time <= STAGE_CLICK_DEDUPE_DELAY && pointDistance(last.point, pointer) <= STAGE_CLICK_DEDUPE_DISTANCE) {
      lastTapRef.current = null
      return true
    }
    lastTapRef.current = { time: now, point: { x: pointer.x, y: pointer.y } }
    return false
  }

  // ---------- 草稿 ----------

  function cancelDraft() {
    draftStartRef.current = null
    draftPointsRef.current = []
    setDraft(null)
  }

  function buildShapeDraft(start: DrawPoint, end: DrawPoint): DraftState {
    const tool = activeTool
    const dashed = !tool.startsWith('实心')
    const fill = shapeFillColor(tool, activeColor)
    if (tool.includes('圆形')) {
      return { kind: 'ellipse', ...normalizeEllipse(start, end), dashed, fill, stroke: activeColor, strokeWidth: activeStrokeWidth }
    }
    return { kind: 'rect', ...normalizeRect(start, end), dashed, fill, stroke: activeColor, strokeWidth: activeStrokeWidth }
  }

  function commitShapeItem(start: DrawPoint, end: DrawPoint) {
    const tool = activeTool
    const fill = shapeFillColor(tool, activeColor)
    const common = { id: createDrawId(), stroke: activeColor, fill, strokeWidth: activeStrokeWidth }
    if (tool.includes('圆形')) {
      commitDrawItem({ ...common, type: 'circle', ...normalizeEllipse(start, end) })
      return
    }
    commitDrawItem({ ...common, type: 'rect', ...normalizeRect(start, end) })
  }

  // ---------- 智能线 ----------

  function isPredictionCell(cell: DigitCellTarget) {
    return Boolean(boardRows[cell.rowIndex]?.prediction)
  }

  function hasPredictionMarkForCell(cell: DigitCellTarget) {
    return Boolean(findSimplePredictionByCell(cell) || findPredictionByCell(cell))
  }

  function shouldRenderSmartPreviewMark(cell: DigitCellTarget) {
    return !isPredictionCell(cell) || !hasPredictionMarkForCell(cell)
  }

  function clearSmartHoldTimer() {
    if (smartHoldTimerRef.current) {
      clearTimeout(smartHoldTimerRef.current)
      smartHoldTimerRef.current = null
    }
  }

  function beginSmartLineHold(point: DrawPoint) {
    const cell = resolveDigitCell(geometry, boardRows, point, drawCount)
    if (!cell) return
    if (isPredictionCell(cell) && !hasPredictionMarkForCell(cell)) return
    clearSmartHoldTimer()
    smartStartCellRef.current = cell
    smartDraggingRef.current = false
    suppressNextClickRef.current = false
    suppressUntilRef.current = 0
    suppressPointRef.current = null
    smartHoldTimerRef.current = setTimeout(() => {
      startSmartLineDrag()
    }, SMART_LINE_HOLD_DELAY)
  }

  function startSmartLineDrag() {
    if (!smartStartCellRef.current) return
    smartDraggingRef.current = true
    const pointer = lastPointerRef.current || smartStartCellRef.current
    suppressUpcomingStageClicks(pointer)
    updateSmartLineDraft(pointer)
  }

  function updateSmartLineDraft(pointer: DrawPoint) {
    const startCell = smartStartCellRef.current
    if (!startCell) return
    const targetCell = resolveDigitCell(geometry, boardRows, pointer, drawCount)
    previewCellRef.current = targetCell && targetCell.key !== startCell.key ? targetCell : null
    const segments = buildSmartLineDraftSegments(
      geometry,
      boardRows,
      drawCount,
      startCell,
      targetCell,
      pointer,
      smart.penCount,
      smart.gap,
      smart.colorMode,
      activeColor,
    )
    setPreviewStartCells(
      segments.map((segment) => ({ ...segment.start, color: segment.color })).filter(shouldRenderSmartPreviewMark),
    )
    setPreviewTargetCells(
      segments
        .filter((segment) => Boolean(segment.target) && segment.target?.key !== segment.start.key)
        .map((segment) => ({ ...segment.target!, color: segment.color }))
        .filter(shouldRenderSmartPreviewMark),
    )
    setDraft({ kind: 'smart', segments, shape: smart.lineShape, strokeWidth: activeStrokeWidth })
  }

  function finishSmartLineDrag(pointer: DrawPoint | null) {
    clearSmartHoldTimer()
    const wasDragging = smartDraggingRef.current
    const startCell = smartStartCellRef.current
    const targetCell = pointer ? resolveDigitCell(geometry, boardRows, pointer, drawCount) : previewCellRef.current

    smartStartCellRef.current = null
    smartDraggingRef.current = false
    previewCellRef.current = null
    setPreviewStartCells([])
    setPreviewTargetCells([])
    setDraft(null)

    if (!wasDragging) return
    suppressUpcomingStageClicks(pointer || targetCell || startCell)
    cancelDraft()
    if (!startCell || !targetCell || targetCell.key === startCell.key) return

    const segments = buildSmartLineSegments(
      geometry,
      boardRows,
      drawCount,
      startCell,
      targetCell,
      smart.penCount,
      smart.gap,
      smart.colorMode,
      activeColor,
    )
    if (!segments.length) return

    const nextKeys = new Set(markedDigitKeys)
    const nextColors = { ...markedDigitColors }
    segments.forEach((segment) => {
      nextKeys.add(segment.start.key)
      nextKeys.add(segment.target.key)
      nextColors[segment.start.key] = segment.color
      nextColors[segment.target.key] = segment.color
    })
    setMarkedDigitKeys(nextKeys)
    setMarkedDigitColors(nextColors)

    const newItems: DrawItem[] = segments.map((segment) => ({
      id: createDrawId(),
      type: 'polyline',
      lineKind: 'smart',
      smartShape: smart.lineShape,
      smartStart: digitCellAnchor(segment.start),
      smartEnd: digitCellAnchor(segment.target),
      points: [segment.start.x, segment.start.y, segment.target.x, segment.target.y],
      stroke: segment.color,
      strokeWidth: activeStrokeWidth,
    }))
    setActiveSmartControlLineId(smart.enabled ? newItems[0]?.id || null : null)
    commitDrawItems(newItems)
  }

  function cancelSmartLineInteraction() {
    clearSmartHoldTimer()
    smartStartCellRef.current = null
    smartDraggingRef.current = false
    previewCellRef.current = null
    setPreviewStartCells([])
    setPreviewTargetCells([])
    suppressNextClickRef.current = false
    suppressUntilRef.current = 0
    suppressPointRef.current = null
    setDraft((prev) => (prev?.kind === 'smart' ? null : prev))
  }

  // ---------- 引擎事件 ----------

  function handlePointerDown(point: DrawPoint, hit: DrawEngineHit) {
    lastPointerRef.current = point
    if (activeTool === '智能线') {
      if (hit.type === 'smartControl') return
      beginSmartLineHold(point)
      return
    }
    if (hit.type !== 'board') return
    if (activeTool === '直线') {
      draftStartRef.current = point
      draftPointsRef.current = [point.x, point.y, point.x, point.y]
      setDraft({ kind: 'line', points: [point.x, point.y, point.x, point.y], dashed: true, stroke: activeColor, strokeWidth: activeStrokeWidth })
    } else if (activeTool === '自由线') {
      draftStartRef.current = point
      draftPointsRef.current = [point.x, point.y]
      setDraft({ kind: 'freeLine', points: [point.x, point.y], stroke: activeColor, strokeWidth: activeStrokeWidth })
    } else if (isShapeTool(activeTool)) {
      draftStartRef.current = point
      setDraft(buildShapeDraft(point, point))
    }
  }

  function handlePointerMove(point: DrawPoint) {
    lastPointerRef.current = point
    if (activeTool === '智能线') {
      if (smartStartCellRef.current && smartDraggingRef.current) updateSmartLineDraft(point)
      return
    }
    const start = draftStartRef.current
    if (!start) return
    if (activeTool === '直线') {
      draftPointsRef.current = [start.x, start.y, point.x, point.y]
      setDraft({ kind: 'line', points: [start.x, start.y, point.x, point.y], dashed: true, stroke: activeColor, strokeWidth: activeStrokeWidth })
    } else if (activeTool === '自由线') {
      draftPointsRef.current = [...draftPointsRef.current, point.x, point.y]
      setDraft({ kind: 'freeLine', points: [...draftPointsRef.current], stroke: activeColor, strokeWidth: activeStrokeWidth })
    } else if (isShapeTool(activeTool)) {
      setDraft(buildShapeDraft(start, point))
    }
  }

  function handlePointerUp(point: DrawPoint | null) {
    if (activeTool === '智能线') {
      finishSmartLineDrag(point)
      return
    }
    const start = draftStartRef.current
    if (!start) return
    if (!point) {
      cancelDraft()
      return
    }
    if (activeTool === '直线' && pointDistance(start, point) > 4) {
      suppressUpcomingStageClicks(point)
      commitDrawItem({
        id: createDrawId(),
        type: 'polyline',
        lineKind: 'straight',
        points: [start.x, start.y, point.x, point.y],
        stroke: activeColor,
        strokeWidth: activeStrokeWidth,
      })
    } else if (activeTool === '自由线' && draftPointsRef.current.length > 5) {
      commitDrawItem({
        id: createDrawId(),
        type: 'freeLine',
        points: [...draftPointsRef.current],
        stroke: activeColor,
        strokeWidth: activeStrokeWidth,
      })
    } else if (isShapeTool(activeTool) && pointDistance(start, point) > 4) {
      commitShapeItem(start, point)
    }
    cancelDraft()
  }

  function handleTap(point: DrawPoint, hit: DrawEngineHit) {
    if (shouldSuppressStageClick(point)) return
    if (shouldSkipDuplicateTap(point)) return

    if (activeTool === '添加文字' && hit.type === 'board') {
      openTextEditor(point)
      return
    }

    const cell = resolveDigitCell(geometry, boardRows, point, drawCount)
    const isCellClickTool = activeTool === '智能线' || activeTool === '直线'
    if (isCellClickTool && cell) {
      if (isPredictionCell(cell)) {
        openPredictionPanel(cell)
        return
      }
      toggleDigitMark(cell)
      return
    }

    if (hit.type === 'item' && hit.itemId) {
      const item = findDrawItem(hit.itemId)
      if (!item) return
      if (activeTool === '橡皮擦') {
        removeDrawItem(item.id)
        return
      }
      if (item.type === 'text') {
        cancelTextEditor()
        setActiveTextItemId(item.id)
        return
      }
      if (smart.enabled && item.type === 'polyline' && item.lineKind === 'smart') {
        setActiveSmartControlLineId(item.id)
      }
      return
    }

    if (hit.type === 'board') {
      setActiveTextItemId(null)
    }
  }

  function handleItemDrag(id: string, position: DrawPoint) {
    updateDrawItem(id, { x: position.x, y: position.y }, false)
  }

  function handleSmartControlDrag(id: string, point: DrawPoint, final: boolean) {
    const item = findDrawItem(id)
    if (!item) return
    if (final) {
      setActiveSmartControlLineId(null)
      updateDrawItem(id, smartLineControlPatch(item, point, geometry, boardRows, drawCount), false)
      return
    }
    updateDrawItem(id, { controlPoint: point }, false)
  }

  function handleTextEdit(id: string) {
    const item = findDrawItem(id)
    if (!item || item.type !== 'text') return
    setActiveTextItemId(id)
    setTextEditor({ point: { x: item.x || 0, y: item.y || 0 }, editingId: id })
    setTextValue(item.text || '')
  }

  function handleTextOpacityToggle(id: string) {
    const item = findDrawItem(id)
    if (!item || item.type !== 'text') return
    setActiveTextItemId(id)
    updateDrawItem(id, { textTransparent: !item.textTransparent, opacity: 1 }, false)
  }

  // ---------- 文字 ----------

  function openTextEditor(point: DrawPoint) {
    setActiveTextItemId(null)
    setTextEditor({ point, editingId: null })
    setTextValue('')
  }

  function cancelTextEditor() {
    setTextEditor(null)
    setTextValue('')
  }

  function commitTextEditor() {
    const editor = textEditor
    const text = textValue.trim()
    cancelTextEditor()
    if (!editor || !text) return
    const width = measureTextWidth(text)
    if (editor.editingId) {
      updateDrawItem(editor.editingId, { text, width }, false)
      return
    }
    const id = createDrawId()
    setActiveTextItemId(id)
    commitDrawItem({
      id,
      type: 'text',
      x: editor.point.x,
      y: editor.point.y,
      width,
      height: TEXT_DEFAULT_HEIGHT,
      text,
      stroke: activeColor,
      strokeWidth: activeStrokeWidth,
      opacity: 1,
      rotation: 0,
      scale: 1,
      textTransparent: false,
    })
  }

  // ---------- 数字标记 / 预测 ----------

  function toggleDigitMark(cell: DigitCellTarget) {
    if (isPredictionCell(cell)) return
    const key = cell.key
    const next = new Set(markedDigitKeys)
    const nextColors = { ...markedDigitColors }
    if (next.has(key)) {
      next.delete(key)
      delete nextColors[key]
    } else {
      next.add(key)
      nextColors[key] = activeColor
    }
    setMarkedDigitKeys(next)
    setMarkedDigitColors(nextColors)
  }

  function findPredictionByCell(cell: DigitCellTarget) {
    const row = boardRows[cell.rowIndex]
    if (!row) return null
    return (
      predictionMarks.find(
        (mark) => mark.rowKey === row.key && predictionColumnsForMark(mark, drawCount).includes(cell.columnIndex),
      ) || null
    )
  }

  function findSimplePredictionByCell(cell: DigitCellTarget) {
    return (
      simplePredictionMarks.find((mark) => mark.rowKey === cell.rowKey && mark.columnIndex === cell.columnIndex) || null
    )
  }

  function removePredictionGroup(mark: PredictionMark) {
    const columns = predictionColumnsForMark(mark, drawCount)
    setPredictionMarks((prev) =>
      prev.filter(
        (item) => item.rowKey !== mark.rowKey || item.condition !== mark.condition || !columns.includes(item.columnIndex),
      ),
    )
    const nextKeys = new Set(markedDigitKeys)
    const nextColors = { ...markedDigitColors }
    columns.forEach((columnIndex) => {
      const key = digitCellKey(mark.rowKey, columnIndex)
      nextKeys.delete(key)
      delete nextColors[key]
    })
    setMarkedDigitKeys(nextKeys)
    setMarkedDigitColors(nextColors)
  }

  function removePredictionForCell(cell: DigitCellTarget) {
    const existing = findPredictionByCell(cell)
    if (!existing) return
    const columns = predictionColumnsForMark(existing, drawCount)
    setPredictionMarks((prev) =>
      prev.filter(
        (item) =>
          item.rowKey !== existing.rowKey || item.condition !== existing.condition || !columns.includes(item.columnIndex),
      ),
    )
  }

  function openPredictionPanel(cell: DigitCellTarget) {
    const existingSimple = findSimplePredictionByCell(cell)
    if (existingSimple) {
      setSimplePredictionMarks((prev) => prev.filter((item) => item.id !== existingSimple.id))
      return
    }
    const existing = findPredictionByCell(cell)
    if (existing) {
      removePredictionGroup(existing)
      return
    }
    setPredictionCell(cell)
    setPredictionSheetVisible(true)
    setSmartSheetVisible(false)
  }

  /** 高级模式确认（源 confirmPredictionPanel，纯前端） */
  function handlePredictionConfirm(payload: PredictionConfirmPayload) {
    const cell = predictionCell
    if (!cell) return
    const row = boardRows[cell.rowIndex]
    if (!row) return
    const columns = predictionColumnsForActiveCondition(payload.condition, cell, drawCount)
    if (!columns.length) return
    const nextMarks = predictionMarks.filter((mark) => {
      if (mark.rowKey !== row.key) return true
      const markColumns = predictionColumnsForMark(mark, drawCount)
      return !markColumns.some((columnIndex) => columns.includes(columnIndex))
    })
    const common = {
      rowKey: row.key,
      condition: payload.condition,
      conditionLabel: payload.conditionLabel,
      numbers: payload.numbers,
      fillMode: payload.fillMode,
      color: activeColor,
    }
    setPredictionMarks([
      ...nextMarks,
      ...predictionMarkColumnsForCommit(payload.condition, columns).map((columnIndex) => ({
        id: `prediction-${row.key}-${columnIndex}-${Date.now()}`,
        columnIndex,
        ...common,
      })),
    ])
    setPredictionSheetVisible(false)
  }

  function handleSimplePredictionSelect(value: string) {
    const cell = predictionCell
    if (!cell) return
    const row = boardRows[cell.rowIndex]
    if (!row) return
    const id = `simple-prediction-${row.key}-${cell.columnIndex}`
    setSimplePredictionMarks([
      ...simplePredictionMarks.filter((mark) => !(mark.rowKey === row.key && mark.columnIndex === cell.columnIndex)),
      { id, rowKey: row.key, columnIndex: cell.columnIndex, value, color: activeColor },
    ])
    removePredictionForCell(cell)
    setPredictionSheetVisible(false)
  }

  // ---------- 工具栏 / 模式 ----------

  function selectTool(tool: DrawTool) {
    setActiveTool(tool)
    cancelTextEditor()
    setActiveTextItemId(null)
    cancelSmartLineInteraction()
    cancelDraft()
    setSmartSheetVisible(false)
    setToolSheetVisible(false)
    setBasicSheetVisible(false)
  }

  function toggleScrollMode() {
    const next = !isScrollMode
    setIsScrollMode(next)
    toast(next ? labels.scrollMode : labels.drawMode)
    setColorSheetVisible(false)
    setToolSheetVisible(false)
    setBasicSheetVisible(false)
    if (next) {
      setSmartSheetVisible(false)
      cancelSmartLineInteraction()
      cancelDraft()
    }
  }

  function handleColorChange(color: string) {
    setActiveColor(color)
    if (activeTextItemId) {
      updateDrawItem(activeTextItemId, { stroke: color }, false)
    }
  }

  function handleSmartChange(patch: Partial<SmartSetting>) {
    const next: SmartSetting = { ...smart, ...patch }
    if (next.penCount <= 1) {
      next.colorMode = 'single'
      next.gap = 0
    }
    setSmart(next)
    if (patch.enabled === false) {
      setActiveSmartControlLineId(null)
    }
  }

  // ---------- 保存 ----------

  async function handleSave() {
    if (saving) return
    cancelTextEditor()
    cancelSmartLineInteraction()
    cancelDraft()
    setActiveSmartControlLineId(null)
    setActiveTextItemId(null)
    setSaving(true)
    try {
      // 等一帧让控制点/选中框从画面移除再截图
      await new Promise((resolve) => setTimeout(resolve, 80))
      const dataUrl = await engineRef.current?.capturePngDataURL()
      if (!dataUrl) throw new Error('capture failed')
      const fileName = labels.saveFileName(getLotteryLabel(lotteryCode), formatExportTimestamp(new Date()))
      const ok = await savePngToDevice(dataUrl, fileName)
      if (!ok) throw new Error('save failed')
    } catch {
      toast(labels.errors.saveFailed)
    } finally {
      setSaving(false)
    }
  }

  // ---------- 渲染 ----------

  const topActions: Array<{ key: string; label: string; disabled: boolean; onTap?: () => void }> = [
    { key: 'undo', label: labels.actionUndo, disabled: !drawItems.length, onTap: undoDrawItem },
    { key: 'redo', label: labels.actionRedo, disabled: !redoItems.length, onTap: redoDrawItem },
    { key: 'clear', label: labels.actionClear, disabled: !hasDrawableContent, onTap: clearDrawItems },
    { key: 'share', label: labels.actionShare, disabled: true },
    { key: 'save', label: labels.actionSave, disabled: !hasDrawableContent || saving, onTap: () => void handleSave() },
    { key: 'settings', label: labels.actionSettings, disabled: false, onTap: () => setBasicSheetVisible(true) },
  ]

  return (
    <View className={`draw-rule-page${process.env.TARO_ENV === 'h5' ? ' draw-rule-page--h5' : ''}`}>
      <View className='draw-rule-toolbar'>
        {topActions.map((action) => (
          <View
            key={action.key}
            className={`draw-rule-toolbar__btn${action.disabled ? ' is-disabled' : ''}`}
            onClick={() => {
              if (!action.disabled) action.onTap?.()
            }}
          >
            <Text className='draw-rule-toolbar__text'>{action.label}</Text>
          </View>
        ))}
      </View>

      <View className='draw-rule-body'>
        {pending && !history.length ? (
          <View className='draw-rule-loading'>
            <Text className='draw-rule-loading__text'>{labels.loadingDraws}</Text>
          </View>
        ) : (
          <ScrollView
            scrollY
            className='draw-rule-scroll'
            scrollTop={scrollAnchor}
            scrollWithAnimation={false}
            onScroll={(event) => setScrollTop(Number(event.detail?.scrollTop || 0))}
          >
            <View
              className='draw-rule-board'
              style={{ width: geometry.boardWidth, height: geometry.boardHeight }}
            >
              <DrawBoard rows={boardRows} geometry={geometry} lotteryCode={lotteryCode} drawCount={drawCount} />
              <DrawEngine
                ref={engineRef}
                geometry={geometry}
                rows={boardRows}
                drawCount={drawCount}
                items={drawItems}
                digitMarks={digitMarks}
                predictionMarks={predictionRenderMarks}
                previewStartCells={previewStartCells}
                previewTargetCells={previewTargetCells}
                draft={draft}
                interactive={!isScrollMode}
                scrollTop={scrollTop}
                activeTool={activeTool}
                activeSmartControlLineId={activeSmartControlLineId}
                activeTextItemId={activeTextItemId}
                smartPenEnabled={smart.enabled}
                onPointerDown={handlePointerDown}
                onPointerMove={handlePointerMove}
                onPointerUp={handlePointerUp}
                onTap={handleTap}
                onItemDragMove={handleItemDrag}
                onItemDragEnd={handleItemDrag}
                onSmartControlDrag={handleSmartControlDrag}
                onTextEdit={handleTextEdit}
                onTextOpacityToggle={handleTextOpacityToggle}
                onTextTransform={(id, patch) => updateDrawItem(id, patch, false)}
              />
              {textEditor ? (
                <Input
                  className='draw-text-editor'
                  style={{
                    left: textEditor.point.x,
                    top: textEditor.point.y,
                    color: activeColor,
                    borderColor: activeColor,
                  }}
                  value={textValue}
                  focus
                  onInput={(event) => setTextValue(event.detail.value)}
                  onBlur={commitTextEditor}
                  onConfirm={commitTextEditor}
                />
              ) : null}
            </View>
          </ScrollView>
        )}

        {/* 底部悬浮操作：颜色（左）/ 滚动锁定（中）/ 工具（右） */}
        <View className='draw-rule-fab draw-rule-fab--color' onClick={() => setColorSheetVisible(true)}>
          <View className='draw-rule-fab__color-dot' style={{ backgroundColor: activeColor }} />
        </View>
        <View className='draw-rule-fab draw-rule-fab--lock' onClick={toggleScrollMode}>
          <Text className='draw-rule-fab__lock-text'>{isScrollMode ? '⇅' : '🔒'}</Text>
        </View>
        <View className='draw-rule-fab draw-rule-fab--tool'>
          {activeTool === '智能线' ? (
            <View className='draw-rule-fab__smart' onClick={() => setSmartSheetVisible(true)}>
              <Text className='draw-rule-fab__smart-text'>{labels.actionSettings}</Text>
            </View>
          ) : null}
          <View className='draw-rule-fab__tool-btn' onClick={() => setToolSheetVisible(true)}>
            <Text className='draw-rule-fab__tool-icon'>{TOOL_ICON_TEXT[activeTool]}</Text>
          </View>
        </View>
      </View>

      <ToolSheet
        visible={toolSheetVisible}
        activeTool={activeTool}
        onSelect={selectTool}
        onOpenSmartSetting={() => {
          setToolSheetVisible(false)
          setSmartSheetVisible(true)
        }}
        onClose={() => setToolSheetVisible(false)}
      />
      <ColorSheet
        visible={colorSheetVisible}
        activeColor={activeColor}
        activeStroke={activeStroke}
        onColorChange={handleColorChange}
        onStrokeChange={setActiveStroke}
        onClose={() => setColorSheetVisible(false)}
      />
      <SmartSettingSheet
        visible={smartSheetVisible}
        value={smart}
        onChange={handleSmartChange}
        onClose={() => setSmartSheetVisible(false)}
      />
      <BasicSettingSheet
        visible={basicSheetVisible}
        lotteryCode={lotteryCode}
        periodCount={periodCount}
        onLotteryChange={setLotteryCode}
        onPeriodChange={(count) => setPeriodCount(normalizePeriodCount(count))}
        onClose={() => setBasicSheetVisible(false)}
      />
      <PredictionSheet
        visible={predictionSheetVisible}
        cell={predictionCell}
        drawCount={drawCount}
        color={activeColor}
        onConfirm={handlePredictionConfirm}
        onSimpleSelect={handleSimplePredictionSelect}
        onClose={() => setPredictionSheetVisible(false)}
      />
    </View>
  )
}
