import { useCallback, useState } from 'react'
import Taro from '@tarojs/taro'
import { useSmsCountdown } from './useSmsCountdown'

interface Options {
  /** 发送成功 toast 文案 */
  sentTitle: string
  /** 发送失败且错误对象无 message 时的兜底 toast 文案 */
  failTitle: string
}

/**
 * 验证码发送统一封装（登录/注册/忘记密码/修改密码弹层共用，短信/邮箱验证码通用）：
 * - 慢网防重发：倒计时未结束或请求在途（倒计时尚未启动）时点击直接忽略
 * - 成功/失败 toast 与倒计时驱动收口在一处，页面只保留各自的表单预校验后调 sendCode()
 * 页面写法：`const { countdown, sending, disabled, sendCode, stop } = useCodeSender(() => sendXxxApi(...), { sentTitle, failTitle })`
 */
export function useCodeSender(send: () => Promise<unknown>, { sentTitle, failTitle }: Options) {
  const [sending, setSending] = useState(false)
  const { countdown, start, stop } = useSmsCountdown()

  const sendCode = useCallback(async () => {
    if (countdown > 0 || sending) return
    setSending(true)
    try {
      await send()
      Taro.showToast({ title: sentTitle, icon: 'none' })
      start()
    } catch (err: any) {
      Taro.showToast({ title: err?.message || failTitle, icon: 'none' })
    } finally {
      setSending(false)
    }
  }, [countdown, sending, send, sentTitle, failTitle, start])

  return { countdown, sending, disabled: countdown > 0 || sending, sendCode, stop }
}
