// RN 端：react-native-wechat-lib 拉起微信 APP 支付（原生能力由壳工程 taro-native-shell 提供）
import * as WeChat from 'react-native-wechat-lib'
import { WX_APP_ID, WX_UNIVERSAL_LINK } from '@/constants/pay'

// registerApp 全局只需一次，缓存 Promise 避免重复注册
let registerPromise: Promise<boolean> | null = null
const ensureRegistered = () => {
  if (!registerPromise) {
    registerPromise = WeChat.registerApp(WX_APP_ID, WX_UNIVERSAL_LINK)
  }
  return registerPromise
}

/**
 * 拉起微信 APP 支付，返回是否成功拉起。
 * 支付结果不以 SDK 回调为准（用户取消 errCode 非 0 也视为已拉起），统一由 /pay/query 轮询兜底。
 */
export async function launchWxAppPay(orderInfo: unknown): Promise<boolean> {
  try {
    if (!(await ensureRegistered())) return false
    if (!(await WeChat.isWXAppInstalled())) return false
    let params: any = orderInfo
    if (typeof orderInfo === 'string') {
      params = JSON.parse(orderInfo)
    }
    if (typeof params !== 'object' || !params) return false
    await WeChat.pay({
      partnerId: String(params.partnerId || ''),
      prepayId: String(params.prepayId || ''),
      nonceStr: String(params.nonceStr || ''),
      timeStamp: String(params.timeStamp || ''),
      package: String(params.package || params.packageValue || 'Sign=WXPay'),
      sign: String(params.sign || ''),
    })
    return true
  } catch {
    return false
  }
}
