import { useEffect, useRef, useState } from 'react'
import { View, Text } from '@tarojs/components'
import Popup from '@/components/SheetPopup'
import Skeleton from '@/components/Skeleton'
import { fetchIntegralPackages } from '@/services/api'
import type { IntegralPackage } from '@/types'
import { runCashPay } from '@/utils/pay'
import CashPayButtons, { CashChannel } from '@/components/pay/CashPayButtons'
import { mineLabels } from '@/labels/mine'
// RN 端 className→style 由 babel 插件按文件收集样式表（babel-plugin-transform-react-jsx-to-rn-stylesheet），
// 本文件用到的 .sheet/.recharge-* 类来自页面样式，必须在本文件显式 import，否则 RN 端样式全丢
import './index.css'

interface Props {
  visible: boolean
  onClose: () => void
  /** 充值成功（订单 PAID）后回调：页面刷新积分余额与 profile */
  onPaid?: () => void
}

/**
 * 积分充值弹层（PRD §6.9 充值弹窗）：套餐列表（sort 升序，默认选中第一项）+ 渠道支付。
 * 链路：/pay/integralPackages → /pay/create（bizType=INTEGRAL_RECHARGE，bizId=套餐 id）
 * → 拉起渠道支付 → /pay/query 轮询至 PAID（编排见 @/utils/pay runCashPay）。
 */
export default function RechargeSheet({ visible, onClose, onPaid }: Props) {
  const [packages, setPackages] = useState<IntegralPackage[] | null>(null)
  const [selectedId, setSelectedId] = useState(0)
  const [paying, setPaying] = useState(false)
  // ref 锁：state 闭包在同一 commit 帧内双击会双过守卫；同时用于支付中拦截弹层关闭
  const payingRef = useRef(false)

  // 每次打开重新拉套餐；关闭时清空，重开不残留上次选中/加载态
  useEffect(() => {
    if (!visible) {
      setPackages(null)
      setSelectedId(0)
      return
    }
    let cancelled = false
    fetchIntegralPackages()
      .then((list) => {
        if (!cancelled) setPackages(list)
      })
      .catch(() => {
        if (!cancelled) setPackages([])
      })
    return () => {
      cancelled = true
    }
  }, [visible])

  // 选中项随接口数据兜底：selectedId 失效（套餐上下架变化）时回落第一项
  const selected = packages?.find((item) => item.id === selectedId) || packages?.[0] || null

  const handlePay = async (channel: CashChannel) => {
    if (!selected || payingRef.current) return
    payingRef.current = true
    setPaying(true)
    try {
      const paid = await runCashPay({
        bizType: 'INTEGRAL_RECHARGE',
        bizId: selected.id,
        channel,
        labels: {
          polling: mineLabels.memberPayPolling,
          success: mineLabels.rechargeSuccess,
          confirming: mineLabels.rechargeConfirming,
          closed: mineLabels.memberPayClosed,
          fail: mineLabels.memberPayFail,
          launchFail: mineLabels.memberPayLaunchFail,
        },
      })
      if (paid) {
        onClose()
        onPaid?.()
      }
    } finally {
      payingRef.current = false
      setPaying(false)
    }
  }

  return (
    // 支付中拦截蒙层/物理返回关闭：避免重开弹层按钮假死、在途回调误关新弹层
    <Popup visible={visible} onClose={() => !payingRef.current && onClose()}>
      <View className='sheet'>
        <Text className='sheet__title'>{mineLabels.rechargeTitle}</Text>
        {packages === null ? (
          <Skeleton rows={2} card={false} />
        ) : packages.length > 0 ? (
          <View className='recharge-grid'>
            {packages.map((item) => (
              <View
                key={item.id}
                className={`recharge-pack${selected?.id === item.id ? ' recharge-pack--active' : ''}`}
                onClick={() => setSelectedId(item.id)}
              >
                <Text className='recharge-pack__name'>{item.packageName}</Text>
                <Text className={`recharge-pack__integral${selected?.id === item.id ? ' recharge-pack__integral--active' : ''}`}>
                  {mineLabels.rechargeGrant(item.grantIntegral)}
                </Text>
                <Text className='recharge-pack__price'>{mineLabels.memberPrice(item.price as number)}</Text>
                {item.remark ? <Text className='recharge-pack__remark'>{item.remark}</Text> : null}
              </View>
            ))}
          </View>
        ) : (
          <Text className='recharge-empty'>{mineLabels.rechargeEmpty}</Text>
        )}

        {/* 渠道按钮组（自绘，NutButton 禁用）；不退款提示为合规要求 */}
        {selected ? (
          <CashPayButtons
            primary
            price={selected.price as number}
            paying={paying}
            noRefundHint={mineLabels.rechargeNoRefund}
            onPay={handlePay}
          />
        ) : null}
      </View>
    </Popup>
  )
}
