import { useEffect, useState } from 'react'
import { View, Text, Input } from '@tarojs/components'
import Taro from '@tarojs/taro'
import Popup from '@/components/SheetPopup'
import { sendSmsCodeApi, setPasswdApi } from '@/services/api'
import { useCodeSender } from '@/hooks/useCodeSender'
import { maskCnPhone } from '@/utils/phone'
import { authLabels } from '@/labels/auth'
import { mineLabels } from '@/labels/mine'
// RN 端 className→style 由 babel 插件按文件收集样式表（babel-plugin-transform-react-jsx-to-rn-stylesheet），
// 本文件用到的 .sheet/.form__*/.pwd-* 类来自页面样式，必须在本文件显式 import，否则 RN 端样式全丢
import './index.css'

/** 验证方式：旧密码 / 短信验证码（setPasswd 契约二选一，未设过密码只能用短信） */
type VerifyMode = 'old' | 'sms'

interface Props {
  visible: boolean
  /** 已绑定手机号，空串表示未绑定（此时仅旧密码验证可用） */
  boundPhone?: string
  /** 返回上一级（回到编辑资料弹层）；不传则不显示返回按钮 */
  onBack?: () => void
  onClose: () => void
}

/** 修改密码弹层（登录态 POST /biz/user/setPasswd）：短信/旧密码二选一验证 + 新密码 + 确认新密码 */
export default function ChangePasswordSheet({ visible, boundPhone = '', onBack, onClose }: Props) {
  const canSms = !!boundPhone
  const [mode, setMode] = useState<VerifyMode>('old')
  const [oldPasswd, setOldPasswd] = useState('')
  const [newPasswd, setNewPasswd] = useState('')
  const [confirmPasswd, setConfirmPasswd] = useState('')
  const [smsCode, setSmsCode] = useState('')
  const [submitting, setSubmitting] = useState(false)
  const { countdown, disabled: sendDisabled, sendCode, stop } = useCodeSender(
    () => sendSmsCodeApi(boundPhone),
    { sentTitle: authLabels.login.codeSent, failTitle: mineLabels.pwdSendFail },
  )

  // 每次打开重置表单；默认验证方式：已绑定手机走短信（覆盖未设过密码的场景），否则旧密码。
  // 关闭时停掉倒计时：本弹层随 profile 页常驻不卸载，不停则 1Hz interval 关闭后仍空转 ~60s，
  // 且重开时残留「Ns 后重发」无法重发
  useEffect(() => {
    if (visible) {
      setMode(canSms ? 'sms' : 'old')
      setOldPasswd('')
      setNewPasswd('')
      setConfirmPasswd('')
      setSmsCode('')
    } else {
      stop()
    }
  }, [visible, canSms, stop])

  const handleSubmit = async () => {
    if (submitting) return
    if (mode === 'old' && !oldPasswd.trim()) {
      Taro.showToast({ title: mineLabels.pwdOldRequired, icon: 'none' })
      return
    }
    if (mode === 'sms' && !smsCode.trim()) {
      Taro.showToast({ title: mineLabels.pwdCodeRequired, icon: 'none' })
      return
    }
    // 与后端 setPassword 对齐：先 trim（setPasswdApi 与后端存的均是 trim 后值），再校验 5-20 位
    const newPwd = newPasswd.trim()
    const confirmPwd = confirmPasswd.trim()
    if (!newPwd) {
      Taro.showToast({ title: authLabels.errors.newPasswordRequired, icon: 'none' })
      return
    }
    if (newPwd.length < 5 || newPwd.length > 20) {
      Taro.showToast({ title: mineLabels.pwdLengthInvalid, icon: 'none' })
      return
    }
    if (newPwd !== confirmPwd) {
      Taro.showToast({ title: authLabels.errors.passwordMismatch, icon: 'none' })
      return
    }
    setSubmitting(true)
    try {
      // 注意后端语义：仅对已设过密码的账号校验身份（旧密码/短信二选一）；未设过密码的账号
      // （短信验证码登录自动注册）setPasswd 不校验 smsCode——登录态即凭证（见后端
      // registerBizUserByPhone 注释）。前端默认短信验证主要为覆盖「已设密码」场景，
      // 首次设置时短信只是交互引导；如需服务端强校验，需后端对免密账号也验证或 profile 暴露已设密码标记
      await setPasswdApi({
        newPasswd: newPwd,
        confirmNewPasswd: confirmPwd,
        ...(mode === 'old' ? { oldPasswd: oldPasswd.trim() } : { smsCode: smsCode.trim() }),
      })
      Taro.showToast({ title: mineLabels.pwdSuccess, icon: 'success' })
      onClose()
    } catch (err: any) {
      Taro.showToast({ title: err?.message || mineLabels.pwdFail, icon: 'none' })
    } finally {
      setSubmitting(false)
    }
  }

  return (
    <Popup visible={visible} onClose={onClose}>
      <View className='sheet'>
        <View className='sheet__header'>
          {onBack ? (
            <Text className='sheet__back' onClick={onBack}>‹</Text>
          ) : (
            <Text className='sheet__back sheet__back--placeholder' />
          )}
          <Text className='sheet__header-title'>{mineLabels.pwdTitle}</Text>
          <Text className='sheet__back sheet__back--placeholder' />
        </View>

        {canSms ? (
          <View className='pwd-tabs'>
            <Text
              className={`pwd-tabs__tab${mode === 'sms' ? ' pwd-tabs__tab--active' : ''}`}
              onClick={() => setMode('sms')}
            >
              {mineLabels.pwdModeSms}
            </Text>
            <Text
              className={`pwd-tabs__tab${mode === 'old' ? ' pwd-tabs__tab--active' : ''}`}
              onClick={() => setMode('old')}
            >
              {mineLabels.pwdModeOld}
            </Text>
          </View>
        ) : (
          <Text className='pwd__hint'>{mineLabels.pwdNoPhoneHint}</Text>
        )}

        {mode === 'sms' && canSms ? (
          <View className='form__item'>
            <Text className='form__label'>{mineLabels.fieldSmsCode}</Text>
            <Text className='pwd__hint'>{mineLabels.pwdBoundPhone(maskCnPhone(boundPhone))}</Text>
            <Text className='pwd__hint'>{mineLabels.pwdFirstSetHint}</Text>
            <View className='form__code-row'>
              <Input
                className='form__input form__code-input'
                type='number'
                maxlength={6}
                value={smsCode}
                placeholder={mineLabels.pwdCodePlaceholder}
                onInput={(e) => setSmsCode(e.detail.value)}
              />
              <Text
                className={`form__code-btn${sendDisabled ? ' form__code-btn--disabled' : ''}`}
                onClick={sendCode}
              >
                {countdown > 0 ? authLabels.login.resendAfter(countdown) : authLabels.login.sendCode}
              </Text>
            </View>
          </View>
        ) : (
          <View className='form__item'>
            <Text className='form__label'>{mineLabels.fieldOldPassword}</Text>
            <Input
              className='form__input'
              password
              value={oldPasswd}
              placeholder={mineLabels.pwdOldPlaceholder}
              onInput={(e) => setOldPasswd(e.detail.value)}
            />
          </View>
        )}

        <View className='form__item'>
          <Text className='form__label'>{mineLabels.fieldNewPassword}</Text>
          <Input
            className='form__input'
            password
            maxlength={20}
            value={newPasswd}
            placeholder={mineLabels.pwdNewPlaceholder}
            onInput={(e) => setNewPasswd(e.detail.value)}
          />
        </View>
        <View className='form__item'>
          <Text className='form__label'>{mineLabels.fieldConfirmPassword}</Text>
          <Input
            className='form__input'
            password
            maxlength={20}
            value={confirmPasswd}
            placeholder={mineLabels.pwdConfirmPlaceholder}
            onInput={(e) => setConfirmPasswd(e.detail.value)}
          />
        </View>

        {/* 弹层提交按钮：自绘主按钮（NutButton 在 RN 端样式丢失且 loading 图标崩溃，禁用） */}
        <View
          className={`sheet__submit${submitting ? ' sheet__submit--disabled' : ''}`}
          onClick={handleSubmit}
        >
          <Text className='sheet__submit-text'>{submitting ? mineLabels.pwdSubmitting : mineLabels.pwdSubmit}</Text>
        </View>
      </View>
    </Popup>
  )
}
