import { View, Text } from '@tarojs/components'
import type { FeedItem } from '@/types'
import Avatar from '@/components/Avatar'
import HitBadge from '@/components/HitBadge'
import LotteryTag from '@/components/LotteryTag'
import { getDimensionLabel } from '@/constants/lottery'
import { forumLabels } from '@/labels'
import { forumDetailLabels } from '@/labels/forumDetail'
import { formatTime } from '@/utils/formatTime'
import './index.css'

interface FeedPredictionCardProps {
  item: FeedItem
}

/** 信息流预测帖卡片：头像作者 + 标签行 + 标题（两行截断）+ 时间/评论/收藏（产品方案 §6.5） */
export default function FeedPredictionCard({ item }: FeedPredictionCardProps) {
  const author = item.nickName || forumDetailLabels.anonymous
  const title = item.title?.trim() || forumDetailLabels.noTitle
  const dimLabel = getDimensionLabel(item.planMode)

  return (
    <View className='feed-pred'>
      <View className='feed-pred__head'>
        <Avatar src={item.avatar} name={author} size={28} />
        <Text className='feed-pred__author'>{author}</Text>
        <View className='feed-pred__tags'>
          <Text className='feed-pred__tag feed-pred__tag--type'>{forumLabels.predictionTag}</Text>
          {dimLabel ? <Text className='feed-pred__tag feed-pred__tag--dim'>{dimLabel}</Text> : null}
          <LotteryTag code={item.lotteryCode} />
          <HitBadge hitFlag={item.hitFlag} />
        </View>
      </View>
      <Text className='feed-pred__title'>{title}</Text>
      <View className='feed-pred__foot'>
        <Text className='feed-pred__time'>{formatTime(item.createTime)}</Text>
        <Text className='feed-pred__stat'>评论 {item.commentNum || 0}</Text>
        <Text className='feed-pred__stat'>收藏 {item.collectNum || 0}</Text>
      </View>
    </View>
  )
}
