/** RN：画规图 PNG dataURL → 存系统相册（壳工程已集成 @react-native-camera-roll/camera-roll） */
import { CameraRoll } from '@react-native-camera-roll/camera-roll'

export async function savePngToDevice(dataUrl: string, _fileName: string): Promise<boolean> {
  try {
    await CameraRoll.save(dataUrl, { type: 'photo' })
    return true
  } catch {
    return false
  }
}
