/**
 * 实用工具标识（toolId）权威定义。
 * 与后端 GET /tool/list 下发的 toolId 一一对应，后端按此做权益档位 / 门控配置；
 * 前端一切工具权限数据（locked / lockReason / requiredLevel / sort）均以 toolId 为键消费。
 * 新增工具：在此登记 toolId，并同步后端权限配置，否则前端不识别。
 */
export const TOOL_ID = {
  /** 筛选工具 */
  FILTER: 'filter',
  /** 码组扩展工具 */
  CODE_GROUP_EXTENSION: 'code-group-extension',
  /** 历史回查工具（免费） */
  HISTORY_REVIEW: 'history-review',
  /** 集合处理工具 */
  SET_PROCESSING: 'set-processing',
  /** 画规工具 */
  DRAW_RULE: 'draw-rule',
} as const

export type ToolId = (typeof TOOL_ID)[keyof typeof TOOL_ID]

export const TOOL_IDS: readonly ToolId[] = Object.values(TOOL_ID)
