.free-mode {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.free-mode__range {
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 12px;
}

.free-mode__range-label {
  font-size: 13px;
  color: var(--color-text-secondary);
}

.free-panel {
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  overflow: hidden;
}

.free-panel__head {
  min-height: 44px;
  display: flex;
  flex-direction: row;
  align-items: center;
  padding: 0 12px;
  gap: 8px;
  background: var(--color-bg);
}

.free-panel__label {
  font-size: 14px;
  font-weight: 600;
  color: var(--color-text);
}

.free-panel__hint {
  flex: 1;
  font-size: 12px;
  color: var(--color-text-secondary);
}

.free-panel__hint--over {
  color: var(--color-danger);
}

.free-panel__arrow {
  font-size: 12px;
  color: var(--color-text-placeholder);
}

.free-panel__body {
  padding: 12px;
}

.free-panel__textarea {
  width: 100%;
  box-sizing: border-box;
  font-size: 14px;
  line-height: 1.6;
  color: var(--color-text);
  background: var(--color-bg-card);
}

.free-panel__textarea--base {
  min-height: 180px;
}

.free-panel__textarea--focus {
  min-height: 120px;
}

.free-panel__textarea--main {
  min-height: 72px;
}

.free-panel__error {
  display: block;
  margin-top: 8px;
  font-size: 12px;
  color: var(--color-danger);
}
