.member-page {
  min-height: 100vh;
  padding: 16px 16px 0;
  /* RN 端 var 不注入走 fallback，底部 24px + 安全区 */
  padding-bottom: var(--sa-24, calc(24px + env(safe-area-inset-bottom)));
  background: var(--color-bg);
}

/* 状态头卡：品牌红渐变（RN 端 background-image 被剥离，自动用兜底 background-color） */
.member-hero {
  padding: 24px;
  border-radius: var(--radius-md);
  background-color: #b83237;
  background-image: linear-gradient(135deg, #c23b40 0%, #9c272c 100%);
}

.member-hero__title {
  font-size: 18px;
  font-weight: 700;
  color: #fff;
}

.member-hero__status {
  display: block;
  margin-top: 8px;
  font-size: 13px;
  color: rgba(255, 255, 255, 0.82);
}

/* 休市顺延提示 */
.member-closure {
  display: block;
  margin-top: 12px;
  padding: 10px 14px;
  border-radius: var(--radius-sm);
  background: var(--color-primary-light);
  font-size: 12px;
  color: var(--color-primary);
}

/* 档位 Tab（参考修改密码弹层 pwd-tabs 分段控件） */
.member-tabs {
  margin-top: 16px;
  display: flex;
  flex-direction: row;
  padding: 3px;
  border-radius: 8px;
  background: var(--color-bg-card);
}

.member-tabs__tab {
  flex: 1;
  /* 触控目标 ≥44px（AGENTS.md 编码约定） */
  height: 44px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 6px;
}

.member-tabs__tab-text {
  font-size: 14px;
  color: var(--color-text-secondary);
}

.member-tabs__tab--active {
  background: var(--color-primary);
}

/* 激活态文字色直接挂在文本节点（RN 端不支持后代选择器改色） */
.member-tabs__tab-text--active {
  color: #fff;
}

/* SKU 列表区 */
.member-section {
  margin-top: 16px;
  padding: 16px;
  background: var(--color-bg-card);
  border-radius: var(--radius-md);
}

.member-section__note {
  display: block;
  margin-bottom: 12px;
  font-size: 11px;
  color: var(--color-text-placeholder);
}

/* SKU 卡片 */
.member-plan {
  padding: 16px;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  margin-bottom: 12px;
}

.member-plan__head {
  display: flex;
  flex-direction: row;
  align-items: center;
}

.member-plan__name {
  flex: 1;
  font-size: 15px;
  font-weight: 600;
}

.member-plan__period {
  font-size: 12px;
  color: var(--color-text-secondary);
}

.member-plan__price-row {
  margin-top: 8px;
  display: flex;
  flex-direction: row;
  align-items: center;
}

.member-plan__price {
  font-size: 20px;
  font-weight: 700;
  color: var(--color-primary);
}

.member-plan__original {
  margin-left: 8px;
  font-size: 12px;
  color: var(--color-text-placeholder);
  text-decoration: line-through;
}

.member-plan__integral {
  margin-left: 8px;
  font-size: 12px;
  color: var(--color-text-secondary);
}

.member-plan__remark {
  display: block;
  margin-top: 8px;
  font-size: 12px;
  color: var(--color-text-secondary);
}

.member-plan__foot {
  margin-top: 12px;
  display: flex;
  flex-direction: row;
  align-items: center;
}

.member-plan__days {
  flex: 1;
  font-size: 12px;
  color: var(--color-text-placeholder);
}

.member-plan__buy {
  min-height: 36px;
  padding: 0 20px;
  border-radius: 999px;
  background: var(--color-primary);
  display: flex;
  align-items: center;
  justify-content: center;
}

.member-plan__buy-text {
  font-size: 13px;
  color: #fff;
}

/* 确认订单弹层 */
.pay-sheet {
  padding: 24px;
  padding-bottom: var(--sa-24, calc(24px + env(safe-area-inset-bottom)));
}

.pay-sheet__title {
  display: block;
  margin-bottom: 20px;
  text-align: center;
  font-size: 17px;
  font-weight: 600;
}

.pay-sheet__row {
  display: flex;
  flex-direction: row;
  justify-content: space-between;
  align-items: center;
  min-height: 48px;
  border-bottom: 1px solid var(--color-border);
}

.pay-sheet__label {
  font-size: 14px;
  color: var(--color-text-secondary);
}

.pay-sheet__value {
  font-size: 14px;
  color: var(--color-text);
}

.pay-sheet__price {
  font-size: 18px;
  font-weight: 700;
  color: var(--color-primary);
}

/* 支付动作按钮：自绘（NutButton 在 RN 端样式丢失且 loading 图标崩溃，禁用） */
.pay-sheet__action {
  margin-top: 16px;
  min-height: 46px;
  padding: 6px 16px;
  border-radius: 23px;
  border: 1px solid var(--color-border);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
}

.pay-sheet__action--primary {
  background: var(--color-primary);
  border-color: var(--color-primary);
}

.pay-sheet__action--disabled {
  opacity: 0.6;
}

.pay-sheet__action-text {
  font-size: 15px;
  color: var(--color-text);
}

.pay-sheet__action-text--primary {
  font-weight: 600;
  color: #fff;
}

/* 积分支付按钮内的余额副行（主按钮白字场景） */
.pay-sheet__action-sub {
  margin-top: 2px;
  font-size: 11px;
  color: rgba(255, 255, 255, 0.82);
}
