import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import { View, Text } from '@tarojs/components'
import Taro from '@tarojs/taro'
import Popup from '@/components/SheetPopup'
import { useAuth, redirectToLogin } from '@/store/auth'
import { createPayOrder, fetchMemberPlans, fetchUserIntegral } from '@/services/api'
import type { MemberPlanSku, MemberPlansPage } from '@/types'
import { currentRoute } from '@/utils/nav'
import { runCashPay } from '@/utils/pay'
import CashPayButtons, { CashChannel } from '@/components/pay/CashPayButtons'
import { mineLabels } from '@/labels/mine'
import Empty from '@/components/Empty'
import Skeleton from '@/components/Skeleton'
import './index.css'

/**
 * 会员中心（购买页）：状态头卡 + 档位 Tab + SKU 列表 + 确认订单弹层。
 * 购买链路：/member/plans → /pay/create → 渠道支付 → /pay/query 轮询至 PAID（编排见 @/utils/pay runCashPay）。
 * - bizType=MEMBER_SUBSCRIPTION，bizId=planId；金额由后端定价，前端不传。
 * - 渠道按钮组（协议勾选/不退款提示/MOCK 追加）见 @/components/pay/CashPayButtons。
 * - 积分渠道 INTEGRAL 为同步事务（成功即 PAID 并发放权益），无需轮询。
 * - 合规：支付前必须勾选《会员服务协议》，并展示虚拟商品不退款提示（PRD §9.2）。
 */

export default function MemberPage() {
  const { isLoggedIn, refreshProfile } = useAuth()

  const [page, setPage] = useState<MemberPlansPage | null>(null)
  const [loading, setLoading] = useState(true)

  // 确认订单弹层：非 null 即打开
  const [payPlan, setPayPlan] = useState<MemberPlanSku | null>(null)
  const [paying, setPaying] = useState(false)
  // ref 锁：state 闭包在同一 commit 帧内双击会双过守卫，同步置位防重复下单
  const payingRef = useRef(false)
  // 《会员服务协议》勾选（PRD §9.2 强制）：每次打开弹层重置
  const [agreed, setAgreed] = useState(false)
  // 积分余额：打开确认弹层时拉取，用于积分支付按钮的余额展示与不足禁用
  const [integralBalance, setIntegralBalance] = useState<number | null>(null)

  const loadPlans = useCallback(async () => {
    try {
      setPage(await fetchMemberPlans())
    } catch {
      setPage(null)
    } finally {
      setLoading(false)
    }
  }, [])

  useEffect(() => {
    loadPlans()
  }, [loadPlans])

  /** 按档位分组（保持 sort 升序顺序，组序按首次出现），档位作为 Tab */
  const groups = useMemo(() => {
    const map = new Map<string, MemberPlanSku[]>()
    for (const plan of page?.plans || []) {
      const list = map.get(plan.planLevel) || []
      list.push(plan)
      map.set(plan.planLevel, list)
    }
    return Array.from(map.entries())
  }, [page])

  // 当前选中的档位 Tab：默认第一组；activeLevel 失效（接口数据变化）时回落第一组
  const [activeLevel, setActiveLevel] = useState('')
  const levels = groups.map(([level]) => level)
  const currentLevel = levels.includes(activeLevel) ? activeLevel : levels[0] || ''
  const currentPlans = groups.find(([level]) => level === currentLevel)?.[1] || []

  const handleBuy = (plan: MemberPlanSku) => {
    if (!isLoggedIn) {
      redirectToLogin(currentRoute())
      return
    }
    setIntegralBalance(null)
    setAgreed(false)
    setPayPlan(plan)
    // 拉取积分余额（失败不阻塞，按钮退化为不展示余额、由后端校验兜底）
    fetchUserIntegral()
      .then((res) => {
        // 接口缺 data 时 value 为空串，Number('')===0 会把余额伪造成 0，需归位 null 走兜底
        const raw = String(res?.value ?? '').trim()
        const value = raw ? Number(raw) : NaN
        setIntegralBalance(Number.isFinite(value) ? value : null)
      })
      .catch(() => setIntegralBalance(null))
  }

  /** 积分不足以支付当前选中套餐（余额未加载时不禁用，由后端校验兜底） */
  const integralInsufficient =
    payPlan != null && integralBalance != null && integralBalance < payPlan.integralPrice

  /** 现金渠道：下单 → 拉起渠道支付 → 轮询 /pay/query 至 PAID（编排与文案见 @/utils/pay） */
  const handleCashPay = async (channel: CashChannel) => {
    if (!payPlan || payingRef.current) return
    payingRef.current = true
    setPaying(true)
    try {
      const paid = await runCashPay({
        bizType: 'MEMBER_SUBSCRIPTION',
        bizId: payPlan.planId,
        channel,
        labels: {
          polling: mineLabels.memberPayPolling,
          success: mineLabels.memberPaySuccess,
          confirming: mineLabels.memberPayConfirming,
          closed: mineLabels.memberPayClosed,
          fail: mineLabels.memberPayFail,
          launchFail: mineLabels.memberPayLaunchFail,
        },
      })
      if (paid) {
        setPayPlan(null)
        // 同步刷新会员状态（profile.memberFlag/有效期）与购买页（剩余天数/档位）
        refreshProfile()
        loadPlans()
      }
    } finally {
      payingRef.current = false
      setPaying(false)
    }
  }

  /** 积分支付：同步事务，后端校验余额 → 原子扣减 → 订单置 PAID → 发放权益，无需轮询 */
  const handleIntegralPay = async () => {
    if (!payPlan || payingRef.current || integralInsufficient || !agreed) return
    payingRef.current = true
    setPaying(true)
    try {
      const order = await createPayOrder({
        bizId: payPlan.planId,
        bizType: 'MEMBER_SUBSCRIPTION',
        channel: 'INTEGRAL',
      })
      if (String(order?.status || '').toUpperCase() === 'PAID') {
        setPayPlan(null)
        Taro.showToast({ title: mineLabels.memberPaySuccess, icon: 'success' })
        // 同步刷新会员状态（profile.memberFlag/有效期）与购买页（剩余天数/档位）
        refreshProfile()
        loadPlans()
      } else {
        Taro.showToast({ title: mineLabels.memberPayConfirming, icon: 'none' })
      }
    } catch (error: any) {
      // 余额不足等后端业务错误信息原样透出
      Taro.showToast({ title: error?.message || mineLabels.memberPayFail, icon: 'none' })
    } finally {
      payingRef.current = false
      setPaying(false)
    }
  }

  const statusText =
    isLoggedIn && page?.memberLevel && page.daysRemaining != null
      ? mineLabels.memberStatusActive(mineLabels.memberLevelLabel(page.memberLevel), page.daysRemaining)
      : isLoggedIn
        ? mineLabels.memberStatusNone
        : mineLabels.memberGuestHint

  return (
    <View className='member-page'>
      {/* 状态头卡：品牌红渐变（background-color 兜底 + background-image，RN 端自动用兜底色） */}
      <View className='member-hero'>
        <Text className='member-hero__title'>{mineLabels.memberCenter}</Text>
        <Text className='member-hero__status'>{statusText}</Text>
      </View>

      {page?.closureTip ? <Text className='member-closure'>{page.closureTip}</Text> : null}

      {loading ? (
        <View className='member-section'>
          <Skeleton rows={3} card={false} />
        </View>
      ) : groups.length > 0 ? (
        <>
          {/* 档位 Tab（参考修改密码弹层 pwd-tabs 分段控件） */}
          {levels.length > 1 ? (
            <View className='member-tabs'>
              {levels.map((level) => (
                <View
                  key={level}
                  className={`member-tabs__tab${level === currentLevel ? ' member-tabs__tab--active' : ''}`}
                  onClick={() => setActiveLevel(level)}
                >
                  <Text className={`member-tabs__tab-text${level === currentLevel ? ' member-tabs__tab-text--active' : ''}`}>
                    {mineLabels.memberLevelLabel(level)}
                  </Text>
                </View>
              ))}
            </View>
          ) : null}
          <View className='member-section'>
            {currentLevel === 'TIER_2' && page?.dataFactoryLaunchNote ? (
              <Text className='member-section__note'>{page.dataFactoryLaunchNote}</Text>
            ) : null}
            {currentPlans.map((plan) => (
              <View key={plan.planId} className='member-plan'>
                <View className='member-plan__head'>
                  <Text className='member-plan__name'>{plan.displayName}</Text>
                  <Text className='member-plan__period'>{mineLabels.memberPeriodLabel(plan.period)}</Text>
                </View>
                <View className='member-plan__price-row'>
                  <Text className='member-plan__price'>{mineLabels.memberPrice(plan.price)}</Text>
                  {plan.originalPrice > plan.price ? (
                    <Text className='member-plan__original'>{mineLabels.memberPrice(plan.originalPrice)}</Text>
                  ) : null}
                  {plan.integralPrice > 0 ? (
                    <Text className='member-plan__integral'>{mineLabels.memberIntegralPrice(plan.integralPrice)}</Text>
                  ) : null}
                </View>
                {plan.remark ? <Text className='member-plan__remark'>{plan.remark}</Text> : null}
                <View className='member-plan__foot'>
                  <Text className='member-plan__days'>{mineLabels.memberDays(plan.days)}</Text>
                  <View className='member-plan__buy' onClick={() => handleBuy(plan)}>
                    <Text className='member-plan__buy-text'>{mineLabels.memberBuy}</Text>
                  </View>
                </View>
              </View>
            ))}
          </View>
        </>
      ) : (
        <Empty text={mineLabels.memberPlansEmpty} />
      )}

      {/* 确认订单弹层（关闭即销毁子节点，选中套餐状态提升在页面级 payPlan） */}
      <Popup visible={!!payPlan} onClose={() => setPayPlan(null)}>
        {payPlan ? (
          <View className='pay-sheet'>
            <Text className='pay-sheet__title'>{mineLabels.memberPayTitle}</Text>
            <View className='pay-sheet__row'>
              <Text className='pay-sheet__label'>{mineLabels.memberPayPlanLabel}</Text>
              <Text className='pay-sheet__value'>{payPlan.displayName}</Text>
            </View>
            <View className='pay-sheet__row'>
              <Text className='pay-sheet__label'>{mineLabels.memberPayAmountLabel}</Text>
              <Text className='pay-sheet__price'>{mineLabels.memberPrice(payPlan.price)}</Text>
            </View>
            {/* 协议勾选 + 不退款提示 + 渠道按钮组（自绘按钮；积分支付作为业务按钮插入现金渠道之前） */}
            <CashPayButtons
              price={payPlan.price}
              paying={paying}
              agreed={agreed}
              onAgreeChange={setAgreed}
              noRefundHint={mineLabels.memberPayNoRefund}
              onPay={handleCashPay}
            >
              {payPlan.integralPrice > 0 ? (
                <View
                  className={`pay-sheet__action pay-sheet__action--primary${paying || integralInsufficient || !agreed ? ' pay-sheet__action--disabled' : ''}`}
                  onClick={handleIntegralPay}
                >
                  <Text className='pay-sheet__action-text pay-sheet__action-text--primary'>
                    {paying ? mineLabels.memberPaySubmitting : mineLabels.memberPayIntegral(payPlan.integralPrice)}
                  </Text>
                  {integralBalance != null ? (
                    <Text className='pay-sheet__action-sub'>
                      {mineLabels.memberPayIntegralBalance(integralBalance)}
                      {integralInsufficient ? ` · ${mineLabels.memberPayIntegralInsufficient}` : ''}
                    </Text>
                  ) : null}
                </View>
              ) : null}
            </CashPayButtons>
          </View>
        ) : null}
      </Popup>
    </View>
  )
}
